# ── Typo-tolerant insurance vocabulary ──────────────────────────────────────────
# Correctly-spelled insurance-domain terms used by _correct_typos() to
# fix common typos before vector retrieval.
_INSURANCE_VOCAB = [
    "insurance", "policy", "premium", "deductible", "coverage", "claim", "claims",
    "insured", "insurer", "insurers", "underwriting", "underwrite", "renewal", "nominee",
    "beneficiary", "cashless", "reimbursement", "rider", "liability", "copay",
    "endorsement", "subrogation", "exclusion", "maturity", "surrender",
    "vehicle", "comprehensive", "third party", "cover", "covered", "co-pay",
    "deductibles", "premiums", "health", "medical", "hospital", "surgery",
    "prescription", "medication", "accident", "disability", "critical illness",
    "maternity", "dental", "vision", "agent", "broker", "benefit", "benefits",
    "term life", "whole life", "endowment", "annuity", "pension", "retirement",
    "investment", "savings", "finance", "financial", "limit", "limits",
    "no-claim bonus", "sum insured", "sum assured", "grace period",
    "waiting period", "free look period", "cancellation", "protection",
    "calculation", "formula", "amount", "documents", "process", "settlement",
]

# Ordinary English words that fuzzy-match an _INSURANCE_VOCAB entry above
# the 85 threshold but are never actually a typo of it — raising the
# threshold from 80 to 85 (see _correct_typos) closed off the "detail" ->
# "dental" class of false positive, but a systematic scan of the top
# 10,000 most common English words turned up 19 more words that still
# score >=85, in the same range as genuine typos ("nominie" -> "nominee"
# also scores 85.7), so no threshold value can separate them from real
# typo-correction coverage. These are hand-verified as real, common
# words that would never legitimately need fixing to the paired vocab
# term, and are excluded outright before the fuzzy match ever runs.
# Worst cases if left unprotected: "injured" -> "insured" (opposite-ish
# meaning, and "injured" is one of the most common words in accident/
# health queries), "requirement" -> "retirement" (silently redirects an
# eligibility question into unrelated retirement-planning content),
# "description" -> "prescription", "copy" -> "copay". A few borderline
# scan hits ("heath" -> "health", "accent" -> "accident", "cove" ->
# "cover") were deliberately left OUT of this set: in an insurance-chat
# context a typo is far more likely than the literal rare word, so
# correction is still the right default for those three.
_TYPO_CORRECTION_PROTECTED_WORDS = frozenset({
    "injured", "requirement", "requirements", "description", "descriptions",
    "copy", "copies", "converted", "convert", "projection", "projections",
    "beneficial", "renewable", "document", "ride", "rides", "saving",
    "broke", "protecting", "tension", "meditation", "calculator",
})


# ── Casual greetings (fuzzy-matched) ─────────────────────────────────────────────
_CASUAL_GREETINGS = frozenset({
    "hi", "hello", "hey", "yo", "sup", "what's up", "whats up",
    "good morning", "good evening", "good afternoon",
    "howdy", "hiya", "dude", "bro", "hii", "heya",
})


# Common prefixes that turn a vocab word into a distinct compound insurance
# term (re+insurance, co+insurance, un+insured, under+insured, over+insurance,
# non+insurance). Users often type these with a space or hyphen instead of
# joined — "re insurance" / "re-insurance" — which changes nothing for a
# human reader but is a different token for retrieval than the corpus's
# actual joined spelling. _join_split_compounds() below re-joins them.
_COMPOUND_PREFIXES = ("re", "co", "un", "under", "over", "non")
_COMPOUND_PREFIX_RE = re.compile(
    r'\b(' + '|'.join(_COMPOUND_PREFIXES) + r')[\s-]+(\w{4,})\b',
    re.IGNORECASE,
)

# The only roots that actually form a real compound word with one of the
# prefixes above. Deliberately NOT the full _INSURANCE_VOCAB — that was
# the bug: matching against all 40+ vocab entries meant ANY of them
# following "under"/"re"/"co"/etc. got silently glued together, including
# words that don't form a real compound at all. Confirmed live: "covered
# under health insurance" got rewritten to "covered underhealth
# insurance" — "health" is a legitimate vocab entry on its own, but
# "underhealth" isn't a word, and the garbled query made retrieval
# unreliable (intermittent reranker-gate refusals on a question the KB
# answers fine). Same failure shape as "reinsurance" -> "insurance" in
# _correct_typos below: a broad match target catching real domain words
# that happen to sit near a prefix, not just genuine split compounds.
_COMPOUND_ROOTS = ["insurance", "insured", "insurer", "writing", "write"]


def _join_split_compounds(text: str) -> str:
    """Re-join a compound prefix ("re", "co", "un", "under", "over", "non")
    that was typed with a space or hyphen before a word matching a
    _COMPOUND_ROOTS entry — "re insurance" / "re-insurance" -> "reinsurance",
    "under insured" -> "underinsured" — so retrieval sees the same single
    token the knowledge base actually uses, instead of two separate ones.

    Only joins when the word after the prefix fuzzy-matches one of the
    small set of roots that actually form a real compound (score >= 85 —
    see _correct_typos for why this was raised from 80) — NOT the full
    insurance vocabulary, which would match ordinary domain words that
    happen to follow a prefix without forming any real compound term
    ("under health" is not "underhealth"). An unrelated word right after
    "re"/"co"/etc. ("re apply") is left untouched either way.
    """
    def _try_join(m: re.Match) -> str:
        prefix, rest = m.group(1), m.group(2)
        if rest.lower() in _TYPO_CORRECTION_PROTECTED_WORDS:
            return m.group(0)
        result = process.extractOne(rest, _COMPOUND_ROOTS, scorer=fuzz.ratio)
        if result is not None:
            best_match, score, _ = result
            if score >= 85:
                return f"{prefix.lower()}{best_match}"
        return m.group(0)

    return _COMPOUND_PREFIX_RE.sub(_try_join, text)


def _correct_typos(text: str) -> str:
    """Fix common typos in insurance-domain terms using fuzzy matching.

    Splits *text* into words. For each word of length >= 4, finds the best
    match in ``_INSURANCE_VOCAB`` using ``rapidfuzz`` with ``fuzz.ratio``.
    If the best match score >= 85 and is not already exact, replaces the
    word with the correctly-spelled vocabulary term. Returns the corrected
    sentence with original word order preserved.

    Skips the correction when the matched vocab word is fully contained
    inside a *longer* candidate word (e.g. "insurance" inside
    "reinsurance") — that's a legitimate compound/prefixed domain term
    built on top of the vocab word, not a misspelling of it. A real typo
    is a substitution/transposition/omission that stays roughly the same
    length as the intended word ("deductable" -> "deductible"); it doesn't
    cleanly embed a complete shorter word plus extra characters. Without
    this guard, "reinsurance" scores 90 against "insurance" (they share
    it as a substring) and gets silently rewritten to "insurance" before
    retrieval ever runs — and the same happens to "coinsurance",
    "uninsured", "underinsured", etc. against "insurance"/"insured". This
    check generalizes the fix so every such compound survives untouched
    without having to hand-list each one in the vocab.

    Also skips the reverse shape: a complete, shorter candidate word that
    happens to be the tail end of a longer vocab word with one short
    prefix chopped off — e.g. "over" scores 89 against "cover" (drop the
    leading "c" and they're identical) and would otherwise get "corrected"
    into "cover" any time it appears in an ordinary sentence ("what happens
    over the policy term"). Real typos almost never drop exactly the
    leading character(s) of a word; that's specifically the shape of an
    unrelated, independently-valid short word.

    Threshold raised 80 -> 85 after finding this was silently corrupting
    ordinary English words that happen to be near-neighbors of a vocab
    term, with no unusual-shape guard able to catch it since these are
    same-length substitutions, structurally identical to a real typo.
    Confirmed live: "explain fire insurance in detail" retrieved as
    "...in dental" (score 83.3 against "dental") and returned a flat "not
    in my knowledge base" refusal for a topic the KB actually covers well
    — silently corrupted before retrieval ever ran, so nothing downstream
    had a chance to catch it. A vocabulary scan turned up "company" ->
    "copay" (83.3) and "order" -> "rider" (80.0) as the same class of
    false positive. Every genuine typo this function is meant to catch
    ("deductable", "insurence", "premiu", "materinty", "hospitl", ...)
    scored 85.7 or higher in the same scan, so 85 cleanly separates real
    typos from coincidental collisions with common English words without
    losing any tested correction case.
    """
    text = _join_split_compounds(text)
    words = text.split()
    corrected = []
    for w in words:
        stripped = w.strip(".,!?;:()[]{}'\"")
        if len(stripped) >= 4 and stripped.lower() not in _TYPO_CORRECTION_PROTECTED_WORDS:
            result = process.extractOne(stripped, _INSURANCE_VOCAB, scorer=fuzz.ratio)
            if result is not None:
                best_match, score, _ = result
                stripped_lower = stripped.lower()
                best_match_lower = best_match.lower()
                is_compound_extension = (
                    len(stripped) > len(best_match)
                    and best_match_lower in stripped_lower
                )
                is_truncated_vocab_word = (
                    len(best_match) > len(stripped)
                    and best_match_lower.endswith(stripped_lower)
                )
                if (score >= 85 and best_match != stripped
                        and not is_compound_extension and not is_truncated_vocab_word):
                    prefix = w[:len(w) - len(w.lstrip(".,!?;:()[]{}'\""))]
                    suffix = w[len(w.rstrip(".,!?;:()[]{}'\"") or len(w)):]
                    corrected.append(f"{prefix}{best_match}{suffix}")
                    continue
        corrected.append(w)
    return " ".join(corrected)


# Bidirectional abbreviation <-> full-term expansion, appended to (never
# replacing) the retrieval query — confirmed live (2026-07-13): a KB
# document titled "Major Insurance Brokers in the GCC" ranked BELOW an
# unrelated, generic PDF when the user asked about "the Gulf Cooperation
# Council" instead of "GCC". The document's own text only ever uses the
# abbreviation, so a query using the spelled-out form has no lexical
# match against it at all — embedding similarity alone wasn't enough to
# keep it top-ranked against exact-term competition elsewhere in the KB.
# Appending the counterpart form (in whichever direction the query used)
# gives retrieval a lexical match against source documents that only
# ever use one form or the other. Appending rather than substituting
# keeps the original query intact for every other check downstream
# (lexical coverage, grounding, KV cache key) — this only adds extra
# surface area for the vector/hybrid search to match against.
_ABBREVIATION_EXPANSIONS = {
    "gcc": "gulf cooperation council",
    "uae": "united arab emirates",
    "ksa": "kingdom of saudi arabia",
    "irdai": "insurance regulatory and development authority of india",
    # Not a regional abbreviation like the others above, but the exact same
    # failure shape: confirmed live, "copay" (a valid, common colloquial
    # spelling — already in _INSURANCE_VOCAB, so _correct_typos correctly
    # leaves it alone, there's no typo to fix) scores meaningfully lower
    # against the KB's own "Co-payment" chunk than the KB's own spelling
    # does (0.57 vs 0.76 cosine similarity, direct comparison tested) —
    # embedding similarity alone wasn't enough to keep that chunk
    # competitive against other chunks scoring well on an "example"-shaped
    # query. Appending the KB's own spelling gives retrieval a matching
    # form to latch onto without touching the user's original wording.
    "copay": "co-payment",
}
_ABBREVIATION_RE = re.compile(
    r'\b(' + '|'.join(re.escape(k) for k in _ABBREVIATION_EXPANSIONS) + r')\b',
    re.IGNORECASE,
)
_EXPANSION_TO_ABBR = {v: k.upper() for k, v in _ABBREVIATION_EXPANSIONS.items()}
_EXPANSION_RE = re.compile(
    r'\b(' + '|'.join(re.escape(v) for v in _ABBREVIATION_EXPANSIONS.values()) + r')\b',
    re.IGNORECASE,
)


def _expand_abbreviations(text: str) -> str:
    """Append the counterpart form (abbreviation <-> spelled-out term) for
    any known regional/regulatory term found in *text*, so retrieval
    matches KB documents using either form. New abbreviations can be added
    to _ABBREVIATION_EXPANSIONS as they're found to matter for documents
    actually in the KB — this isn't meant to be an exhaustive dictionary,
    just a targeted fix for the specific class of mismatch confirmed live.
    """
    additions = []
    for m in _ABBREVIATION_RE.finditer(text):
        full = _ABBREVIATION_EXPANSIONS[m.group(1).lower()]
        if full not in additions:
            additions.append(full)
    for m in _EXPANSION_RE.finditer(text):
        abbr = _EXPANSION_TO_ABBR[m.group(1).lower()]
        if abbr not in additions:
            additions.append(abbr)
    if not additions:
        return text
    return text + " " + " ".join(additions)


# ── Context coverage check ────────────────────────────────────────────────────
# Domain-generic terms that appear in virtually every insurance chunk and
# therefore give no signal about whether a chunk covers the specific query topic.
_QUERY_STOP_WORDS = {
    # English function words
    'what', 'is', 'are', 'the', 'a', 'an', 'in', 'of', 'for', 'how', 'does',
    'do', 'i', 'my', 'me', 'by', 'with', 'under', 'about', 'can', 'will',
    'which', 'when', 'where', 'to', 'and', 'or', 'at', 'this', 'that', 'it',
    'its', 'be', 'been', 'has', 'have', 'had', 'any', 'all', 'from', 'on',
    # Conversational intent words — appear in questions but never in KB chunks
    'tell', 'you', 'your', 'give', 'explain', 'know', 'say', 'get', 'let',
    'show', 'help', 'talk', 'discuss', 'find', 'see', 'our', 'their', 'use',
    'used', 'using', 'work', 'works', 'mean', 'means', 'please', 'want',
    'need', 'like', 'just', 'also', 'more', 'some', 'very', 'well', 'good',
    'different', 'types', 'type', 'kind', 'kinds', 'various', 'general',
    'basic', 'main', 'key', 'between', 'difference', 'example', 'examples',
    # Answer-style/format requests — ask HOW to phrase the answer, never
    # appear as literal words inside actual KB content (no policy document
    # says "explain in simple words"). Reformulated follow-ups like "explain
    # it in simple words" or "give me an example" fold these into the
    # retrieval query, and requiring them to co-occur with the real topic
    # in a source chunk always fails regardless of whether the topic itself
    # is genuinely covered.
    'simple', 'simply', 'definition', 'define', 'detail', 'detailed',
    'briefly', 'brief', 'short', 'layman', 'easy', 'explanation',
    'language', 'words', 'scenario', 'illustration', 'instance',
    # Generic quality/selection words — appear in virtually every insurance doc
    # so they cannot indicate topic coverage (e.g. "best coverage", "choose a plan")
    'best', 'top', 'great', 'better', 'right', 'ideal', 'suitable', 'suited',
    'choose', 'choosing', 'select', 'selecting', 'pick', 'decide', 'deciding',
    'compare', 'comparing', 'recommend', 'recommended', 'important', 'affordable',
    'option', 'options', 'available', 'offer', 'offers', 'provide', 'provides',
    # Domain-generic insurance terms that appear in almost every chunk
    'insurance', 'insured', 'insurer', 'policy', 'policies', 'cover', 'coverage',
    'plan', 'claim', 'claims', 'benefits', 'benefit',
    # Generic time/measurement words — too common to indicate topic coverage
    'period', 'time', 'duration', 'date', 'days', 'year', 'month', 'months',
}

def _extract_topic_terms(query: str) -> set[str]:
    """Return discriminating topic words from a query after stop-word filtering."""
    stop = _QUERY_STOP_WORDS
    return {
        w for w in re.findall(r'\b[a-z]{3,}\b', query.lower())
        if not _is_stopword(w, stop)
    }


def _word_matches(topic: str, chunk_word: str) -> bool:
    """True if topic and chunk_word are the same root.

    Uses a 5-character shared-prefix heuristic to handle common inflections
    without a full stemmer, e.g.:
      "deductible" / "deduction" / "deducted"  → share "deduct" ✓
      "nominate"   / "nomination"               → share "nomin"  ✓
      "tax"        / "taxation"                 → share "tax"    ✓ (exact)

    Short topic words (< 5 chars, e.g. "term") never reach that prefix
    heuristic, so they only ever match an EXACT identical word. Tried adding
    a blanket trailing-"s" plural/singular rule to fix "term" vs "terms" —
    reverted immediately: it let the topic "term insurance" pass on any
    chunk containing the word "terms" in the totally unrelated sense of
    "terms and conditions" (a near-universal phrase in every insurance
    document, present on almost every page regardless of topic). Confirmed
    live: this let a term-insurance claim question answer confidently using
    retrieved MOTOR insurance claims content (driving license, FIR for
    vehicle theft) — a wrong-topic answer, strictly worse than the refusal
    it replaced. Exactly the "weak rider smuggles the query through" failure
    mode already documented below for the no-claim-bonus case, just via
    grammatical number instead of a generic rider word. A safe fix for the
    "term"/"terms" case needs to be specific to that word pair (or require
    the plural to appear near "insurance"/"policy" specifically), not a
    general suffix rule — left as future work rather than shipping this.
    """
    if topic == chunk_word:
        return True
    # Require at least 5 chars in both to avoid spurious short-word matches
    min_len = 5
    prefix = min(len(topic), len(chunk_word), min_len)
    return prefix >= min_len and topic[:prefix] == chunk_word[:prefix]


def _is_stopword(word: str, stop: set[str]) -> bool:
    """True if word is (or shares a root with) an entry in the stopword set.

    A hand/LLM-curated list only ever lists one inflection ("insurer") and
    silently misses others ("insurers"). Since that missed plural is common
    enough to appear in almost every KB chunk, it then slips through the
    coverage-check gate as if it were a topic-specific word, letting the LLM
    "confirm" a query that isn't actually covered by the KB. Root-matching
    against the stopword set closes this gap without hand-listing every form.
    """
    if word in stop:
        return True
    return any(_word_matches(word, s) for s in stop)


def _topics_hit_chunk(topics: set, chunk_terms: set) -> bool:
    """True if any topic word matches (exactly or by root prefix) any chunk term."""
    # Fast exact intersection first
    if topics & chunk_terms:
        return True
    # Stem-based fallback for inflection mismatches
    for t in topics:
        for c in chunk_terms:
            if _word_matches(t, c):
                return True
    return False


# Splits a compound query on "and"/"or" only when a question-word/aux-verb
# immediately follows — see the regex-fallback branch of
# _context_covers_query() for why a bare split on every "and" is wrong.
_COMPOUND_SPLIT = re.compile(
    r'\b(?:and|or)\s+(?=(?:what|who|which|how|why|when|where|is|are|'
    r'does|do|can|could|should|will|would|was|were)\b)',
    re.IGNORECASE,
)


def _context_covers_query(query: str, docs: list, llm_topics: set | None = None) -> bool:
    """True if >=1 retrieved chunk contains at least one topic keyword (root-aware).

    When llm_topics is provided, checks that every topic word appears in at
    least one retrieved chunk (distributed coverage across chunks). This is
    intentionally lenient: the LLM receives all chunks as context, so info
    spread across chunks is still usable. The only hard block is when a
    specific term (e.g. 'IDV', 'no-claim bonus') doesn't appear ANYWHERE in
    the retrieved pool, which reliably indicates the KB has no relevant content.

    Falls back to regex (OR logic) when llm_topics is absent.
    """
    if llm_topics:
        # Excludes chunks matching _REGULATORY_BOILERPLATE_RE from this max —
        # confirmed live via the hollow-answer investigation: "my claim got
        # rejected, what do I do" retrieved a regulatory/supervisory chunk
        # about IRDA's grievance-redressal and inter-party dispute-
        # adjudication framework that scored highly enough on lexical
        # similarity ("claim", "dispute") to trip the single_topic bypass
        # below on its own, letting a chunk that doesn't actually answer a
        # consumer's "why was MY claim rejected" question vouch for
        # coverage. The model then had nothing real to draw from and
        # produced a near-empty answer that technically passed every rule
        # but helped no one (see the hollow-answer detector further down —
        # that catches the SYMPTOM after generation; this is the same
        # underlying cause, caught before generation runs at all). A
        # boilerplate chunk can still be used as regular CONTEXT if it's
        # not the only thing available — this only stops it from being the
        # sole justification for skipping the stricter per-topic check.
        top_rerank = max(
            (
                d.metadata.get("rerank_score", 0) for d in docs
                if hasattr(d, "metadata")
                and not _REGULATORY_BOILERPLATE_RE.search((getattr(d, "page_content", "") or "").lower())
            ),
            default=0,
        )
        stop = _QUERY_STOP_WORDS
        topic_word_lists = []
        for topic in llm_topics:
            words = [w for w in topic.replace('-', ' ').split() if len(w) >= 3 and not _is_stopword(w, stop)]
            if words:
                topic_word_lists.append(words)

        # Score-based rescues (the 0.5 full-bypass below and the 0.05
        # lexical-miss fallback further down) are only safe for single-topic
        # questions. top_rerank is the SINGLE best score across ALL chunks —
        # for a compound question ("X and Y"), a high score usually just
        # means ONE part matched well, and applying it question-wide lets
        # that one strong match vouch for a completely unrelated other part.
        # Measured: "what is a deductible and what is the GST rate on
        # insurance premiums" scored 0.53 purely from the deductible half,
        # bypassing this check entirely and letting the model invent a
        # specific GST percentage that appears nowhere in the KB. For
        # multi-topic questions, every topic must pass the strict per-chunk
        # lexical check below — no score-based rescue.
        single_topic = len(topic_word_lists) <= 1

        # Only bypass keyword coverage check when the cross-encoder is *highly*
        # confident the chunk is relevant. The reranker (BAAI/bge-reranker-base
        # via sentence-transformers CrossEncoder) is sigmoid-activated, so
        # scores are bounded probabilities in [0, 1], NOT raw unbounded
        # logits — empirically: unrelated content ≈ 0.0000, marginally-topical
        # content ≈ 0.01-0.16, genuinely on-topic ≈ 0.3-0.5+, near-certain
        # matches ≈ 0.9+. A stale threshold of 4.0 here was calibrated for
        # raw logits and was literally unreachable (scores can't exceed 1.0),
        # silently making this bypass permanently dead code.
        if single_topic and top_rerank >= 0.5:
            return True

        # Require EVERY extracted topic to be covered (AND-logic), not just
        # one via OR-logic. The LLM extracts several "Specific" topics per
        # question, but many are weak riders that survive stopword-filtering
        # down to one common word — e.g. "motor insurance" -> "motor",
        # "health insurance" -> "health", or a country name like "india" —
        # which trivially matches almost any chunk in that domain. Under
        # plain OR-logic, a query like "what is a no-claim bonus" (topics:
        # "no-claim bonus", "motor insurance", "premiums") passed because
        # "motor" and "premiums" matched SOMETHING, even though the actual
        # distinguishing term "bonus" never appeared anywhere — the KB
        # genuinely doesn't define NCB, but a weak rider smuggled the query
        # through. An earlier attempt to fix this by checking only the
        # "most specific" (longest) topic broke when several topics tied
        # for length (e.g. "india", "health", "portability" are all single
        # words after filtering) — the arbitrary tie-break could pick the
        # weak rider instead of the real term. Requiring ALL topics to pass
        # removes the ambiguity: a weak rider passing no longer matters if
        # the real term still fails.
        #
        # Each topic's words must co-occur within a SINGLE chunk (not be
        # scattered independently across the whole retrieved pool — "zero"
        # in one unrelated chunk and "depreciation" in another otherwise
        # satisfied "zero depreciation" even though no chunk ever discussed
        # the concept as a unit) — but different topics may be satisfied by
        # different chunks, since the LLM sees the union of all of them.
        if topic_word_lists:
            chunk_term_sets = []
            for doc in docs:
                text = (
                    doc.page_content if hasattr(doc, 'page_content') else doc.get('text', '')
                ).lower()
                chunk_term_sets.append(set(re.findall(r'\b[a-z]{3,}\b', text)))
            all_topics_covered = all(
                any(
                    all(any(_word_matches(w, c) for c in chunk_terms) for w in words)
                    for chunk_terms in chunk_term_sets
                )
                for words in topic_word_lists
            )
            if all_topics_covered:
                return True

        # Lexical matching (even root-aware, even per-chunk) structurally
        # can't handle true synonyms — "claim rejected" vs. source text
        # saying "claim refused" share no root, so no hand-maintained
        # synonym list can ever be complete. But the cross-encoder reranker
        # IS a semantic model — it's what separates genuinely-relevant-but-
        # differently-worded content from actual noise, independent of
        # literal wording. When the lexical AND-check fails, fall back to
        # trusting that signal — but only well above the noise floor, and
        # only for single-topic questions (see single_topic above — this
        # fallback has the same compound-question smuggling risk as the 0.5
        # bypass): measured false positives (e.g. "IDV" scored 0.024 with
        # zero actual IDV content) sit close to measured true positives
        # (e.g. "rejected"/"refused" scored 0.074), so this bar is
        # deliberately conservative and still imperfect at this boundary —
        # a known residual limit of a purely retrieval-based gate, not a
        # fully solved problem.
        if single_topic and top_rerank >= 0.05:
            return True
        return False

    # Regex fallback (used for follow-up turns, where extracted LLM topics
    # from the raw short follow-up text aren't trustworthy — the topic lives
    # in conversation history, not the follow-up itself). Split compound
    # questions on "and"/"or", one discriminating-word set per sub-query.
    #
    # Same AND-logic + per-chunk co-occurrence fix as the llm_topics branch
    # above, and for the same reason: the old version required only ONE word
    # of a sub-query's term set to appear ANYWHERE in the pool (OR-logic,
    # scattered matching) — so "is regular health insurance mandatory"
    # (terms: "health", "mandatory") passed on "health" alone appearing
    # somewhere in an unrelated section, even though "mandatory" never
    # appeared anywhere and the KB never addresses legal requirements at
    # all. Every discriminating word of a sub-query must now co-occur
    # within a single chunk, and every sub-query must be satisfied.
    #
    # `query` here is usually the LLM-reformulated retrieval phrase for a
    # follow-up (e.g. "standard fire insurance policy exclusions and
    # limitations clause analysis"), not the user's raw question — and plain
    # "and"/"or" is extremely common in ordinary topic phrasing ("exclusions
    # and limitations", "terms and conditions") without meaning two separate
    # questions. Splitting on every bare "and" turned each such phrase into
    # two sub-queries, and the second half ("limitations clause analysis")
    # never lexically matches the actual chunks, failing the whole coverage
    # check and refusing a genuinely-covered topic. Real compound questions
    # ("what is a deductible and what is the GST rate...") repeat a
    # question-word/aux-verb right after the conjunction — only split there.
    sub_queries = [q.strip() for q in _COMPOUND_SPLIT.split(query) if q.strip()]
    all_term_sets = [_extract_topic_terms(sq) for sq in sub_queries]
    all_term_sets = [t for t in all_term_sets if t]
    if not all_term_sets:
        return True

    # Same single-topic-gated reranker-score rescue as the llm_topics branch
    # above, and it belongs here for the identical reason: pure lexical
    # matching can't handle phrasing gaps ("proximate cause" query vs.
    # source explaining it via "nearest cause"/"closest cause" without ever
    # using the words "proximate" or "determined" together) — the LLM-topics
    # extraction can also come back empty for a legitimate question (observed:
    # "How is proximate cause determined when multiple causes contribute to a
    # loss?" returned zero specific topics), which silently routes here with
    # no fallback at all before this fix, even when the actual best chunk
    # scored 0.92 — about as confident as this system ever gets.
    top_rerank = max(
        (d.metadata.get("rerank_score", 0) for d in docs if hasattr(d, "metadata")),
        default=0,
    )
    single_topic = len(all_term_sets) <= 1
    if single_topic and top_rerank >= 0.5:
        return True

    chunk_term_sets = []
    for doc in docs:
        text = (
            doc.page_content if hasattr(doc, 'page_content') else doc.get('text', '')
        ).lower()
        chunk_term_sets.append(set(re.findall(r'\b[a-z]{3,}\b', text)))

    all_covered = all(
        any(
            all(any(_word_matches(w, c) for c in chunk_terms) for w in term_set)
            for chunk_terms in chunk_term_sets
        )
        for term_set in all_term_sets
    )
    if all_covered:
        return True

    if single_topic and top_rerank >= 0.05:
        return True
    return False


def _quoted_comparison_covered(question: str, docs: list) -> bool:
    """True unless the question quotes 2+ specific terms to compare and the
    retrieved context is missing one of them.

    _context_covers_query() only requires ANY topic word to appear ANYWHERE
    in the retrieved pool, so a question like 'difference between "floater
    policy" and "specific policy" in fire insurance' passes on the generic
    words "fire"/"policy" alone even when the KB never discusses a floater
    vs. specific split — the LLM then fills the gap from training knowledge.
    This closes that gap: every quoted term must have at least one of its
    non-generic words present in context, or we decline instead of guessing.
    """
    quoted = re.findall(r'["‘’“”]([^"‘’“”]{3,40})["‘’“”]', question)
    quoted = [q.strip() for q in quoted if q.strip()]
    if len(quoted) < 2:
        return True
    ctx_lower = " ".join(
        (doc.page_content if hasattr(doc, "page_content") else doc.get("text", ""))
        for doc in docs
    ).lower()
    for term in quoted:
        distinguishing = _extract_topic_terms(term)
        if not distinguishing:
            continue
        if not any(w in ctx_lower for w in distinguishing):
            return False
    return True


# "Which insurers cover X" / "who offers Y" expect a NAMED list back.
# _context_covers_query() only requires generic topic words ("travel",
# "america") to appear somewhere in the retrieved pool — a general
# educational video that mentions America as an example destination passes
# that gate even though it never names a single insurer. This closes that
# gap: enumeration-style questions additionally require at least one
# proper-noun-like token (a plausible brand/company name) in the context.
_ENUMERATION_PATTERN = re.compile(
    r'\b(which|what)\s+(\w+\s+){0,2}(insurers?|insurance\s+compan(?:y|ies)|'
    r'compan(?:y|ies)|providers?|banks?|firms?|carriers?)\b'
    r'|\bwho\s+(covers?|offers?|provides?|insures?|sells?|underwrites?)\b'
    r'|\b(name|list)\s+(the|all|some)\b.{0,30}(insurers?|compan(?:y|ies)|providers?)',
    re.IGNORECASE,
)

_ENUM_COMMON_CAP_WORDS = {
    "the", "this", "that", "these", "those", "america", "india", "usa", "uk",
    "europe", "asia", "africa", "australia", "canada", "china", "japan",
    "however", "therefore", "additionally", "furthermore", "generally",
    "typically", "importantly", "note", "tip", "example", "for", "when",
    "while", "before", "after", "during", "also", "some", "many", "most",
    "several", "various", "certain", "so", "now", "here", "there", "yes", "no",
    # Secondary safeguard (belt-and-suspenders, not the primary fix — see
    # _has_named_entity()): these are capitalized when they open a
    # proper-noun-style phrase like "Takaful Insurance" or "Islamic
    # insurance model", but none of them are company names. The primary
    # fix is requiring known-insurer-name or company-suffix-adjacency
    # evidence in _has_named_entity() itself; this list additionally
    # excludes these specific words even if they'd otherwise satisfy that
    # adjacency check (e.g. "Islamic insurance" — "Islamic" sits directly
    # next to the suffix word "insurance").
    "takaful", "shariah", "islamic", "halal", "conventional",
}

# Known insurer names — factored out from _is_likely_followup()'s
# _INSURANCE_INDICATORS_LOCAL regex (same list) below, so both places share
# one source of truth instead of maintaining two independent copies.
_KNOWN_INSURER_NAMES = frozenset({
    "hdfc ergo", "icici", "bajaj", "tata aig", "reliance",
    "new india", "oriental", "national", "united india",
})

# Capitalized word/phrase immediately adjacent to one of these counts as a
# plausible company name (e.g. "New India Assurance", "XYZ Ltd", "ABC Corp").
_COMPANY_SUFFIX_WORDS = frozenset({
    "insurance", "assurance", "general", "life", "ltd", "inc", "co",
    "corp", "group", "underwriters", "mutual", "holdings",
})


def _has_named_entity(text: str) -> bool:
    """Plausible company/brand name: either a known insurer name, or a
    capitalized word/phrase immediately adjacent to a company-suffix word.

    The old version treated ANY capitalized, non-sentence-initial word not
    in a small filler list as a "plausible company name" — which let words
    like "Takaful", "Islamic", "Shariah" (capitalized when they open a
    proper-noun-style phrase, e.g. "Takaful Insurance") pass as named
    entities. That wrongly satisfied _enumeration_query_covered() for
    "which insurers cover the travel policy to south africa" when the
    retrieved chunk was actually about the Takaful insurance MODEL and
    never named a single real insurer — the confident answer that reached
    the user cited that chunk as if it answered the question.
    """
    lower = text.lower()
    if any(name in lower for name in _KNOWN_INSURER_NAMES):
        return True
    sentence_initial = {
        m.start(1) for m in re.finditer(r'(?:^|[.!?]\s+)([A-Z][a-zA-Z]{2,})', text)
    }
    for m in re.finditer(r'\b[A-Z][a-zA-Z]{2,}\b', text):
        if m.start() in sentence_initial:
            continue
        word = m.group(0)
        if word.lower() in _ENUM_COMMON_CAP_WORDS:
            continue  # belt-and-suspenders exclusion — see _ENUM_COMMON_CAP_WORDS
        before = text[:m.start()].rstrip()
        after = text[m.end():].lstrip()
        before_word = re.search(r'(\w+)$', before)
        after_word = re.match(r'^(\w+)', after)
        if before_word and before_word.group(1).lower() in _COMPANY_SUFFIX_WORDS:
            return True
        if after_word and after_word.group(1).lower() in _COMPANY_SUFFIX_WORDS:
            return True
    return False


def _enumeration_query_covered(question: str, docs: list) -> bool:
    """True unless the question asks 'which/who provides X' and the
    retrieved context contains no plausible named entity at all — or has a
    named entity, but not in the SAME chunk as the question's own topic
    words. A named entity that only appears in an unrelated chunk doesn't
    answer "which insurers cover travel to south africa" just because SOME
    insurer name exists somewhere else in the retrieved pool.
    """
    if not _ENUMERATION_PATTERN.search(question):
        return True
    topic_words = _extract_topic_terms(question)
    for doc in docs:
        text = doc.page_content if hasattr(doc, "page_content") else doc.get("text", "")
        if not _has_named_entity(text):
            continue
        if not topic_words:
            # No specific topic words to check co-occurrence against (e.g.
            # question was just "which insurers offer coverage?") — a named
            # entity anywhere is sufficient, same as before.
            return True
        chunk_terms = set(re.findall(r'\b[a-z]{3,}\b', text.lower()))
        if _topics_hit_chunk(topic_words, chunk_terms):
            return True
    return False


_DETAIL_SIGNALS = {
    'in detail', 'step by step', 'step-by-step', 'in steps', 'procedure',
    'how to', 'elaborate', 'walk me through',
    'in depth', 'thoroughly', 'fully explain', 'all about', 'everything about',
    'comprehensive', 'what are all', 'list all',
    'what all', 'how does it work', 'all the steps', 'entire process',
    'tell me everything', 'give me a full', 'give me the full',
}

_SIMPLE_SIGNALS = {
    'in simple', 'in short', 'in brief', 'briefly', 'short answer',
    'simple answer', 'quick answer', 'simple terms', 'layman', 'easy way',
    'just briefly', 'keep it short', 'keep it simple', 'just tell me',
    'just give me', 'just explain', 'just say',
    'simple language', 'simple words', 'easy language', 'easy words',
    'meaning of', 'meaning of this', 'what do you mean',
}

_EXAMPLE_SIGNALS = {
    'with example', 'with an example', 'give me an example', 'give an example',
    'show me an example', 'show an example', 'can you give example',
    'explain with example', 'example please', 'real life example',
    'real example', 'for example', 'use example',
    'with the help of an example', 'with the help of example',
    'explain me with example', 'can you give me an example',
    'explain with the help', 'using an example', 'using example',
}

# Every entry above contains the word "example" — the phrase list is really a
# proxy for "does the user want one". A fixed phrase list breaks on ordinary
# grammar drift (e.g. "with a example" instead of "with an example"), which
# silently disabled both the KV-cache safeguard and the prompt instruction for
# that query. Match on the word itself instead, which is the real signal.
_EXAMPLE_PATTERN = re.compile(r'\bexamples?\b', re.IGNORECASE)


def _wants_example(text: str) -> bool:
    return bool(_EXAMPLE_PATTERN.search(text))


# Same fragility as _EXAMPLE_SIGNALS had: _DETAIL_SIGNALS' 'in detail' entry
# is an exact-phrase match, so ordinary grammar drift silently disables it.
# Confirmed live: "can you explain it in more detail" — an extremely common,
# natural follow-up phrasing — doesn't contain the literal substring "in
# detail" (the word "more" sits between "in" and "detail"), so it silently
# fell through to brief mode. The user got a marginally-longer paragraph
# instead of the structured, wider-retrieval DETAILED_GROUNDED_PROMPT they
# asked for — visible from the outside only as the answer keeping brief
# mode's sign-off ("Let me know if you want more details!") instead of
# detailed mode's ("Hope that clears it up!..."). Same fix shape as
# _EXAMPLE_PATTERN: match the core signal via regex instead of an exact
# phrase, permissive of 0-2 modifier words between "in" and "detail(s)" so
# "in detail", "in more detail", "in greater detail", "in much more detail"
# all match.
_DETAIL_PATTERN = re.compile(r'\bin\s+(?:\w+\s+){0,2}details?\b', re.IGNORECASE)

# Used by _enforce_numbered_list_format (below _strip_source_self_reference) —
# these two query shapes are the ones prompt_template.py's FORMAT section
# explicitly requires a numbered list for (TYPES/KINDS QUESTIONS, COMPARISON
# QUESTIONS), and confirmed live the prompt rule alone isn't fully reliable —
# the exact same "prompt-only compliance holds most but not all of the time"
# pattern as _DETAIL_PATTERN's own "in detail" gap and _strip_source_self_reference's
# source-reference gap.
# "categories"/"varieties" added 2026-09-02 — confirmed live that "tell me
# about the various categories of health insurance" pulled the identical
# KB content (Mediclaim + Overseas Mediclaim) as "what kinds of health
# insurance are there" but came back as one flowing paragraph instead of a
# numbered list, purely because "categories of" isn't "type(s) of"/"kind(s)
# of". Same content, same intent, different container.
#
# This regex is the LOOSE signal of a three-tier check — see
# _is_types_enumeration_query below. Patching one more synonym in here
# every time a new phrasing surfaces live doesn't generalize (same lesson
# already learned for _DETAIL_PATTERN/_EXAMPLE_PATTERN/_has_modifier_hint
# elsewhere in this file); a word like "options" is a clean synonym in
# "what options do I have for marine insurance" but a completely
# different question in "what options do I have if my claim is denied" —
# too context-dependent to ever safely hardcode into a regex, which is
# exactly the case the LLM fallback below exists to resolve.
_TYPES_OF_QUERY_RE = re.compile(r"\b(?:types?|kinds?|categories|varieties)\s+of\b", re.IGNORECASE)

# STRICT fast path — confirmed live (2026-09-02) that the loose regex
# above matches "kind of"/"type of" followed by ANYTHING, insurance or
# not: "what kind of documents do I need to file a claim" matched it and
# returned True unconditionally, with zero chance for the LLM fallback to
# ever run and correctly say no (the function returned before reaching
# that code at all). This narrower version additionally requires an
# insurance-context word within a few words of "of" — generous enough
# (0-6 filler words) to cover a real multi-word type name ("types of
# long term health and critical illness insurance"), tight enough to
# reject "kind of documents"/"type of proof" claims-process phrasing. It
# is the ONLY case allowed to skip the LLM entirely (true zero-latency
# fast path); the loose regex above still matters as a secondary signal
# in _is_types_enumeration_query — a "kind of X" that fails THIS strict
# check isn't auto-rejected, it's handed to the LLM instead of trusted
# blindly either way.
_TYPES_OF_QUERY_STRICT_RE = re.compile(
    r"\b(?:types?|kinds?|categories|varieties)\s+of\s+(?:\w+\s+){0,6}?"
    r"(?:insurance|polic(?:y|ies)|cover(?:age)?|plans?)\b",
    re.IGNORECASE,
)
_COMPARISON_QUERY_RE = re.compile(
    r"\bcompare\b|\bdifference\s+between\b|\bvs\.?\b|\bversus\b|"
    r"\bwhat\s+(?:is|are)\b[^.?!]*\band\b",  # "what are Form A and Form B ...?" — two named items joined by "and", not just an explicit "compare"
    re.IGNORECASE,
)

# ── Hybrid fallback for "types of X" recognition (2026-09-02) ──────────────
# Same two-tier shape as _resolve_modifier_intent/_is_type_decision_query
# above: a free, instant regex for phrasings already seen, and — only when
# the wording at least LOOKS types-adjacent — a small LLM call that
# understands the actual meaning instead of matching one more fixed
# phrase. This is what lets "options"/"forms"/any future synonym resolve
# correctly (including telling a genuine "what options do I have for
# marine insurance" apart from an unrelated "what options do I have if my
# claim is denied") without needing a code change for each new wording.
_TYPES_HINT_WORDS = {
    'types', 'type', 'kinds', 'kind', 'categories', 'category',
    'varieties', 'variety', 'classes', 'class', 'options', 'option',
    'forms', 'form', 'variants', 'variant',
}

_TYPES_ENUMERATION_LLM_PROMPT = """\
Read the user's question to an insurance chatbot. Does it ask for a LIST \
of every type, kind, category, or variety of an insurance product that \
exists (e.g. "what types of motor insurance are there", "what options do \
I have for marine insurance", "what varieties of health cover exist")?

Answer NO for anything that is not this — including a question about the \
user's OWN situation asking which ONE type to pick ("which policy should \
I buy for my pet"), a claims/coverage/definition question ("what does my \
policy cover", "how do I file a claim", "what options do I have if my \
claim is denied" — that asks about the CLAIMS PROCESS, not insurance \
product types), or any unrelated question.

Output EXACTLY one word: YES or NO.

Question: "What options do I have when it comes to marine insurance?"
YES

Question: "What options do I have if my claim is denied?"
NO

Question: "Which policy is right for my pet?"
NO

Question: "What does my home insurance cover?"
NO

Question: {question}
"""


async def _is_types_enumeration_query(question: str) -> bool:
    """True when the question asks to enumerate every type/kind/category/
    variety of an insurance product — used everywhere _TYPES_OF_QUERY_RE
    used to be checked directly (retrieval width, numbered-list format
    enforcement, page-neighbor expansion). Three tiers: (1) _TYPES_OF_QUERY_STRICT_RE
    — "type(s)/kind(s) of" with an insurance-context word nearby — is a
    true zero-latency fast path, confidently correct on its own. (2)
    Anything that only matches the LOOSE _TYPES_OF_QUERY_RE ("kind of X"
    with no insurance-context word nearby, e.g. "what kind of documents
    do I need") or contains a loosely types-adjacent word
    (_TYPES_HINT_WORDS, e.g. "options"/"forms") is ambiguous enough to be
    worth one cheap LLM call rather than either trusting or discarding it
    blindly — confirmed live both directions matter: the loose regex
    alone previously returned True unconditionally for "what kind of
    documents do I need to file a claim" (not a types-of-insurance
    question at all), and a bare hint word like "options" means two
    completely different things depending on what follows it. (3) A
    genuinely unrelated question (neither regex, no hint word) never pays
    any extra cost — same "loose hint-word pre-filter" gate as
    _has_modifier_hint uses for the detail/simple/example classifier.
    """
    q = question.lower()
    if _TYPES_OF_QUERY_STRICT_RE.search(q):
        return True
    tokens = set(re.findall(r"[a-z]+(?:'[a-z]+)?", q))
    if not (tokens & _TYPES_HINT_WORDS) and not _TYPES_OF_QUERY_RE.search(q):
        return False
    try:
        prompt = _TYPES_ENUMERATION_LLM_PROMPT.format(question=question)
        raw = await _backend_completion(prompt, max_tokens=4, timeout=10)
        _result = bool(raw) and raw.strip().upper().startswith("YES")
        logger.info(
            "[ask_stream] types-enumeration LLM fallback fired: result=%s query=%r",
            _result, question[:80],
        )
        return _result
    except Exception:
        return False


# ── "I have/got X" ownership-statement fast path — hybrid check ────────────
# The fast path this backs (in ask_stream, "User-statement fast path") used
# to trust _USER_STATEMENT_OPENER_RE alone: match the OPENING few words of
# the message, and if so, skip retrieval entirely and reply with a canned
# "That's great that you have a {type} plan!" acknowledgment. Same bug
# shape as the old _TYPES_OF_QUERY_RE fast path (see that regex's own
# comment trail) — matching only the sentence's opening words says nothing
# about what the REST of the sentence actually is. Confirmed live:
# "I got some concerning test results and I'm worried about the hospital
# bills piling up" matched "I got" and got the canned ownership-
# acknowledgment reply, with zero retrieval, for someone describing a real,
# urgent problem — not announcing they own a plan. _is_insurance_related's
# own keyword list (which includes "hospital") never caught this either,
# since it's a topic gate, not a statement-vs-problem gate — a different
# job it does correctly, just not this one.
_USER_STATEMENT_OPENER_RE = re.compile(
    r"^\s*i\s+(have|got|have\s+got|purchased|bought|own|took|taken|recently\s+got|just\s+got"
    r"|am\s+covered|am\s+insured|enrolled|signed\s+up)\b",
    re.IGNORECASE,
)

_USER_STATEMENT_LLM_PROMPT = """\
Read this message sent to an insurance chatbot. Is the user simply \
ANNOUNCING that they already own or have an insurance POLICY/PLAN — a \
plain statement with no real question or problem attached (e.g. "I have \
a health plan", "I just bought term insurance", "I'm covered under my \
company's group policy")?

Answer NO if the message describes a problem, event, or situation the \
user needs help with or an answer to — even if it happens to start with \
similar words (e.g. "I got some concerning test results and I'm worried \
about the hospital bills" is NOT just an announcement, it's a real \
problem; "I got into an accident yesterday" and "I got denied for a \
claim" are NOT announcements either).

Answer NO when "own"/"have"/"got" refers to owning the INSURED THING \
ITSELF (a car, a house, a pet) rather than owning a policy for it — \
"I own a car and I'm thinking about getting insurance for it" means the \
user does NOT have a policy yet and is asking for help, not announcing \
coverage. Only say YES when the thing owned/had/bought is explicitly the \
policy/plan/cover itself, not the underlying asset.

Output EXACTLY one word: YES or NO.

Message: "I have a health plan."
YES

Message: "I got some concerning test results and I'm worried about the hospital bills piling up"
NO

Message: "I just bought term insurance last month."
YES

Message: "I got denied for a claim and I don't know what to do."
NO

Message: "I own a car and I'm thinking about getting insurance for it."
NO

Message: "I own a house and I'm not sure if I need insurance for it."
NO

Message: {question}
"""


async def _is_genuine_ownership_statement(question: str) -> bool:
    """True only when the message is genuinely just announcing the user
    already owns a plan — not describing a problem that happens to share
    an opening word. Fast regex first (free — most real messages don't
    even start with "I have/got", so this rarely fires at all); only when
    it DOES match does one cheap LLM call confirm the rest of the
    sentence is actually an announcement, not a problem needing a real
    answer. Unlike _is_types_enumeration_query's three-tier design, there
    is no separate loose-regex/hint-word middle tier here — the opener
    regex is already narrow enough (a specific closed set of verbs at the
    very start of the message) that every match is worth the one LLM call
    to disambiguate, rather than needing a pre-filter to avoid paying for
    ordinary unrelated traffic.
    """
    if not _USER_STATEMENT_OPENER_RE.match(question.lower()):
        return False
    try:
        prompt = _USER_STATEMENT_LLM_PROMPT.format(question=question)
        raw = await _backend_completion(prompt, max_tokens=4, timeout=10)
        _result = bool(raw) and raw.strip().upper().startswith("YES")
        logger.info(
            "[ask_stream] ownership-statement LLM check fired: result=%s query=%r",
            _result, question[:80],
        )
        return _result
    except Exception:
        return False


# ── Decision-query sub-branch disambiguation (2026-09-02) ──────────────────
# A policy_type can bundle several distinct, differently-scoped named
# products under one roof — marine has Cargo/Hull/Freight, motor has
# Liability Only/Package, etc. Confirmed live: "We're exporting machinery
# parts by sea and want to protect against damage" got recommended Hull
# Insurance (covers the SHIP) instead of Cargo Insurance (covers the
# GOODS) — even though Cargo's own chunk reranked ~3.4x higher than
# Hull's (0.0162 vs 0.0047, confirmed via direct reranker scoring, so
# retrieval/reranking were not at fault). The generation call picked Hull
# anyway because the KB's own Hull-branch text happens to say "...and
# related machinery", lexically echoing the query's "machinery parts"
# despite meaning something completely different (the ship's own
# machinery, not the user's cargo). Simply listing the branch names in
# the SAME generation prompt wouldn't fix this — that call is already
# busy with tone/structure/citations, and is exactly what got pulled off
# by the lexical coincidence in the first place. This is a SEPARATE,
# single-purpose classification call instead — same principle as
# _is_types_enumeration_query/_is_genuine_ownership_statement above: a
# call with exactly one job resists this kind of surface-level pull far
# better than a call juggling several jobs at once.
_SUBBRANCH_DECISION_PROMPT = """\
Read the description below of the different named products/branches within \
{policy_type} insurance, and the user's own situation. Decide which ONE \
named product actually applies to the user's situation — base this on WHO \
or WHAT is being protected (the specific asset, person, or party named in \
each branch's own description), not on which individual words happen to \
also appear in the user's own wording.

Branches description (from the knowledge base):
{branches_text}

User's situation: {question}

Output ONLY the exact name of the one branch that applies, copied verbatim \
from the branches description above (e.g. "Cargo Insurance"). If the \
description above does not clearly name more than one distinct product, or \
none of them clearly matches the user's situation, output exactly: NONE
"""


async def _classify_decision_subbranch(
    question: str, policy_type: str, branch_chunks: list,
) -> Optional[str]:
    """For a decision-shaped query, determine which specific named
    sub-branch/product within policy_type applies, via a call whose ONLY
    job is that decision — see the block comment above for why this is
    separate from the main generation call.

    Generic by design, not tied to marine or any other specific
    policy_type: entirely driven by whatever the KB itself already
    contains. `branch_chunks` are chunks THIS SAME request already
    retrieved and classified (via classify_chunk_intent, at the
    "decision-query full-policy-type retrieval" call site) as
    "types_of_insurance" — the KB's own enumeration-style content for
    this policy_type. If that content doesn't actually distinguish
    multiple named products (most policy_types only ever have one real
    product — the LLM decides this from the actual text, not a
    hardcoded per-policy_type list), or the model can't confidently pick
    one, returns None and the caller proceeds exactly as before this fix
    — this only ever ADDS a stated fact to the generation prompt, never
    blocks or replaces the normal path.
    """
    if not branch_chunks:
        return None
    branches_text = "\n\n".join(c.page_content[:800] for c in branch_chunks[:4])
    try:
        prompt = _SUBBRANCH_DECISION_PROMPT.format(
            policy_type=policy_type, branches_text=branches_text, question=question,
        )
        raw = await _backend_completion(prompt, max_tokens=20, timeout=12)
        if not raw:
            return None
        raw = raw.strip()
        if not raw or raw.upper().startswith("NONE"):
            return None
        # Verbatim gate — same discipline as this file's other salvage/
        # extraction code: only trust a branch name that's a real
        # substring of the source text actually shown to the classifier,
        # never let the LLM's own output alone decide what counts as real.
        if raw.lower() not in branches_text.lower():
            logger.info(
                "[ask_stream] sub-branch classifier returned a name not present "
                "in its own source text, discarding: %r", raw,
            )
            return None
        logger.info(
            "[ask_stream] sub-branch classifier: policy_type=%s decided=%r query=%r",
            policy_type, raw, question[:80],
        )
        return raw
    except Exception as _sb_exc:
        logger.debug("[ask_stream] sub-branch classifier skipped: %s", _sb_exc)
        return None


# ── PGF decision-query "names the type" check — hybrid (2026-09-02) ────────
# Confirmed live: "I just bought a new car... legal minimum or full
# protection" survived PGF's per-sentence grounding check with real,
# specific, correctly-grounded content ("protects your car against flood
# while in transit", "doesn't cover damages to your own car") — but the
# OLD check here required one of a small set of exact multi-word PHRASES
# ("car insurance", "motor policy", "vehicle insurance", ...) to appear
# verbatim, and natural writing about a vehicle just says "your car"/"your
# vehicle" once the topic is established, never redundantly repeating
# "motor insurance" in every sentence. Correct, substantive content got
# wrongly treated as hollow on BOTH the original attempt and its retry,
# ending in a false "not in KB" refusal for an answer the KB fully
# supported. Same bug shape as every other rigid-phrase-list fix this
# session — hybrid fast-list-then-LLM-semantic-check, not a bigger list.
_PGF_NAMES_TYPE_LLM_PROMPT = """\
Read this text, written as part of an answer recommending an insurance \
product for someone's situation. Does it substantively explain a \
{policy_type} insurance product — what it covers, how it helps, or what \
it's called — even if it never uses the exact phrase "{policy_type} \
insurance" itself (e.g. it might just say "your car"/"your vehicle" \
instead of ever saying "motor insurance")?

Answer NO if the text is only vague reassurance with no actual product \
information (e.g. "you should look into coverage for this" with nothing \
concrete about what that coverage actually is or does).

Output EXACTLY one word: YES or NO.

Text: {text}
"""


async def _pgf_survivor_names_type(text: str, policy_type: str) -> bool:
    """True when `text` substantively covers a `policy_type` product —
    used to decide whether a decision-query's surviving content (after
    PGF drops unsupported sentences) is a real answer or effectively
    hollow. Fast phrase-list check first (free, matches the common case
    where the answer DOES use one of the curated phrases); only when that
    finds nothing does one cheap LLM call confirm the text is actually
    about a real product, semantically, before concluding "hollow" and
    triggering a retry. On a backend failure, returns False — the same
    outcome this check had unconditionally before this fix existed, so a
    classifier failure degrades to the prior (safe, if occasionally
    over-cautious) behavior rather than a new, unproven default.
    """
    _hints = get_active_vocab().get(policy_type, {}).get("keywords", [])
    _lower = text.lower()
    if any(h in _lower for h in _hints):
        return True
    try:
        prompt = _PGF_NAMES_TYPE_LLM_PROMPT.format(policy_type=policy_type, text=text[:1000])
        raw = await _backend_completion(prompt, max_tokens=4, timeout=10)
        _result = bool(raw) and raw.strip().upper().startswith("YES")
        logger.info(
            "[ask_stream] pgf-names-type LLM fallback: policy_type=%s result=%s",
            policy_type, _result,
        )
        return _result
    except Exception:
        return False


# ── Illegal-adjacent-word insurance-context check — hybrid (2026-09-02) ────
# api.py's off-topic/illegal-content guard blocks a small "insurance-
# adjacent" word list (steal, robbery, fraud, scam, forge, launder, hack,
# malware, ransomware) UNLESS the question also contains an explicit
# insurance keyword (insurance, policy, cover, claim, premium, cyber,
# deductible, reimburs, payout, indemnity) — needed because these words
# are also exactly how someone asks a real coverage question ("does cyber
# insurance cover a hack"). Confirmed live: "I run a small shop and
# worried an employee might steal money from the register" — a genuine,
# if indirect, question about fidelity/theft coverage (this KB has real
# content for it) — got blocked outright as if it were "how do I steal",
# purely because it never happens to say "insurance"/"cover"/"claim"
# anywhere. Same bug shape as every other "explicit keyword required"
# gap fixed this session, just guarding a different, higher-stakes
# decision (block vs. answer) — hybrid fast-list-then-LLM fallback, kept
# conservative: on any doubt or backend failure, still blocks (this
# check only widens what counts as legitimate, never narrows the
# existing safety margin).
_ILLEGAL_ADJACENT_CONTEXT_LLM_PROMPT = """\
Read this message sent to an insurance chatbot. It contains a word that \
could mean either (a) the user is describing a real situation or risk \
they want insurance/protection against, or (b) the user is actually \
asking for help doing something illegal or harmful.

Answer YES only if this is clearly (a) — a legitimate question about a \
real situation, loss, or risk the user wants coverage/protection/advice \
for, even if it never uses words like "insurance" or "policy" (e.g. \
"worried an employee might steal from the register" is a real business-\
risk question, not a request for help stealing).

Answer NO if it's actually (b) — genuinely asking how to commit theft, \
fraud, hacking, or another illegal act, or anything unrelated to \
insurance/risk/protection entirely.

Output EXACTLY one word: YES or NO.

Message: {question}
"""


async def _confirm_insurance_adjacent_legitimate(question: str) -> bool:
    """Called only when a question matched an "illegal-adjacent" word
    (steal/hack/fraud/...) but none of the fast explicit insurance
    keywords — decides whether this is really a legitimate, if indirectly
    worded, insurance question before letting it through. Deliberately
    fails CLOSED: any backend error, empty response, or non-YES answer
    keeps the existing block in place — this check can only widen what
    counts as legitimate on a confident YES, never weaken the underlying
    safety gate on doubt.
    """
    try:
        prompt = _ILLEGAL_ADJACENT_CONTEXT_LLM_PROMPT.format(question=question)
        raw = await _backend_completion(prompt, max_tokens=4, timeout=10)
        _result = bool(raw) and raw.strip().upper().startswith("YES")
        logger.info(
            "[ask_stream] illegal-adjacent context LLM fallback: result=%s query=%r",
            _result, question[:80],
        )
        return _result
    except Exception:
        return False


# ── Warm lead-in (shared by both fallback sites below) ─────────────────────
# Used to rotate through several candidates ("So,", "Good question,",
# "Right,", "Sure thing,") — user feedback (2026-08-13, two rounds) flagged
# the VARIETY itself as the problem, not just "So," specifically ("these
# 'So' and 'Right' are not looking [good]... just say 'Sure Thing'").
# Locked to a single fixed phrase instead — explicitly chosen by the user
# over the no-lead-in-at-all alternative. _pick_lead_in kept as a function
# (not inlined at both call sites) so a future change is one edit, not two.
_LEAD_IN = "Sure thing,"


def _pick_lead_in(check_text: str) -> str:
    return _LEAD_IN

# ── "Type of X" query-shape disambiguation (2026-08-13) ────────────────
# _TYPES_OF_QUERY_RE fires on the bare phrase "type(s) of X" regardless of
# grammatical shape, but two completely different question shapes share
# that surface phrase: a genuine ENUMERATION request ("what types of
# motor insurance are there") that legitimately wants a full list, versus
# a DECISION/RECOMMENDATION request ("what type of insurance should I buy
# if my house is on fire") that wants ONE specific answer plus a brief
# reason — not an inventory of every peril a policy happens to cover.
# prompt_template.py's TYPES/KINDS QUESTIONS rule has no way to tell these
# apart from the raw question text alone, because the model reads that
# static rule text against whatever the actual question says. Confirmed
# live: "if my house is on fire then what type of insurance should i buy"
# got a 7-point numbered list padded with home insurance's OTHER covered
# perils (lightning, explosion, storm, flood, theft) — none of which the
# user asked about — because the model read "what type of insurance" as
# matching the enumeration rule's trigger phrase. Same lesson as every
# other prompt-compliance gap fixed this session: rewording the static
# rule and hoping the model reads it right every time isn't durable —
# resolve the ambiguity in code first (regex fast path, LLM fallback for
# genuinely ambiguous phrasing, same two-tier shape as
# _resolve_modifier_intent above), then tell the model explicitly which
# shape this specific question is.
# Confirmed live 2026-09-07: "should I" alone is a generic modal-verb
# construction that appears just as naturally in a PROCESS question
# ("what should I DO about the damages?" — a claims-process question)
# as in a genuine policy-CHOICE question ("what type should I BUY?") —
# the bare \bshould\s+i\b/\bshould\s+you\b alternatives below had no way
# to tell those apart and fired on the process question too, short-
# circuiting past the LLM fallback (which correctly distinguishes the
# two per _TYPE_SHAPE_PROMPT's own worked examples) before it ever got a
# chance to run. Restricted the same way the "need to"/"want to"
# alternatives below already were: require an actual acquisition/choice
# verb IMMEDIATELY after "should I/you", not just the modal phrase
# alone. Deliberately zero-gap (no filler-word tolerance like
# _srg_EXCLUSIONS_UNIT_RE's "{0,2}" elsewhere in this file) — a filler-
# word allowance here would let something like "what should I do to GET
# my claim processed" jump back into a false match on "get"; the rarer
# legitimate phrasing with an adverb in between ("should I really
# buy...") just falls through to the LLM fallback instead, which is the
# same safe degrade every other unmatched case here already relies on.
_TYPE_DECISION_RE = re.compile(
    r"\bshould\s+i\s+(?:buy|get|purchase|choose|opt|go|select|pick|take)\b|"
    r"\bshould\s+you\s+(?:buy|get|purchase|choose|opt|go|select|pick|take)\b|"
    r"\bdo\s+i\s+need\b|\bdoes\s+one\s+need\b|"
    r"\bwhich\s+(?:one\s+)?(?:should|do)\s+i\b|"
    r"\bneed\s+to\s+(?:buy|get|purchase|choose|take|pick)\b|"
    r"\bwant\s+to\s+(?:buy|get|purchase)\b|"
    r"\brecommend\b|\bbest\s+(?:type|option|policy|insurance)\b",
    re.IGNORECASE,
)
_TYPE_ENUMERATION_RE = re.compile(
    r"\b(?:are\s+there|exist|available)\b|\ball\s+the\s+(?:types?|kinds?)\b|"
    r"\blist\s+(?:all\s+)?(?:the\s+)?(?:types?|kinds?)\b",
    re.IGNORECASE,
)

_TYPE_SHAPE_PROMPT = """\
Read the user's question to an insurance chatbot. Decide which of these \
shapes it actually is:

DECISION = the user describes their OWN situation, need, pet/car/house/trip, \
or a specific event, and wants a RECOMMENDATION of the ONE type or plan that \
fits it — not a list of every type that exists. This includes questions that \
never use the words "type of" or "kind of" at all — "which policy is right \
for my pet", "what should I get for my pet's insurance", "help me choose a \
pet insurance plan", "what kind of insurance do I need for my car", "which \
type of policy is best if I travel a lot", "if my house catches fire what \
type of insurance should I buy" are ALL decision questions, phrased \
differently.

ENUMERATION = everything else — the user explicitly wants a LIST of every \
type/kind that exists ("what types of motor insurance are there", "list all \
the types of X"), OR the question isn't really about choosing between \
insurance types/plans at all (asking what's covered, how to file a claim, \
what a term means, etc. — anything that isn't "help me pick one").

Output EXACTLY one word: ENUMERATION or DECISION.

Question: "What are the types of motor insurance policies?"
ENUMERATION

Question: "If my house is on fire then what type of insurance should i buy"
DECISION

Question: "Which policy is right for my pet?"
DECISION

Question: "Help me choose a pet insurance plan"
DECISION

Question: "What does my home insurance cover?"
ENUMERATION

Question: {question}
"""


async def _classify_type_query_shape_llm(question: str) -> bool:
    """LLM fallback for the ENUMERATION-vs-DECISION shape of a "type(s)
    of X" question — only called when neither fast regex above found a
    confident signal either way. Returns True for DECISION (suppress the
    enumeration format), False for ENUMERATION or on any error/timeout —
    the safer default, since ENUMERATION is this codebase's pre-existing
    behavior for this phrase and an unresolved case should degrade to
    that rather than to an unproven new behavior.
    """
    try:
        prompt = _TYPE_SHAPE_PROMPT.format(question=question)
        raw = await _backend_completion(prompt, max_tokens=6, timeout=10)
        if not raw:
            return False
        return raw.strip().upper().startswith("DECISION")
    except Exception:
        return False


async def _is_type_decision_query(question: str, section_hint: Optional[str] = None) -> bool:
    """True when a question is asking for a recommendation of ONE
    insurance type/plan for the user's own situation, rather than a
    request to enumerate every type that exists — see _TYPE_DECISION_RE
    above for why this distinction matters. Called unconditionally on
    EVERY question (as of 2026-08-31 — a caller-side gate requiring the
    literal phrase "type of"/"kind of" first was found to skip this
    check entirely for real, differently-phrased decision questions like
    "which policy is right for my pet?"). Safe to call universally: the
    fast internal regexes below resolve the common cases at zero extra
    latency, and _TYPE_SHAPE_PROMPT's LLM fallback correctly returns
    False/ENUMERATION for anything that isn't actually a decision
    question at all (a coverage question, a claims question, etc.), so
    this naturally no-ops for the large majority of unrelated queries.

    section_hint (2026-09-07): the caller's OWN already-resolved, already-
    trusted section-intent classification (_query_section_result, only
    passed when confident — not a weaker "candidate" match), reused here
    as a hard structural veto rather than adding yet another standalone
    guess. User's explicit push-back on the earlier _TYPE_DECISION_RE
    narrowing fix: tightening one regex alternative doesn't help anything
    that still falls through to _classify_type_query_shape_llm — that
    fallback is itself just another small-model judgment call, exactly
    the kind of check this whole session has repeatedly found unreliable
    on its own. A CONFIRMED "claims" section is definitionally never a
    "which type should I buy" decision question — a claims-process
    question and a policy-choice question are mutually exclusive by
    definition, not just usually different — so this hint short-circuits
    straight to False before either the regex or the LLM ever runs,
    closing the whole failure class (any phrasing a claims question might
    take) rather than one more phrasing of it. Scoped to "claims"
    specifically since that's the section this was actually confirmed
    live against; extend to other unambiguously-process sections
    (documents, etc.) only once a real case proves the same gap there.
    """
    if section_hint == "claims":
        return False
    q = question.lower()
    if _TYPE_DECISION_RE.search(q):
        return True
    if _TYPE_ENUMERATION_RE.search(q):
        return False
    # Neither fast pattern matched — genuinely ambiguous phrasing worth
    # the small LLM round trip rather than silently defaulting either way.
    return await _classify_type_query_shape_llm(question)


def _needs_detailed_answer(question: str) -> bool:
    """True when the question expects a comprehensive, multi-part, or procedural answer."""
    q = question.lower()
    if any(sig in q for sig in _SIMPLE_SIGNALS):
        return False  # user explicitly wants brief — short-circuit before detail check
    if any(sig in q for sig in _DETAIL_SIGNALS) or _DETAIL_PATTERN.search(q):
        return True
    # Long questions (>25 words) almost always need more than 4 sentences
    if len(question.split()) > 25:
        return True
    # Three or more sub-questions joined by "and"
    if q.count(' and ') >= 3:
        return True
    return False


# ── Hybrid fallback for detail/simple/example intent ───────────────────────
# _SIMPLE_SIGNALS/_DETAIL_SIGNALS/_wants_example above are a fast, free,
# zero-latency check that correctly classifies the vast majority of real
# phrasings — but a fixed phrase/regex list can only ever cover phrasings
# someone has already hit (see [[project_detail_pattern_generalization]],
# [[project_fragile_signal_lists]]: EXAMPLE and DETAIL were each patched
# after a live miss, and there will always be a next one no matter how many
# patterns get added). The genuinely general fix is to ask the LLM itself
# when the fast path is inconclusive — semantic understanding generalizes to
# any phrasing, lexical matching never fully does.
#
# Kept as a FALLBACK, not the primary path, specifically for latency: this
# project has repeatedly traded effort for latency elsewhere this session
# (consolidated reranking, sentence caching, suggestion-chip removal), so
# adding a blocking classification call to every single request would cut
# directly against that. The fast path already resolves ~all real traffic;
# the LLM call only fires for the (expected to be rare) case where NONE of
# detail/simple/example matched anything lexically, so most requests pay
# zero extra latency and only genuinely ambiguous/novel phrasing pays the
# ~1-2s round trip.
_MODIFIER_INTENT_PROMPT = """\
Read the user's message to an insurance chatbot and decide what kind of \
answer they want.

DETAIL = the message EXPLICITLY asks for a full, comprehensive, step-by-\
step, or thorough explanation — not just a plain question.
SIMPLE = the message EXPLICITLY asks for a brief, short, plain-language, \
or easy-to-understand answer — not just a plain question.
EXAMPLE = the message EXPLICITLY asks for a concrete example, \
illustration, or real-life scenario.

A plain, ordinary question ("What is X?", "How does X work?", "Does X \
cover Y?") with NO explicit request for a particular style or depth is \
"no" on all three — default to "no" unless the wording clearly asks for \
one of these. Do not infer DETAIL or SIMPLE from how long or short the \
question itself is, or guess that a basic question implicitly wants a \
short answer — many basic questions still want a normal, complete answer.

Any, all, or none of these can be true for a given message. Output EXACTLY \
one line, nothing else, in this exact format:
detail=<yes/no> simple=<yes/no> example=<yes/no>

Message: "What is health insurance?"
detail=no simple=no example=no

Message: "I want the full picture, not just a summary"
detail=yes simple=no example=no

Message: "keep it short please"
detail=no simple=yes example=no

Message: "can you show me a real scenario for this"
detail=no simple=no example=yes

Message: {question}
"""


# Loose, cheap pre-filter for whether the LLM fallback is even worth
# trying. Confirmed live this matters: without it, "What is fire
# insurance?" — a completely plain question with zero modifier-related
# vocabulary — fell through to the LLM fallback exactly like a genuine
# novel-phrasing case, because "the strict fast path matched nothing" is
# also true for the overwhelming majority of ordinary questions that were
# never asking for a modifier at all. Not matching the strict signal list
# means "resolved: no modifier" for a plain question; it only means
# "inconclusive, worth asking" when the wording ALSO contains some
# modifier-adjacent vocabulary the strict list didn't happen to cover.
# This word set is deliberately looser/broader than the strict signal
# lists — it only has to be a cheap, in-process membership check, not an
# accurate classifier; the LLM call that follows is the actual classifier.
_MODIFIER_HINT_WORDS = {
    'full', 'complete', 'thorough', 'thoroughly', 'comprehensive',
    'everything', 'all', 'deep', 'deeper', 'depth', 'elaborate', 'expand',
    'picture', 'scenario', 'illustrate', 'breakdown', 'overview',
    'summary', 'summarize', 'concise', 'brief', 'briefly', 'quick',
    'short', 'basics', 'layman', 'plain', 'simple', 'simplify',
    'detail', 'details', 'detailed', 'skip',
}
# Multi-word hints can't be caught by single-word tokenization above —
# checked separately as plain substrings.
_MODIFIER_HINT_PHRASES = ('hold back', 'leave out', 'skip ahead')


def _has_modifier_hint(question_lower: str) -> bool:
    tokens = set(re.findall(r"[a-z]+(?:'[a-z]+)?", question_lower))
    if tokens & _MODIFIER_HINT_WORDS:
        return True
    return any(phrase in question_lower for phrase in _MODIFIER_HINT_PHRASES)


async def _classify_modifier_intent_llm(question: str) -> tuple[bool, bool, bool]:
    """LLM fallback for detail/simple/example intent — only called when the
    fast keyword/regex check found nothing in any of the three dimensions.
    max_tokens=20 so the round trip stays short. Falls back to
    (False, False, False) on any error/timeout, same as the fast path
    finding nothing — the caller already treats that as "no modifier
    requested", so a failed classification call degrades to the pre-hybrid
    behavior rather than blocking or crashing the request.
    """
    try:
        prompt = _MODIFIER_INTENT_PROMPT.format(question=question)
        raw = await _backend_completion(prompt, max_tokens=20, timeout=10)
        if not raw:
            return (False, False, False)
        raw_l = raw.lower()
        return (
            bool(re.search(r"detail\s*=\s*yes", raw_l)),
            bool(re.search(r"simple\s*=\s*yes", raw_l)),
            bool(re.search(r"example\s*=\s*yes", raw_l)),
        )
    except Exception:
        return (False, False, False)


async def _resolve_modifier_intent(question: str) -> tuple[bool, bool, bool]:
    """Resolve whether the user wants a detailed, simple, and/or
    example-based answer. Three stages: (1) strict fast path (free) — a
    real phrase/regex match resolves immediately; (2) if that finds
    nothing, a loose hint-word pre-filter decides whether the question is
    even worth asking the LLM about — a genuinely plain question with no
    modifier-adjacent vocabulary at all resolves to "no modifier" here,
    still free; (3) only if the loose filter also finds something does the
    LLM classification call actually run. See the block comment above
    _MODIFIER_INTENT_PROMPT for why this is hybrid rather than
    always-fast or always-LLM, and _has_modifier_hint's comment for why
    stage 2 exists (a plain "What is fire insurance?" was paying the LLM
    round trip for nothing until stage 2 was added).

    Returns (has_detail, has_simple, has_example). SIMPLE takes precedence
    over DETAIL when both are somehow set, matching _needs_detailed_answer's
    existing precedence — a user asking for both is treated as wanting
    brief, not a contradiction to resolve either way.
    """
    q = question.lower()
    _fast_example = _wants_example(q)
    _fast_simple = any(sig in q for sig in _SIMPLE_SIGNALS)
    _fast_detail = any(sig in q for sig in _DETAIL_SIGNALS) or bool(_DETAIL_PATTERN.search(q))
    # Structural signals (long/compound questions) stay fast-path-only —
    # these aren't a phrasing-recognition gap the LLM classifier would help
    # with, they're "is this objectively a big question" regardless of
    # wording, already phrasing-independent by construction.
    #
    # "types of X" / "kinds of X" / any equivalent phrasing
    # (_is_types_enumeration_query, already defined above for
    # _enforce_numbered_list_format's post-generation formatting) belongs
    # here too, for the retrieval-sizing side, not just formatting. Confirmed
    # live: "types of life insurance" retrieved only enough chunks to cover
    # 2 of the 6 real types this KB has (term, whole life — endowment,
    # annuities, money-back, and ULIP all live in the same source document a
    # few paragraphs later), because a bare "types of X" phrasing matches
    # none of _DETAIL_SIGNALS and stayed on the tight chunk_limit=5 budget
    # meant for single-fact questions. An enumeration question is
    # structurally never a single-fact question — it needs the wider
    # chunk_limit=8/doc_top_k=18 budget the same way a long or compound
    # question does, regardless of whether the user also happened to type
    # "in detail".
    _structural_detail = (
        len(question.split()) > 25
        or q.count(' and ') >= 3
        or await _is_types_enumeration_query(question)
    )

    if _fast_example or _fast_simple or _fast_detail or _structural_detail:
        _has_detail = (_fast_detail or _structural_detail) and not _fast_simple
        return (_has_detail, _fast_simple, _fast_example)

    # Strict fast path matched nothing — for the overwhelming majority of
    # ordinary questions ("What is fire insurance?") that's not ambiguity,
    # it's the correct, confident answer: no modifier was requested. Only
    # worth the LLM round trip when the wording ALSO contains some looser
    # modifier-adjacent vocabulary the strict list didn't happen to cover —
    # otherwise every plain question would pay the fallback's latency for
    # no reason, defeating the entire point of the hybrid design.
    if not _has_modifier_hint(q):
        return (False, False, False)

    # Genuinely ambiguous or novel phrasing (e.g. "I want the full
    # picture, not just a summary", or "explain it in more detail" before
    # that specific gap was patched into the strict list). Try the cheap
    # LLM classifier before defaulting to "no modifier requested".
    _llm_detail, _llm_simple, _llm_example = await _classify_modifier_intent_llm(question)
    _has_detail = _llm_detail and not _llm_simple
    logger.info(
        "[ask_stream] modifier intent LLM fallback fired: detail=%s simple=%s example=%s query=%r",
        _has_detail, _llm_simple, _llm_example, question[:80],
    )
    return (_has_detail, _llm_simple, _llm_example)


# ── Hybrid fallback for section-intent classification ──────────────────────
# Same underlying problem as the detail/simple/example hybrid above, same
# fix, applied to a different classifier: _QUERY_SECTION_INTENT_PATTERNS
# (the closed regex list _classify_query_section_intent checks first) can
# only ever cover phrasings someone has already hit. Confirmed live —
# three real gaps found in one afternoon of testing fresh, previously-
# untried query phrasings, each needing its own regex patch before this
# fallback existed: "Explain in detail how a health insurance claim
# works" (not "how do I file/claim/submit"), "Walk me through the process
# of claiming a life insurance policy" (not "claims process/procedure"),
# and there will always be a next one — a query classifier that only ever
# recognizes exact phrasings already seen can't cover something as open-
# ended as how people actually ask questions. Semantic understanding
# generalizes to any phrasing; lexical matching never fully does.
#
# Kept as a fallback, not the primary path, for the same latency reason as
# the modifier hybrid: the fast regex list already resolves the vast
# majority of real traffic for free, so only genuinely novel phrasing
# should ever pay the LLM round trip.
_SECTION_INTENT_LLM_PROMPT = """\
Read the user's question to an insurance chatbot and decide which ONE \
section of an insurance document it's really asking about, if any.

Categories:
benefits — what a policy covers or includes. This INCLUDES a question \
that describes a specific real-world situation or incident and asks \
whether it would be covered, or whether it could cost the person money \
out of pocket ("would insurance help me if X happened", "could that end \
up costing me money", "am I on the hook for this") — that is still \
asking about coverage for that situation, not asking generically about \
refunds, premiums, or a product's payment structure. Judge it by whether \
a SPECIFIC situation is described, not by whether the word "money" or \
"cost" appears.
exclusions — what's NOT covered, exceptions, limitations
claims — how to file/submit a claim, the claims process, what happens \
when making a claim
definitions — the query explicitly asks what a specific TERM means \
("define X", "what does X mean", "meaning of X") — a bare "What is X?" \
about a named product, policy, or concept is NOT automatically \
"definitions": it's usually really asking about that thing's benefits, \
claims process, or general nature, and the real answer in this \
knowledge base is filed under one of THOSE categories instead, or under \
none at all. Only pick "definitions" when the question is asking for a \
dictionary-style meaning, not when "X" just happens to be the topic.
eligibility — who can buy a policy, age limits, entry requirements
flight_delay — a flight, trip, or departure being delayed (travel \
insurance)
baggage — lost, delayed, or damaged baggage/luggage (travel insurance)
legislation — laws, regulations, IRDAI rules, legal requirements
types_of_insurance — different types or kinds of a policy
principles — insurance principles or doctrines
history — the history or origins of insurance
case_law — court cases, legal precedent, judgments
medical — a medical emergency or evacuation while traveling
none — doesn't clearly fit any single category above, or is a broad/\
general question

Judge the underlying INTENT, not just literal keyword overlap — "what \
happens when I claim" and "walk me through claiming" both mean "claims" \
even though neither contains the word "process" or "file".

Output EXACTLY one line, nothing else, in this exact format:
category=<one label from the list above>

Question: "How do I get money back if I never claim anything?"
category=none
(a general question about a PRODUCT FEATURE — a no-claim refund/bonus
structure — with no specific situation described; different from a
question that describes an actual incident and asks if it's covered)

Question: "My neighbor's kid broke his arm playing in my backyard, could
that end up costing me money?"
category=benefits
(a specific real-world incident, asking whether the policy would cover
the cost of it — this is a coverage/benefits question even though it
never uses the words "cover" or "policy")

Question: "What happens when I claim under a fire insurance policy?"
category=claims

Question: "What is No Claim Bonus?"
category=none

Question: {question}
"""

# Semantic (embedding) classifier for query section-intent, sitting
# between the fast regex path and the LLM fallback below. Root-cause fix
# for a pattern confirmed TWICE live in one night (2026-09-01): the
# fixed-12-category LLM classifier answering "category=none" for a real,
# substantively-covered question just because it doesn't cleanly fit one
# category in the LLM's own judgment — first a misleading few-shot
# example biased it ("could that end up costing me money" pattern-
# matched a "none" example about refunds), then a genuinely broad,
# multi-faceted question ("what should I sort out before I go") had no
# single obvious category. Patching the PROMPT one example at a time
# doesn't scale to every future phrasing shape. This classifies by
# MEANING instead — cosine similarity against a question-form prototype
# per category, reusing the shared embedding model already loaded for
# retrieval (no new dependency) — the same principled fix already used
# for chunk-side section classification earlier this session (see
# metadata_tagger.py's classify_by_section_embedding), just built fresh
# for QUERY-length text and the query-side label set, since chunk
# prototypes (statement-form, e.g. "Describes what a policy pays for")
# and this taxonomy (13 different labels: flight_delay/baggage/
# legislation/case_law/etc. vs. chunk-side's own set) don't transfer —
# confirmed live: applying the chunk classifier directly to these same
# queries returned entirely wrong labels ("premiums", "chapter",
# "how_to") that aren't even valid values in this taxonomy.
_QUERY_SECTION_PROTOTYPES = {
    "benefits": "Does my policy cover this specific situation or event, and what does it pay for?",
    "exclusions": "What is not covered or excluded under this policy?",
    "claims": "How do I file or submit a claim, and what is the claims process?",
    "definitions": "What does this specific insurance term mean?",
    "eligibility": "Who is eligible to buy this policy, and what are the entry requirements or age limits?",
    "flight_delay": "My flight or trip departure was delayed, am I covered for that?",
    "baggage": "My baggage or luggage was lost, delayed, or damaged, what happens?",
    "legislation": "What do the insurance laws, regulations, or IRDAI rules require?",
    "types_of_insurance": "What are the different types or kinds of this insurance?",
    "principles": "What insurance principle or doctrine applies here?",
    "history": "What is the history or origin of this kind of insurance?",
    "case_law": "What court case or legal precedent applies to this?",
    "medical": "I have a medical emergency or need evacuation while traveling, what do I do?",
}

# Calibrated empirically against 10 real positive queries (one per
# category) and 5 genuine negatives (off-topic questions like "tell me
# a joke"). An absolute-score-only cutoff does NOT cleanly separate
# them — a genuinely AMBIGUOUS query (the backpacking-prep question,
# which touches benefits/eligibility/medical roughly equally) can score
# almost as high on its WRONG top label (0.581) as a clearly-correct
# match does on its right one (0.620). What DOES separate them cleanly
# is the MARGIN between the top and runner-up label: the confirmed-
# correct backyard-liability match beat its next-best rival by 0.113;
# every genuinely ambiguous or off-topic query in the calibration set
# had its top few candidates bunched within 0.008-0.061 of each other,
# however high the top score itself looked. Requiring both a score
# floor AND a margin catches this reliably without needing to have
# seen the specific query shape before.
_QUERY_SECTION_EMBED_FLOOR = 0.55
_QUERY_SECTION_EMBED_MARGIN = 0.08
_query_section_prototype_embeddings: Optional[tuple] = None


def _get_query_section_prototype_embeddings():
    global _query_section_prototype_embeddings
    if _query_section_prototype_embeddings is None:
        _model = _get_shared_embed_model(EMBED_MODEL_NAME)
        _labels = list(_QUERY_SECTION_PROTOTYPES.keys())
        _vecs = _model.encode(list(_QUERY_SECTION_PROTOTYPES.values()), normalize_embeddings=True)
        _query_section_prototype_embeddings = (_labels, _vecs)
    return _query_section_prototype_embeddings


def _classify_query_section_by_embedding(query: str) -> Optional[tuple[str, bool]]:
    """See the _QUERY_SECTION_PROTOTYPES block comment above for the full
    rationale and calibration evidence. Returns (label, False) — same
    shape as a fixed-category regex/LLM match, never a candidate/open-
    vocabulary result — or None if neither the score floor nor the
    margin bar is cleared, in which case the caller falls through to the
    LLM tier exactly as if this check didn't exist."""
    try:
        _labels, _proto_vecs = _get_query_section_prototype_embeddings()
        _model = _get_shared_embed_model(EMBED_MODEL_NAME)
        _qvec = _model.encode([query], normalize_embeddings=True)[0]
        _sims = np.dot(_proto_vecs, _qvec)
        _order = np.argsort(-_sims)
        _top_score = float(_sims[_order[0]])
        _margin = _top_score - float(_sims[_order[1]])
        if _top_score >= _QUERY_SECTION_EMBED_FLOOR and _margin >= _QUERY_SECTION_EMBED_MARGIN:
            _label = _labels[_order[0]]
            logger.info(
                "[ask_stream] section-intent embedding match: label=%r score=%.3f "
                "margin=%.3f query=%r",
                _label, _top_score, _margin, query[:80],
            )
            return (_label, False)
        return None
    except Exception as exc:
        logger.debug("[ask_stream] section-intent embedding classification failed (%s)", exc)
        return None


# Loose, cheap pre-filter for whether the LLM fallback is even worth
# trying — same role as _MODIFIER_HINT_WORDS/_has_modifier_hint: a plain
# question with none of this vocabulary at all ("What is fire
# insurance?") resolves to "no section intent" here, still free; the LLM
# call only fires when the wording contains SOME section-adjacent
# vocabulary the strict regex list didn't happen to cover. Deliberately
# broader/looser than any single category's own strict pattern — it only
# has to gate whether asking is worth it, not classify anything itself.
_SECTION_HINT_WORDS = {
    'benefit', 'benefits', 'cover', 'covers', 'covered', 'coverage',
    'exclude', 'excludes', 'excluded', 'exclusion', 'exclusions',
    'claim', 'claims', 'define', 'definition', 'meaning', 'mean',
    'eligible', 'eligibility', 'age', 'delay', 'delayed', 'flight',
    'trip', 'departure', 'baggage', 'luggage', 'regulation',
    'regulations', 'legislation', 'irda', 'irdai', 'legal', 'law',
    'laws', 'type', 'types', 'kind', 'kinds', 'principle', 'principles',
    'history', 'origin', 'origins', 'court', 'judgment', 'judgement',
    'precedent', 'medical', 'emergency', 'evacuation',
    # Confirmed live (2026-08-25): "My cargo was damaged during shipping,
    # what do I do to get compensated?" is genuinely a claims question but
    # contains none of the words above — no "claim" anywhere in it — so it
    # fell through this pre-filter without ever reaching the LLM
    # classifier at all, not because the LLM said "none" but because it
    # was never asked. These cover the common ways people describe a
    # claims situation without using the word "claim" itself.
    'compensate', 'compensated', 'compensation', 'reimburse',
    'reimbursed', 'reimbursement', 'settle', 'settlement', 'damage',
    'damaged', 'loss', 'lost', 'stolen', 'theft', 'accident', 'refund',
}


def _has_section_hint(question_lower: str) -> bool:
    tokens = set(re.findall(r"[a-z]+(?:'[a-z]+)?", question_lower))
    return bool(tokens & _SECTION_HINT_WORDS)


async def _classify_query_section_llm(question: str) -> Optional[str]:
    """LLM fallback for section-intent classification — only called when
    the fast regex list found nothing. max_tokens=20 so the round trip
    stays short. Returns None on any error/timeout or an unrecognized
    label, same as the fast path finding nothing — a failed classification
    call degrades to the pre-hybrid behavior (no section intent detected)
    rather than blocking or crashing the request.
    """
    try:
        prompt = _SECTION_INTENT_LLM_PROMPT.format(question=question)
        raw = await _backend_completion(prompt, max_tokens=20, timeout=10)
        if not raw:
            return None
        m = re.search(r"category\s*=\s*([a-z_]+)", raw.lower())
        if not m:
            return None
        label = m.group(1)
        if label == "none" or label not in MultiSourceRAG._QUERY_SECTION_INTENT_PATTERNS:
            return None
        return label
    except Exception:
        return None


async def _classify_query_candidate_section_llm(question: str) -> Optional[str]:
    """Open-vocabulary sibling of _classify_query_section_llm() — only
    called when the fixed-12-category LLM classifier already said "none".
    _classify_query_section_intent's own fast path already does a CHEAP,
    free keyword-overlap check against candidate_section_vocab.json (see
    match_candidate_section_vocab) for exactly this same open-vocabulary
    case — but that only catches a query using 2+ of a discovered
    label's literal stored keywords. Confirmed live 2026-09-01: a
    query can genuinely be about a real, already-discovered topic
    without hitting that literal-keyword bar, the same way the fixed-12
    LLM classifier exists because the fixed regex list has the same
    literal-phrase limitation. This is that same upgrade, one level up.

    Deliberately does NOT invent brand-new labels here, unlike
    _classify_query_candidate_type_llm on the policy_type side —
    ingestion-time discovery (classify_candidate_section in rag.py) has
    the actual source document text to work from when deciding a new
    label is warranted; a query alone doesn't have enough context to
    safely invent one, and a wrong invented label here would just
    silently fail to match anything anyway (candidate_section filtering
    only ever helps if the label already exists on some chunk). Purely
    a MATCHING step against whatever's already been discovered.
    """
    from candidate_section_vocab import get_candidate_section_vocab
    vocab = get_candidate_section_vocab()
    if not vocab:
        return None
    try:
        label_list = "\n".join(f"  - {lbl}" for lbl in sorted(vocab.keys()))
        prompt = f"""These are topic labels discovered from real documents in an insurance
knowledge base, on top of the standard categories already checked (which didn't match):

{label_list}

Does the user's question below genuinely match ONE of these labels? Only answer yes if
it's a clear, specific match to what that label is actually about — not a loose or
generic connection.

QUESTION: {question}

Reply with ONLY the exact label word if one clearly matches, or reply with exactly: none"""
        raw = await _backend_completion(prompt, max_tokens=15, timeout=10)
        if not raw:
            return None
        label = raw.strip().strip('"').lower()
        label = re.split(r"[\s\n,.:;()]", label)[0]
        if label and label in vocab:
            logger.info(
                "[ask_stream] candidate-section LLM fallback: %r -> %s", question, label,
            )
            return label
        return None
    except Exception as exc:
        logger.debug("[ask_stream] candidate-section LLM classification failed (%s)", exc)
        return None


_FOLLOWUP_SIGNALS = {
    'it', 'its', 'that', 'this', 'them', 'those', 'they', 'their', 'which', 'these',
}

# Pronoun/reference words used to decide whether _contextualize_query() should
# attempt an LLM call.  If the question doesn't contain any of these tokens it
# is structurally standalone (e.g. a fresh topic out of nowhere), so the LLM
# round-trip can be skipped entirely.
#
# Ordinal references to a numbered list ("point 2", "the 2nd point", "explain
# number 3") are just as much a reference needing resolution as "the second
# point" — but people type them with a digit far more often than spelled out.
# Without the digit patterns below, "explain the 2 point" fell through this
# fast-path as "structurally standalone" and skipped contextualization
# entirely, so the follow-up went to retrieval completely unresolved and the
# model ended up guessing/blending a different point at generation time.
_REFERENCE_TOKENS = re.compile(
    r"\b(?:it|its|that|this|those|these|they|them|their|which|"
    r"one\b|ones\b|the\s+\w+\s+one|the\s+other\b|"
    r"more\b|further\b|elaborate\b|"
    r"first\b|second\b|third\b|last\b|"
    r"other\b|another\b|"
    r"\d+(?:st|nd|rd|th)\b|"
    r"point\s+\d+\b|\d+\s*(?:st|nd|rd|th)?\s+point\b|"
    r"number\s+\d+\b)",
    re.IGNORECASE,
)
_FOLLOWUP_OPENERS = (
    'what about', 'how about', 'and what', 'also ', 'tell me more',
    'what does it', 'how does it', 'what is it', 'is it ', 'can it ',
)

# Standalone keywords that strongly signal a follow-up when the message is short
# and has no standalone insurance topic. These words refer back to a prior topic
# (e.g. "justify more", "explain further", "why though") rather than introducing
# a new self-contained question.
_FOLLOWUP_KEYWORDS = frozenset({
    "more", "further", "why", "justify", "expand", "deeper", "elaborate",
    "explain", "details", "detail", "reason", "reasons", "example", "examples",
    "though", "still", "again", "anyway",
})


# The vLLM backend is shared, slow (~7-8 tok/s, confirmed live), and a
# single ask_stream request already makes many sequential calls to it
# (query classification, topic extraction, contextualization, the main
# answer, then — for comparison queries — depth-balancing, list
# formatting, and table reformatting on top). Confirmed live 2026-08-14:
# a burst of back-to-back test requests produced 3x more backend timeout
# warnings than the same window under normal light use — extra concurrent
# requests were queueing on top of each other on this one backend, and
# the tightest per-call timeouts (sized for near-instant response) had no
# slack left once a request had to wait its turn. Capping how many
# requests THIS PROCESS sends to vLLM at once means the (N+1)th request
# waits here, in an asyncio queue, instead of piling up unbounded on the
# backend and timing out. Does not apply to Groq/manual — those are
# different services without this shared-capacity constraint.
_VLLM_CONCURRENCY_LIMIT = int(os.getenv("VLLM_CONCURRENCY_LIMIT", "4"))
_vllm_semaphore = asyncio.Semaphore(_VLLM_CONCURRENCY_LIMIT)
_unlimited_semaphore = asyncio.Semaphore(1000)


async def _backend_completion(
    prompt: str, max_tokens: int, timeout: float, temperature: float = 0,
    backend_override: Optional[str] = None,
) -> Optional[str]:
    """Fast, non-streaming chat completion against whichever backend is
    currently active (vLLM or Groq — both OpenAI-compatible, same request
    shape). Returns the raw response text, or None on any failure, timeout,
    or unconfigured/unsupported backend.

    Used for short, best-effort auxiliary calls (topic extraction, query
    reformulation) that should follow the SAME backend as the main
    answer generation, not be pinned to vLLM regardless of FORCE_BACKEND.
    An earlier version hardcoded these to
    always use vLLM specifically to keep a Groq-vs-vLLM generation-fidelity
    A/B test uncontaminated by a different topic-extraction model also
    changing retrieval-gating behavior. That trade-off made sense for a
    controlled test, but not for actual production use — once FORCE_BACKEND
    picks a backend to actually serve answers from, every supporting call
    should use that same fast backend too, not bottleneck the whole request
    on a slower one just for a few background tokens.

    backend_override bypasses _active_backend() for the one call that needs
    it regardless of FORCE_BACKEND: the query-cleaning fallback path exists
    specifically to route around Groq's daily quota running out (observed
    repeatedly in testing), so its own grounding re-check would defeat the
    point if it silently used Groq again and failed the same way.

    Only vLLM and Groq are handled (matches what existed before this
    generalization) — OpenAI/Anthropic backends fall through to None here,
    same as an unconfigured backend, and callers already have a graceful
    fallback for that.
    """
    import aiohttp as _ah
    from router import (
        VLLM_HOST, VLLM_API_KEY, _resolve_vllm_model, _active_backend,
        GROQ_API_KEY, GROQ_CLASSIFICATION_MODEL, GROQ_CLASSIFICATION_REASONING_EFFORT,
    )
    backend = backend_override or _active_backend()
    if backend == "vllm":
        url = f"{VLLM_HOST}/v1/chat/completions"
        model = _resolve_vllm_model()
        headers = {"Content-Type": "application/json", "Authorization": f"Bearer {VLLM_API_KEY}"}
    elif backend == "groq":
        # Every caller of this function is a classification/extraction-
        # shaped auxiliary call (query type, modifier intent, policy
        # type, grounding check, contextualization, ...) — never Ava's
        # live chat, which stays on GROQ_MODEL untouched. Safe to use
        # the classification-specific model here unconditionally.
        url = "https://api.groq.com/openai/v1/chat/completions"
        model = GROQ_CLASSIFICATION_MODEL
        headers = {"Content-Type": "application/json", "Authorization": f"Bearer {GROQ_API_KEY}"}
    elif backend == "manual":
        from router import _runtime_manual_api_key, _runtime_manual_base_url, _runtime_manual_model
        url = f"{_runtime_manual_base_url.rstrip('/')}/chat/completions"
        model = _runtime_manual_model
        headers = {"Content-Type": "application/json", "Authorization": f"Bearer {_runtime_manual_api_key}"}
    else:
        return None
    # GROQ_CLASSIFICATION_MODEL is a reasoning model — see its own comment
    # in router.py. Every call site here was tuned for the old non-
    # reasoning model with max_tokens as low as 6, nowhere near enough
    # headroom for reasoning tokens on top of the actual answer; raising
    # the floor here (once, centrally) beats touching every call site.
    _payload_max_tokens = max(max_tokens, 150) if backend == "groq" else max_tokens
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": prompt}],
        "max_tokens": _payload_max_tokens,
        "temperature": temperature,
        "stream": False,
    }
    if backend == "groq":
        payload["reasoning_effort"] = GROQ_CLASSIFICATION_REASONING_EFFORT
    sem = _vllm_semaphore if backend == "vllm" else _unlimited_semaphore
    try:
        async with sem:
            async with _ah.ClientSession() as session:
                async with session.post(
                    url, json=payload, headers=headers,
                    timeout=_ah.ClientTimeout(total=timeout),
                ) as resp:
                    if resp.status != 200:
                        # Silently returning None here (as before) is indistinguishable
                        # from a network blip or timeout in logs — every caller treats
                        # it as "the model said no" and refuses, so a sustained
                        # condition (e.g. a rate/quota limit) looks identical to
                        # ordinary occasional flakiness with no way to tell them apart
                        # short of manually replaying the exact request outside the
                        # app. Logging status + body once per failure costs nothing
                        # on the happy path and turns "everything is mysteriously
                        # refusing" into an immediately diagnosable log line.
                        body = await resp.text()
                        logger.warning(
                            "[_backend_completion] %s returned status=%s (backend=%s model=%s): %s",
                            url, resp.status, backend, model, body[:300],
                        )
                        return None
                    data = await resp.json()
                    return data["choices"][0]["message"]["content"].strip()
    except Exception as exc:
        logger.warning("[_backend_completion] request to %s failed (backend=%s): %s", url, backend, exc)
        return None


async def _vllm_clean_query(question: str) -> Tuple[Optional[str], Optional[str], bool]:
    """Fallback query cleaner tried only when the primary retrieval attempt
    already failed coverage — fixes general spelling mistakes (not just the
    hand-curated insurance vocabulary _correct_typos() knows) and strips
    specific qualifiers (a named country/city, emphasis words like
    "affordable"/"cheap"/"best") that measurably tank the reranker's score
    even when the KB covers the general topic well. Measured: "how to buy
    motor insurance" scored 0.79; adding just "affordable" dropped it to
    0.017; adding "in Dubai" alone dropped it to 0.15 — the same qualifier-
    dilution pattern behind several earlier fixes this session, just never
    addressed at the query-cleaning layer directly.

    Calls vLLM specifically, not whatever _active_backend()/FORCE_BACKEND
    currently points at — this is a retry path for a query that's already
    failing, not primary answer generation, and shouldn't compete for the
    same (rate-limited) Groq quota real answers need.

    Returns (cleaned_query, dropped_terms_summary, dropped_has_proper_noun)
    — cleaned_query and dropped_terms_summary are both None on any failure,
    unconfigured backend, or empty response, so the caller falls through to
    the existing refusal exactly as it did before this function existed.
    dropped_terms_summary is computed programmatically from the before/
    after diff (see _diff_dropped_terms), not self-reported by the model —
    asking it to also report what it removed was tried first and was
    unreliable, sometimes echoing the prompt's own example words
    ("affordable", "cheap", "best") as "dropped" even when they were never
    in the query, or weren't actually removed from the cleaned version.
    """
    import aiohttp as _ah
    from router import VLLM_HOST, VLLM_API_KEY, _resolve_vllm_model
    if not VLLM_HOST:
        return None, None, False
    prompt = (
        f"Query: {question}\n\n"
        "This insurance-related search query may contain spelling mistakes, "
        "and words that make it too specific for a keyword search to match "
        "well (e.g. a country/city name, or emphasis words like "
        "'affordable', 'cheap', 'best'). Rewrite it as a short, general "
        "search query about the CORE topic only: fix any spelling mistakes, "
        "and drop any specific location or emphasis words that aren't "
        "needed to describe the core insurance topic. "
        "Respond with ONLY the rewritten query, nothing else."
    )
    try:
        url = f"{VLLM_HOST}/v1/chat/completions"
        model = _resolve_vllm_model()
        headers = {"Content-Type": "application/json", "Authorization": f"Bearer {VLLM_API_KEY}"}
        payload = {
            "model": model,
            "messages": [{"role": "user", "content": prompt}],
            "max_tokens": 40,
            "temperature": 0,
            "stream": False,
        }
        async with _ah.ClientSession() as session:
            async with session.post(
                url, json=payload, headers=headers,
                timeout=_ah.ClientTimeout(total=12),
            ) as resp:
                if resp.status != 200:
                    return None, None, False
                data = await resp.json()
                raw = data["choices"][0]["message"]["content"].strip()
    except Exception:
        return None, None, False
    cleaned = raw.strip().strip('"').strip("'").strip()
    if not cleaned:
        return None, None, False
    _dropped_note, _dropped_proper_noun = _diff_dropped_terms(question, cleaned)
    return cleaned, _dropped_note, _dropped_proper_noun


# Emphasis/qualifier words worth calling out by name if the cleaner drops
# them — deliberately short and specific rather than a broad stopword list,
# since the goal is only to name concrete things that got removed, not to
# flag every function word that naturally differs between two phrasings of
# the same query.
_EMPHASIS_WORDS = frozenset({
    'affordable', 'cheap', 'cheapest', 'best', 'top', 'premium',
    'expensive', 'discount', 'discounted', 'lowest', 'cheaply',
})


def _diff_dropped_terms(original: str, cleaned: str) -> Tuple[Optional[str], bool]:
    """Return (short comma-separated list of concrete terms present in
    *original* but missing from *cleaned*, whether any of them is a likely
    proper noun) — specifically capitalized words other than the first
    (likely a proper noun: a country, city, or provider name) and known
    emphasis words (_EMPHASIS_WORDS). Computed directly from the text
    rather than trusted from the model's own self-report (see
    _vllm_clean_query's docstring for why).

    The proper-noun flag matters downstream: dropping "affordable"/"cheap"
    to get a retrieval match is harmless (the KB's content on the core
    topic is still factually complete, just not tagged "cheap"), but
    dropping a country/city/provider name means the KB has no actual
    content about that specific thing — answering with the generic
    version and hoping the model remembers to disclose the gap is not
    reliable enough to trust (see the caller in ask_stream for the
    concrete failure this was measured against).
    """
    orig_words = original.split()
    clean_lower = cleaned.lower()
    dropped = []
    has_proper_noun = False
    for i, w in enumerate(orig_words):
        w_clean = w.strip(".,!?;:()[]{}'\"")
        if not w_clean:
            continue
        w_lower = w_clean.lower()
        is_proper_noun = i > 0 and w_clean[0].isupper()
        is_emphasis = w_lower in _EMPHASIS_WORDS
        if (is_proper_noun or is_emphasis) and w_lower not in clean_lower:
            dropped.append(w_clean)
            if is_proper_noun:
                has_proper_noun = True
    return (", ".join(dict.fromkeys(dropped)) if dropped else None, has_proper_noun)


_SPECIFIC_TYPE_RE = re.compile(
    r"\b(motor|car|vehicle|auto|bike|two.wheeler|four.wheeler|"
    r"life|term\s*life|whole\s*life|endowment|ulip|"
    r"health|medical|hospital|"
    r"travel|trip|flight|baggage|"
    r"home|house|property|landlord|tenant|"
    r"marine|cargo|fire|"
    r"liability|third.party|"
    r"critical\s*illness|cancer|"
    r"group|corporate|reinsurance|takaful|"
    r"crop|agricultur\w*|"
    r"personal\s*accident|disability|"
    r"retirement|pension|annuity)\b"
)

# Narrower than _SPECIFIC_TYPE_RE above: requires the type word to sit right
# next to "insurance/policy/assurance/cover" before counting as a genuine
# type ATTRIBUTION. _SPECIFIC_TYPE_RE's bare-word matching is fine for its
# original purpose (does a raw USER QUESTION name its own topic?), but reused
# against GENERATED ANSWER prose it over-fires on ordinary English: a
# correct, well-grounded takaful-insurance answer explaining "risks are
# shared among a group, rather than being transferred to an insurance
# company" got discarded and replaced with a refusal because "group" alone
# matched — the answer never claimed anything about Group Insurance as a
# product, it just used "group" to mean "a group of people." Words like
# group/life/home/fire/crop are common English outside insurance too;
# requiring adjacency to insurance/policy/assurance/cover keeps the
# genuine-attribution cases ("endowment assurance policy", "group
# insurance") while dropping incidental non-insurance uses of the same word.
_TYPE_ATTRIBUTION_RE = re.compile(
    r"\b(motor|car|vehicle|auto|bike|two.wheeler|four.wheeler|"
    r"life|term\s*life|whole\s*life|endowment|ulip|"
    r"health|medical|hospital|"
    r"travel|trip|flight|baggage|"
    r"home|house|property|landlord|tenant|"
    r"marine|cargo|fire|"
    r"liability|third.party|"
    r"critical\s*illness|cancer|"
    r"group|corporate|reinsurance|takaful|"
    r"crop|agricultur\w*|"
    r"personal\s*accident|disability|"
    r"retirement|pension|annuity)\s+(insurance|policy|assurance|cover|coverage)\b",
    re.IGNORECASE,
)

# Catches a distinct failure mode from _TYPE_GIVEAWAY_TERMS below: the
# model stating a country/region-level legal or regulatory insurance
# requirement (a Schengen visa's minimum-coverage condition, a country
# "requiring" health insurance for expats, etc.) that it knows from its own
# training data, not from anything actually retrieved — STRICT_GROUNDED_
# PROMPT's "never use external knowledge" instruction doesn't reliably stop
# this for well-known real-world facts. Confirmed live, 3 of 5 destination-
# insurance queries: "is health insurance required for a europe trip"
# fabricated an entirely unrelated "the UAE requires expats to have some
# form of health insurance" claim (sourced from a YouTube transcript with
# no such content) alongside a repeated Schengen-visa claim; "should i buy
# health insurance before travelling to germany" fabricated "Germany
# requires health insurance for certain visa categories" plus a specific
# dollar figure. All three answers' own retrieved context never contained
# the word "visa" at all (confirmed directly against the source text) —
# by contrast, "i am going to france"/"...to japan" with no legal-
# requirement claim in context came back correctly generic, and the one
# query using the literal string "schengen visa" correctly refused rather
# than hallucinate. A real, grounded requirement claim needs its own
# supporting language (visa/legal/mandatory) to exist somewhere in what
# was actually retrieved — if the answer asserts the claim but the context
# has none of that language anywhere, it's very likely training-data
# leakage, not retrieval.
_LEGAL_REQUIREMENT_CLAIM_RE = re.compile(
    r"\b(legal(?:ly)?\s+requir\w*|mandator\w+\s+(?:to\s+have\s+)?(?:some\s+form\s+of\s+)?"
    r"(?:health\s+)?insurance|insurance\s+is\s+(?:often\s+)?(?:a\s+)?legal\s+requirement|"
    r"requir\w*\s+(?:you\s+to\s+have\s+|expats?\s+to\s+have\s+)?(?:some\s+form\s+of\s+)?"
    r"(?:health\s+)?insurance|visa\s+requir\w*)\b",
    re.IGNORECASE,
)
_LEGAL_REQUIREMENT_SUPPORT_RE = re.compile(
    r"\bvisa\b|\blegal(?:ly)?\s+requir\w*|\bmandator\w+\b", re.IGNORECASE,
)

# Module-level (not request-scoped) so both the detailed-mode point filter
# and the brief-mode whole-reply check below can share one definition rather
# than drifting out of sync. Catches jargon/content from a RETRIEVED chunk
# about the wrong topic — distinct from _TYPE_ATTRIBUTION_RE above, which
# only catches an explicit "X insurance/policy" naming, not topic-specific
# vocabulary that never says the type name at all (e.g. "driving history"
# never says "motor insurance").
_TYPE_GIVEAWAY_TERMS = {
    "marine": ("marine insurance", "marine cargo", "icc (a)", "icc (b)", "institute cargo clause", "bill of lading", "voyage policy", "hull insurance"),
    "health": ("health insurance", "domiciliary hospitalization", "domiciliary hospitalisation", "cashless hospitalization", "cashless hospitalisation", "pre-existing disease"),
    "crop": ("crop insurance", "agriculturist", "crop failure", "sowing/planting", "loanee"),
    "fidelity": ("fidelity insurance", "employee dishonesty", "embezzlement"),
    "transit": ("transit insurance", "import covers by sea", "inland transit clause"),
    # Added 2026-09-07 (project_marine_fire_chunk_contamination): "fire" had
    # NO entry at all here despite being a recognized type in
    # _TYPE_ATTRIBUTION_RE — confirmed live, a marine-insurance claim query
    # quoted "the insured must lodge the claim form within 15 days of the
    # fire to claim compensation" verbatim as if it were a marine deadline.
    # The source chunk is real (CLAIM SETTLING PROCESS (FIRE AND MARINE
    # INSURANCE), one combined section covering both types), but that "15
    # days" deadline is stated only for fire claims in the source text —
    # the model misattributed a fire-specific fact to marine because the
    # chunk's heading names both. Terms below are genuine multi-word fire
    # jargon pulled directly from this KB's own fire-insurance chunks
    # (docker exec query against policy_type='fire'), same "real KB-sourced
    # phrase, not a bare word" discipline the other entries here follow.
    "fire": ("fire insurance", "fire insurance policy", "fire brigade", "fire and special perils", "fire and allied perils", "of the fire", "spontaneous combustion", "standard fire policy"),
    "motor": (
        "motor insurance", "vehicles plying on public roads",
        "vehicle", "owner-driver", "driving record", "driving history",
        "reckless driving", "unnamed passengers",
        "tp (third-party) premium", "own damage",
        # Added 2026-08-04 (Phase 1, plan_claim_answer_correctness.md):
        # confirmed live, a life-insurance claim answer asserted "if the
        # claim involves a third party, such as a car accident" — motor's
        # own claim-settlement concept, hallucinated with zero motor
        # content anywhere in that answer's retrieved context.
        # _POLICY_TYPE_HINTS["motor"]["keywords"] already has "road
        # accident" but not this exact phrasing; unambiguous, not shared
        # with any other type.
        "car accident",
    ),
}
# A query naming the type itself is exempt from that type's filter (a
# genuine comparison/vehicle-linked question should keep vehicle content).
# "motor" additionally exempts on "vehicle"/"car"/"driving" etc. since a
# question can ask about vehicle-linked cover without ever saying "motor".
_TYPE_QUERY_EXEMPT_WORDS = {
    "motor": ("motor", "vehicle", "car", "bike", "scooter", "motorcycle", "driving", "driver"),
}


def _get_type_assertion_vocab() -> dict:
    """Phase 1 (plan_claim_answer_correctness.md): per-type vocabulary for
    the ungrounded-foreign-type-assertion gate below — deliberately a
    DIFFERENT, complementary list from _TYPE_GIVEAWAY_TERMS, not a
    replacement for it.

    _text_has_giveaway_contamination (above) catches LEAKAGE: a foreign
    type's term that genuinely appears in RETRIEVED context (a wrong-type
    chunk really was pulled in) and then shows up in the answer too — real
    evidence of a source, just the wrong one for this query. It structurally
    cannot catch the opposite failure: a foreign-type claim asserted with
    ZERO supporting evidence anywhere in what was retrieved — pure
    hallucination, not leakage. Confirmed live 2026-08-04: "How to claim a
    life insurance?" asserted "if the claim involves a third party, such as
    a car accident" (motor's third-party/MACT-tribunal concept) while every
    retrieved source for that query was life-insurance/general content with
    zero motor material in it at all — there was no motor chunk for
    anything to leak FROM.

    Merges _TYPE_GIVEAWAY_TERMS with get_active_vocab()'s keyword lists
    (covers all core + promoted open-vocab types, not just the 6 curated
    here) so this gate has real coverage across all policy types, not just
    the ones _TYPE_GIVEAWAY_TERMS happens to enumerate. Two safety filters,
    both drawn from this file's own bare-word false-positive history
    (project_motor_bareword_giveaway_generalization,
    project_compound_word_joiner_bug):
      - multi-word phrases only — a bare single word (even one already
        vetted for the leakage check above, e.g. motor's "vehicle") is
        excluded here, since this gate's drop condition (context has NO
        support at all) is a different risk profile than the leakage
        check's (context DOES support it).
      - any phrase shared by 2+ types (e.g. "third party liability" in both
        motor and liability, "accidental death" in both life and
        personal_accident) is dropped from every type's list — a shared
        phrase can't safely attribute one type over another.

    Recomputed per call rather than cached at import time: get_active_vocab()
    can change at runtime (candidate-type promotion), and this is cheap
    (short-string set operations over a few hundred keywords, no ML/IO) —
    same reasoning _get_type_assertion_vocab's siblings elsewhere in this
    file already apply to per-request get_active_vocab() calls.
    """
    raw: dict = {}
    for _type_name, _terms in _TYPE_GIVEAWAY_TERMS.items():
        raw.setdefault(_type_name, set()).update(
            t.lower() for t in _terms if " " in t or "-" in t
        )
    for _type_name, _info in get_active_vocab().items():
        for kw in (_info.get("keywords") or []):
            kw_l = kw.lower().strip()
            if " " in kw_l or "-" in kw_l:
                raw.setdefault(_type_name, set()).add(kw_l)
    counts: dict = {}
    for _terms in raw.values():
        for _t in _terms:
            counts[_t] = counts.get(_t, 0) + 1
    return {
        _type_name: sorted(t for t in _terms if counts[t] == 1)
        for _type_name, _terms in raw.items()
    }


# Phase 2 (plan_claim_answer_correctness.md): claim-intent detector, kept as
# one named, importable constant rather than inlined so it can't drift out
# of sync with the corpus/tests that need to recognize the same shape.
# Requires BOTH claim vocabulary AND a procedural question shape — "claim"
# alone would also fire on a coverage question ("does my policy cover a
# claim for water damage?"), which isn't asking about claim PROCEDURE and
# shouldn't get the extra retrieval weighting below. The procedural-shape
# alternation covers all three canonical phrasings this plan's Phase 0
# corpus uses ("how do I claim...", "what is the ... claim process", "walk
# me through claiming on a ... policy") plus common variants.
_CLAIM_INTENT_VOCAB_RE = re.compile(r"\b(claim|claiming|claims|settl\w*|reimburs\w*)\b", re.IGNORECASE)
_CLAIM_INTENT_PROCEDURAL_RE = re.compile(
    r"^\s*(?:how|what|walk me|explain|tell me)\b|\b(?:process|procedure|steps?)\b",
    re.IGNORECASE,
)


def _is_claim_intent_query(query: str) -> bool:
    query = query or ""
    return bool(_CLAIM_INTENT_VOCAB_RE.search(query) and _CLAIM_INTENT_PROCEDURAL_RE.search(query))


# Curated, closed list of named claim/policy documents and instruments this
# KB actually discusses. Used by the artifact-grounding check in the
# currency-filter block below (~_qualifier_mismatched) — same contract as
# _currency_grounded: if the model names a SPECIFIC document, that name
# must actually appear in what was retrieved, or the claim mentioning it is
# dropped. Confirmed live: a motor-insurance answer said the claim
# procedure needs "original bills and discharge summaries" — "discharge
# summary/summaries" (a hospital document) appears in ZERO chunks anywhere
# in this KB. The retrieved motor chunk (m4-3f.pdf) instead says "Discharge
# voucher (full and final payment)" — the model took the real word
# "discharge" out of a claim-PAYMENT acknowledgment and re-formed it into a
# different, wrong-domain document name. _TYPE_GIVEAWAY_TERMS/
# _text_has_giveaway_contamination cannot catch this: that filter requires
# the giveaway TERM to already be present in the retrieved context before
# it will flag anything (see its own docstring) — a term absent from the
# ENTIRE KB, like "discharge summary" here, can never satisfy that and the
# check always no-ops. This list intentionally includes both the correct,
# grounded artifact name AND its most likely wrong-domain confusions (e.g.
# both "discharge voucher" and "discharge summary") so the SAME single
# mechanism naturally keeps the real one and drops the fabricated one,
# rather than needing a hardcoded "X is wrong, Y is right" pairing.
_ARTIFACT_NOUNS = (
    "discharge voucher", "discharge summary", "discharge slip",
    "discharge certificate", "claim form", "cover note",
    "surveyor's report", "receipted bill", "cash memo",
    "policy schedule", "bill of lading", "proposal form",
    "death certificate", "post-mortem report", "postmortem report",
    "driving licence", "driving license", "registration certificate",
)


def _normalize_word_forms(text: str) -> str:
    """Lowercases, strips apostrophes, and singularizes a trailing plural
    's'/'ies' on each word — so a multi-word artifact-noun phrase matches
    regardless of plural or possessive form ("discharge vouchers" /
    "surveyor's report" / "surveyor's reports" all normalize the same way
    as their singular form). Used on both the generated text and the
    retrieved context so the comparison is apples-to-apples."""
    cleaned = re.sub(r"['’]", "", (text or "").lower())
    words = re.findall(r"[a-z]+", cleaned)
    norm = []
    for w in words:
        if w.endswith("ies") and len(w) > 4:
            norm.append(w[:-3] + "y")
        elif w.endswith("s") and len(w) > 4 and not w.endswith("ss"):
            norm.append(w[:-1])
        else:
            norm.append(w)
    return " ".join(norm)


# original phrase -> its normalized form, precomputed once
_ARTIFACT_NOUNS_NORM = {phrase: _normalize_word_forms(phrase) for phrase in _ARTIFACT_NOUNS}

# A point naming a sibling policy type as somewhere ELSE a loss is covered
# ("this is excluded here; covered under your motor/fire policy instead")
# or explicitly as an exclusion is legitimate, standard insurance-document
# language, not evidence the point is actually ABOUT that sibling type.
_EXCLUSION_LANGUAGE_RE = re.compile(
    r"\bexclu\w*\b|\bnot\s+covered\b|\bdoes\s+not\s+cover\b|"
    r"\bcovered\s+(?:by|under|elsewhere)\b",
    re.IGNORECASE,
)


def _text_has_giveaway_contamination(
    text: str, query_lower: str, query_policy_type: str = "general",
    retrieved_context_text: str = "",
) -> bool:
    # query_policy_type is classify_query_policy_type(retrieval_query) —
    # already computed once per request for the metadata retrieval filter,
    # and far more reliable than re-deriving "does the query mention this
    # type" via a bare-word substring check. Confirmed live: "What is
    # medical insurance?" classifies correctly as "health" (its regex list
    # includes "medical insurance"), but the OLD bare-word exemption only
    # checked for the literal word "health" in the query — absent here — so
    # a fully correct answer ("Medical insurance is a type of health
    # insurance...") got flagged as contaminated for saying "health
    # insurance", its own genuinely-correct category. Trusting the
    # classifier directly closes this whole class of synonym/hypernym gap,
    # not just this one instance.
    #
    # retrieved_context_text requires the giveaway TERM to genuinely appear
    # somewhere in what was retrieved this turn before treating a match in
    # the generated text as contamination — same "real evidence" guarantee
    # the original design wanted, but checked against the actual retrieved
    # TEXT rather than a chunk's policy_type TAG. The tag-based version of
    # this check (`_type_name not in retrieved_types`, retrieved_types
    # built by excluding policy_type=="general") was structurally blind to
    # any topic with no official policy_type of its own — confirmed live:
    # "Explain engineering insurance in detail" retrieved ONLY
    # general-tagged chunks (engineering isn't one of the 12 hardcoded
    # types) and produced a point containing "hull insurance" — a term
    # already tracked under the marine bucket — but the marine check never
    # ran at all, since no chunk was TAGGED marine, even though the term
    # was sitting right there in the retrieved text. Checking the text
    # directly closes that gap without weakening the original guarantee:
    # a term still only counts as evidence when it's actually present in
    # what was retrieved, not just because the query's classifier guessed
    # a sibling type (e.g. explaining "personal insurance" by listing it
    # alongside motor/health as one of five general categories stays
    # exempt, since neither "motor insurance" nor "health insurance" as a
    # literal term needs to appear in the retrieved text for that to be a
    # legitimate answer).
    text_lower = text.lower()
    context_lower = retrieved_context_text.lower()
    for _type_name, _terms in _TYPE_GIVEAWAY_TERMS.items():
        if _type_name == query_policy_type:
            continue
        if not any(term in context_lower for term in _terms):
            continue
        _exempt_words = _TYPE_QUERY_EXEMPT_WORDS.get(_type_name, (_type_name,))
        if any(w in query_lower for w in _exempt_words):
            continue
        if any(term in text_lower for term in _terms):
            # A point NAMING a sibling type isn't automatically ABOUT that
            # type — a standard coordination-of-benefits/anti-duplication
            # exclusion clause ("X is excluded here because it's covered
            # under your motor policy") is completely normal, correct
            # insurance-document language, and its own sibling-type
            # classification is identical either way (both come back
            # "motor" — type confirmation, which fixed the Phase 2 gate's
            # false positives, does NOT separate this case; the giveaway
            # term itself is the same word whether the point is about that
            # type or just redirecting to it). Confirmed live 2026-07-23: a
            # correct jewellery-exclusions point naming "motor insurance
            # policies" as where an overlapping loss is instead covered
            # got deleted wholesale. Same negation-style guard the
            # fines-claim check already uses below, applied here too.
            if _EXCLUSION_LANGUAGE_RE.search(text_lower):
                continue
            return True
    return False


# ─────────────────────────────────────────────────────────────────────────
# Shared numbered-point split/rebuild — contamination root-cause plan
# (plan.md), Phase 0/2. Previously this exact opener/points/closer
# split-and-fold logic was duplicated near-identically in the ungrounded-
# point filter and the cross-topic contamination filter below (and would
# have needed a THIRD copy for the point-relevance gate) — precisely the
# kind of silent-drift risk the plan calls out. One shared implementation
# now backs all three call sites plus the contamination trace.
# ─────────────────────────────────────────────────────────────────────────
_POINT_LINE_RE = re.compile(r"^\s*(\d+)\.\s+(.*)$")

# Confirmed live: a detailed-mode life-insurance answer's final line was
# "5. Let me know if you want more details! 😊" — the model numbered its own
# sign-off as if it were a real list item. _POINT_LINE_RE can't tell a real
# point from this by shape alone (both are "N. text"), so without this check
# the sign-off became a bogus final point that survived every downstream
# filter untouched (none of them had anything to drop). Same core sign-off
# vocabulary already used to detect this phrasing elsewhere in this file
# (:7802) — not the full canonical closer strings (:3757), since this only
# needs to catch the model STARTING a line this way, not match it exactly.
_SIGNOFF_START_RE = re.compile(
    r"^(hope that|let me know|feel free|hang tight|glad to|dig into any part)",
    re.IGNORECASE,
)

# Same live example exposed a second, more serious problem in the same
# answer: "So, 1. Different types of life insurance include..." — the warm
# lead-in landed on the SAME line as point 1 instead of its own line/
# paragraph (contrast the well-formed "Sure, let's dive in:\n\n1. ..."
# shape). _POINT_LINE_RE requires the digit at the true start of the line,
# so this whole line fell through to opener_lines untouched — meaning point
# 1's real content became invisible to EVERY point-level filter (grounding,
# cross-topic contamination, the always-false-claim block), since none of
# them read opener_lines. This is a coverage gap, not just a cosmetic one.
# Same lead-in vocabulary already used elsewhere in this file (:7806).
# Deliberately only tried while seen_point is still False — a "1." that
# turns up mid-answer after the list has already started is never a lead-in
# glued to a point, so this can't misfire on later points.
_LEADIN_POINT_LINE_RE = re.compile(
    r"^\s*(?:so|good question|sure thing|right|ah|hmm)[,:]?\s*(\d+)\.\s+(.*)$",
    re.IGNORECASE,
)


def _split_numbered_points(text: str) -> Tuple[List[str], List[str], List[str]]:
    """Split numbered-list answer text into (opener_lines, point_texts,
    closer_lines). Folds indented or "-"/"*"/"•" continuation lines into
    their parent point so a later dropped point doesn't leave orphaned
    sub-bullets behind — same behavior the two original inline copies
    had, just no longer duplicated.
    """
    lines = text.split("\n")
    opener_lines: List[str] = []
    point_texts: List[str] = []
    closer_lines: List[str] = []
    seen_point = False
    for line in lines:
        m = _POINT_LINE_RE.match(line)
        if not m and not seen_point:
            lead_m = _LEADIN_POINT_LINE_RE.match(line)
            if lead_m:
                # Keep the lead-in's own punctuation ("So," / "Right:") —
                # only trims the trailing space before the digit — so IF a
                # rebuild ever fires (a point downstream of this got
                # dropped), the recovered opener still reads as a real
                # sentence fragment rather than a bare stripped word.
                opener_lines.append(line[:lead_m.start(1)].rstrip())
                m = lead_m
        if m:
            content = m.group(2).strip()
            if _SIGNOFF_START_RE.match(content):
                # Route to closer_lines, stripped of the spurious "N. "
                # prefix, so it renders as a normal trailing sign-off
                # instead of a fabricated final list item.
                closer_lines.append(content)
                continue
            seen_point = True
            point_texts.append(content)
            continue
        if not seen_point:
            opener_lines.append(line)
            continue
        stripped = line.strip()
        if not stripped:
            continue
        is_continuation = line[:1].isspace() or stripped.startswith(("-", "*", "•"))
        if is_continuation and point_texts:
            point_texts[-1] = point_texts[-1] + " " + stripped
        else:
            closer_lines.append(line)
    return opener_lines, point_texts, closer_lines


def _rebuild_from_points(opener_lines: List[str], points: List[str], closer_lines: List[str]) -> str:
    """Inverse of _split_numbered_points — rebuild numbered-list text from
    a (possibly filtered) points list. Shared so the rebuild format never
    drifts between the filters that use it.
    """
    opener_part = "\n".join(opener_lines).strip()
    closer_part = "\n".join(closer_lines).strip()
    rebuilt_points = "\n".join(f"{i}. {p}" for i, p in enumerate(points, 1))
    pieces = [p for p in (opener_part, rebuilt_points, closer_part) if p]
    return "\n\n".join(pieces)


def _numbered_list_needs_signoff_leadin_fix(text: str) -> bool:
    """True if `text`, in its RAW (unparsed) form, still has either of the
    two defects _split_numbered_points/_rebuild_from_points already know
    how to fix: a lead-in glued to point 1's own line ("So, 1. ..."), or a
    numbered final line that's actually the sign-off ("N. Hope that clears
    it up!..." / "N. Let me know if you want more details! 😊").

    Deliberately NOT implemented as "compare a raw numbered-marker count
    to len(point_texts)" (the first version of this check, still used
    verbatim at one call site below) — that comparison has a blind spot
    when BOTH defects land in the SAME answer: the lead-in case makes a
    marker-count regex anchored to true line-start undercount by one
    (the glued "1." isn't at a line start), and the sign-off case makes
    point_texts undercount by one too (it's routed to closer_lines) — the
    two undercounts cancel out and the mismatch check misses both.
    Confirmed live: "So, 1. Life insurance focuses on providing a death
    benefit...\\n2. ...\\n5. Let me know if you want more details! 😊" —
    raw marker count (4, since only 2/3/4/5 are true line-start markers)
    equaled point count (4, since point 5 routes to closer_lines) even
    though the text plainly still needed both fixes. This checks each
    defect directly instead of inferring it from a count.
    """
    stripped = (text or '').strip()
    if not stripped:
        return False
    lines = stripped.split('\n')
    if _LEADIN_POINT_LINE_RE.match(lines[0]):
        return True
    _last_point_content = None
    for line in lines:
        m = _POINT_LINE_RE.match(line)
        if m:
            _last_point_content = m.group(2).strip()
    return bool(_last_point_content and _SIGNOFF_START_RE.match(_last_point_content))


# Two-signal duplicate-point detection: a pair must clear BOTH a
# cross-encoder score floor AND a lexical word-overlap floor. Neither
# signal alone was reliable — found through three rounds of live
# calibration against real detailed-mode answers, not guessed:
#
# Round 1 (score only, threshold 0.95): the confirmed real repro (motor
# insurance, points 5 & 7 restating the same liability claim in different
# words) scored 0.9998 — but so did several genuinely-different points
# that merely shared a topic, e.g. "the insurer covers various aspects
# such as damage to the vehicle, third-party liability, and personal
# accident" (real, additive coverage detail) scored 0.9525 against a
# vaguer, unrelated "the insurer promises to cover certain risks" point.
#
# Round 2 (score only, raised to 0.98): reduced but didn't eliminate the
# problem. A live health-insurance answer produced FALSE positives
# scoring 0.9827-0.9924 — e.g. "Understanding the terms and conditions of
# the policy is crucial..." (a generic closing-type remark) matched
# "The insurer covers hospitalization for disease, sickness, or injury..."
# (a specific coverage fact) at 0.9907. These false-positive scores
# directly OVERLAP the genuine-duplicate range (0.9818-1.0000) — no single
# score threshold cleanly separates them. The cross-encoder is
# systematically fooled by a vague/generic point reading as "related to"
# — not necessarily "restating" — a specific, information-dense one.
#
# Round 3 (added the word-overlap floor): the same real examples' word
# Jaccard (content words only, stopwords stripped) showed a real gap the
# score alone didn't: genuine duplicates measured 0.22-0.32 overlap, every
# false-positive case measured 0.00-0.11, and one legitimately-ambiguous
# case (a point listing SPECIFIC extra features vs a point naming only
# the base coverage) sat at 0.17 — appropriately excluded by requiring
# both signals, since dropping it would have lost real detail. This
# combined check is deliberately conservative (biased toward missing a
# softer-worded duplicate over ever merging two genuinely different
# points) — consistent with this file's general stance that a false
# positive (dropping real content) is worse than a false negative here.
_DUPLICATE_POINT_THRESHOLD = 0.98
_DUPLICATE_POINT_JACCARD_FLOOR = 0.20
_DUPLICATE_POINT_STOPWORDS = frozenset({
    'the', 'a', 'an', 'is', 'are', 'of', 'to', 'and', 'or', 'in', 'on', 'for',
    'with', 'that', 'this', 'these', 'those', 'it', 'its', 'be', 'can', 'will',
    'up', 'at', 'as', 'by', 'from', 'includes', 'include', 'including', 'such',
    'other', 'related',
})


def _duplicate_point_word_overlap(a: str, b: str) -> float:
    """Jaccard overlap of content words (stopwords stripped) between two
    points — the second signal in _DUPLICATE_POINT_THRESHOLD's gate. See
    that constant's comment for why score alone isn't reliable enough.
    """
    wa = {w for w in re.findall(r"[a-z']+", a.lower()) if w not in _DUPLICATE_POINT_STOPWORDS}
    wb = {w for w in re.findall(r"[a-z']+", b.lower()) if w not in _DUPLICATE_POINT_STOPWORDS}
    if not wa or not wb:
        return 0.0
    return len(wa & wb) / len(wa | wb)


async def _verify_points_are_duplicate(point_a: str, point_b: str) -> bool:
    """LLM confirmation gate for BOTH numbered-point dedup mechanisms in
    this file (_DUPLICATE_POINT_THRESHOLD's reranker-score check, and the
    separate cosine+jaccard "semantic dedup" pass) — called only on the
    minority of pairs the cheap heuristic already flagged as a candidate
    duplicate, same efficiency shape as _verify_point_faithfulness's own
    vLLM-flags/Groq-confirms design.

    Confirmed live (2026-08-27), user-directed ("if the answer is
    grounded then it shouldn't be dropped even if phrasing is different
    — smarter, not mugging up"): cosine+jaccard alone cannot reliably
    tell "the same fact said twice" apart from "a different fact that
    happens to explain itself relative to an earlier point." Two
    confirmed real cases, both scoring comfortably inside what this
    file's own jaccard floor treats as "genuine duplicate" range: (1)
    "Package Policy – covers loss or damage to the vehicle... IN
    ADDITION TO the liability only coverage mentioned above" (cosine=
    0.818, jaccard=0.240) dropped as a restatement of "Liability Only
    Policy" — these are two DIFFERENT, real motor insurance products,
    not the same fact; Package Policy adds a real, distinct fact (vehicle
    damage cover) the answer needs. (2) "Reimbursement Claim — IF YOU
    CHOOSE NOT TO use a hospital within your insurer's network..."
    (cosine 0.748-0.803, jaccard 0.200-0.219) dropped as a restatement
    of "Pre-Authorisation Request" (the cashless, in-network path) —
    these are two genuinely different claim PROCEDURES for two
    different scenarios, not a restatement; a real "how do I file a
    health claim" answer needs both. Both false positives share the
    same shape: the SECOND point uses relational/contrastive language
    ("in addition to", "if you choose not to") that explains its
    relationship to the first point, which floods embedding similarity
    and lexical overlap with shared procedural vocabulary regardless of
    how different the underlying facts actually are.

    Fail-open toward KEEPING both points on any failure/timeout/empty
    response — the risk direction here is losing real, grounded content
    the answer needs, not the risk of showing a genuine restatement
    twice (mildly redundant, not wrong). This is the opposite fail
    direction from _verify_point_faithfulness (which fails toward
    dropping/refusing on repeated unreachability) because the two checks
    protect against opposite failure modes: faithfulness protects against
    showing something FALSE, this protects against silently REMOVING
    something TRUE.
    """
    if not point_a or not point_a.strip() or not point_b or not point_b.strip():
        return False
    prompt = (
        "Do these two numbered points from the same insurance answer state "
        "the SAME underlying fact, or genuinely DIFFERENT facts — even if "
        "related, or if one explains itself relative to the other using "
        "words like \"in addition to\" or \"if you choose not to\"? Two "
        "different named products, two different scenarios, or two "
        "different steps in a process are DIFFERENT facts, not the same "
        "one restated.\n"
        f'Answer with yes/no. "point A": {point_a[:500]} '
        f'"point B": {point_b[:500]} "same fact":'
    )
    try:
        raw = await _backend_completion(prompt, max_tokens=10, timeout=15.0)
        if not raw:
            return False
        cleaned = re.sub(r"[^a-z\s]", "", raw.strip().lower())
        words = set(cleaned.split())
        return "yes" in words and "no" not in words
    except Exception:
        return False


async def _verify_chunks_are_duplicate(chunk_a: str, chunk_b: str) -> bool:
    """LLM confirmation gate for the same-section chunk-dedup consolidation
    in ask_stream (see that block's own comment) — same two-signal-then-
    LLM shape as _verify_points_are_duplicate just above, adapted for raw
    retrieved source chunks rather than an answer's own numbered points.

    Confirmed live (2026-09-09): the (heading, policy_type)-only gate this
    supports was silently collapsing 5 genuinely different "Common
    Exclusions" chunks from health_insurance_guide.pdf (pre-existing
    diseases, cosmetic surgery, dental, infertility, self-inflicted injury,
    waiting period, treatment abroad — one bullet item per chunk) down to
    just 1, because a KB shape the original consolidation wasn't designed
    for — several chunks legitimately SHARING one heading as siblings of
    the SAME list, not two different guides duplicating the same content —
    looks identical to a true duplicate pair under a heading+policy_type-
    only check. That silent drop starved both the generation prompt (the
    model only ever saw 1 exclusion) and SRG's own cross-chunk bullet-
    enumeration repair (which needs 3+ surviving sibling chunks to even
    recognize a list is there). Fail-open toward KEEPING both chunks on
    any doubt/failure — same reasoning as _verify_points_are_duplicate:
    the risk here is silently losing a real, distinct fact from the
    context the model and SRG both depend on, not showing mildly
    redundant source content twice.
    """
    if not chunk_a or not chunk_a.strip() or not chunk_b or not chunk_b.strip():
        return False
    prompt = (
        "Do these two chunks retrieved from an insurance knowledge base "
        "state the SAME underlying fact/content (e.g. two different guides "
        "describing the same thing), or are they genuinely DIFFERENT facts "
        "— such as two different sibling items from the same list (two "
        "different exclusions, two different required documents, two "
        "different steps in a process) that merely share the same section "
        "heading? Different sibling items under one shared heading are "
        "DIFFERENT facts, not the same one restated.\n"
        f'"chunk A": {chunk_a[:600]} '
        f'"chunk B": {chunk_b[:600]} "same fact":'
    )
    try:
        raw = await _backend_completion(prompt, max_tokens=10, timeout=15.0)
        if not raw:
            return False
        cleaned = re.sub(r"[^a-z\s]", "", raw.strip().lower())
        words = set(cleaned.split())
        return "yes" in words and "no" not in words
    except Exception:
        return False


def _score_points_against_query(query: str, points: List[str]) -> List[float]:
    """Score each point in *points* for query-relevance via the shared
    cross-encoder reranker, in a single batched .predict() call — reused
    by the contamination trace (log-only) and, once enabled, the Phase-2
    topic-relevance gate. Returns [] on any failure (model not loaded,
    empty points, etc.) rather than raising — a scoring failure must
    never affect the answer itself, only the diagnostic/gate that
    consumes the scores, and those callers already treat an empty list
    as "no signal, don't act."
    """
    if not points or not query:
        return []
    try:
        reranker = _get_shared_reranker()
        pairs = [(query, p) for p in points]
        scores = reranker.predict(pairs)
        return [float(s) for s in scores]
    except Exception as exc:
        logger.debug("[contamination] point-relevance scoring failed: %s", exc)
        return []


def _is_likely_followup(question: str) -> bool:
    """Heuristic: is this question likely a follow-up referencing a previous topic?"""
    words = question.strip().split()
    q_lower_early = question.lower().strip()
    if len(words) > 12:
        # "Long questions are usually self-contained" only holds when the
        # question actually names its own topic. Confirmed live this
        # breaks down otherwise: a 20-word, mostly-filler follow-up ("but
        # i have submitted the money on the monthly so what would happen
        # to my money that i have submitted") named no insurance type at
        # all -- "money" alone is undefined without knowing which policy
        # -- but cleared this gate's old flat 12-word cutoff and got
        # treated as self-contained. retrieval_query then stayed the bare
        # 20-word sentence instead of being anchored to the term-life-
        # policy-expiry context established two turns earlier, and the
        # answer had to hedge across every possible policy type ("if
        # you're referring to term life... if it's a savings/investment-
        # linked policy...") instead of directly answering the one
        # already in play. A genuinely long, standalone new question that
        # names its own topic ("difference between comprehensive and
        # third-party motor insurance for a 5-year-old car") still
        # correctly clears this gate; one that doesn't name any type
        # doesn't, regardless of length. Over-triggering this check for a
        # genuinely fresh long question just costs one extra
        # _reformulate_query call -- that prompt already reliably echoes
        # a self-contained question back unchanged rather than corrupting
        # it, so the failure mode here is asymmetric: worth the latency to
        # avoid the alternative (silently un-anchored retrieval).
        return not _SPECIFIC_TYPE_RE.search(q_lower_early)
    tokens = {w.lower().strip('?.,!') for w in words}
    q_lower = question.lower().strip()

    # Existing checks: pronoun-like tokens and fixed opener phrases
    if bool(tokens & _FOLLOWUP_SIGNALS) or any(q_lower.startswith(op) for op in _FOLLOWUP_OPENERS):
        return True

    # Modifier-only request with no insurance vocabulary → clearly a follow-up.
    # Covers "can you explain with the help of an example" (example, 9 words),
    # "explain in simple language" (simple), "can you explain in more detail" (detail),
    # "in simple language with example", "in detail with simple language", etc.
    # The 6-word keyword check below misses these because of the word-count gate.
    _all_modifier_signals = _DETAIL_SIGNALS | _SIMPLE_SIGNALS
    if (
        any(sig in q_lower for sig in _all_modifier_signals)
        or _wants_example(q_lower)
        or _DETAIL_PATTERN.search(q_lower)
    ):
        from re import compile as _re_compile
        _II_QUICK = _re_compile(
            r"\b(insurance|policy|premium|deductible|coverage|claim|health|medical|"
            r"life|motor|travel|home|vehicle|accident|liability|rider|annuity|pension)\b"
        )
        if not _II_QUICK.search(q_lower):
            return True

    # Additional keyword check: short messages (<= 6 words) that contain a
    # follow-up keyword but NO actual insurance vocabulary are likely referential
    # follow-ups ("explain further", "why though", "expand on that").
    if len(words) <= 6:
        stripped_tokens = {w.strip(".,!?;:()[]{}'\"") for w in words}
        if stripped_tokens & _FOLLOWUP_KEYWORDS:
            # If the question contains real insurance vocabulary it's
            # self-contained, not a follow-up.
            from re import compile as _re_compile
            _INSURANCE_INDICATORS_LOCAL = _re_compile(
                r"\b("
                r"insurance|policy|premium|deductible|coverage|claim|claims|"
                r"insure|insured|insurer|underwriting|underwrite|"
                r"cover|covered|covers|covers? (?:for|against|up to|of|on)|"
                r"premiums|co-pay|copay|deductibles|"
                r"health|medical|hospital|surgery|prescription|medication|"
                r"vehicle|car|motor|auto|bike|two-wheeler|four-wheeler|"
                r"travel|trip|flight|baggage|luggage|cancellation|"
                r"life|term life|whole life|endowment|ulip|"
                r"home|house|property|rental|landlord|tenant|"
                r"accident|disability|critical illness|cancer|"
                r"liability|third.party|comprehensive|"
                r"limit|limits|sum insured|sum.assured|"
                r"maternity|dental|vision|"
                r"agent|broker|renewal|grace period|waiting period|"
                r"no.claim|ncb|bonus|"
                r"nominee|beneficiary|"
                r"claim (?:form|process|settlement|rejection|approval)|"
                r"cashless|reimbursement|"
                r"roadside assistance|towing|"
                r"personal accident|"
                r"retirement|pension|annuity|"
                r"finance|financial|investment|savings|"
                r"hdfc ergo|icici|bajaj|tata aig|reliance|"
                r"new india|oriental|national|united india|"
                r"irda|regulator|"
                r"cover note|certi.* of insurance|"
                r"aog|marine|cargo|"
                r"group insurance|corporate|"
                r"rider|add.on"
                r")\b"
            )
            if not _INSURANCE_INDICATORS_LOCAL.search(q_lower):
                return True

    # A short question using only GENERIC insurance-process vocabulary
    # ("claim", "premium", "documents", "cost"...) but no SPECIFIC
    # insurance-type noun (motor, life, health, travel, home...) still
    # depends on whatever type was being discussed — it isn't self-contained
    # just because it contains an insurance word. Confirmed live: "How do I
    # file a claim" asked right after "What is life insurance" fell through
    # every check above (no follow-up opener, no _FOLLOWUP_KEYWORDS match,
    # no detail/simple/example modifier) and was treated as a fresh,
    # standalone question — so it skipped _reformulate_query entirely and
    # retrieval ran on the bare, topic-less phrase, returning confident
    # motor-insurance claim content (roadside assistance, police report)
    # instead of anything about life insurance, or a refusal.
    #
    # Same bug class, same fix (2026-09-09): "What are the exclusions?"
    # asked right after a health-insurance coverage answer fell through
    # this exact list for the identical reason — "exclusions" wasn't in
    # it — and was treated as a fresh, standalone question. Confirmed
    # live: retrieval ran on the bare phrase with no policy-type anchor,
    # matched a generic property-insurance "Exclusions" clause instead,
    # and answered a health-insurance follow-up with home-insurance
    # content (war, burglary, earthquake, unoccupied dwelling). Every
    # other word below names a policy ASPECT that exists identically
    # across every insurance type in this KB — exactly the same
    # "generic, not type-specific" shape as claim/premium/documents —
    # so a short question naming only one of these, with no specific
    # type noun, is added here per the standing instruction to fix the
    # whole bug class rather than just the one reported word.
    if len(words) <= 10:
        _GENERIC_PROCESS_RE = re.compile(
            r"\b(claim|claims|premium|premiums|deductible|deductibles|"
            r"policy|policies|documents?|paperwork|process|renew|renewal|"
            r"cancel|cancellation|cost|price|apply|application|"
            r"exclusion|exclusions|benefit|benefits|coverage|"
            r"eligibility|eligible|"
            r"waiting\s*period|sum\s*insured|sum\s*assured|"
            r"terms?|conditions?|"
            r"co.pay|copay|co.payment|"
            r"limits?|sub.limits?|"
            r"discount|discounts|no.claim\s*bonus|ncb|"
            r"add.on|add.ons|rider|riders)\b"
        )
        if _GENERIC_PROCESS_RE.search(q_lower) and not _SPECIFIC_TYPE_RE.search(q_lower):
            return True

    return False


_REACTION_LEADIN_RE = re.compile(
    r"^(oh\s+)?(okay|ok|alright|got it|i see|gotcha|ah|"
    r"that makes sense|makes sense|interesting|nice|cool|great|awesome|"
    r"good to know|noted|thanks|thank you)\b",
    re.IGNORECASE,
)
_REACTION_QUESTION_RE = re.compile(
    r"\?|\b(what|how|why|when|where|which|who|can you|could you|do you|does it|"
    r"is it|is there|are there|will it|would it|should i)\b",
    re.IGNORECASE,
)


def _is_conversational_reaction(question: str) -> bool:
    """True for a longer acknowledgment/reaction with no retrieval-worthy
    question content, e.g. "Oh okay that makes sense, I didn't know it
    needed forced entry specifically." Confirmed live: at 13 words this is
    past _is_likely_followup's 12-word "long questions are usually
    self-contained" cutoff, so it fell through to standalone KB retrieval,
    found nothing (it isn't a question, there's nothing to retrieve), and
    triggered an unnecessary refusal + human-escalation email for a
    message that was never actually asking anything.

    Deliberately a separate check rather than folded into
    _is_likely_followup — that function's word-count gate is tuned for
    actual follow-up QUESTIONS, and loosening it risks the same
    fragile-signal-list regressions documented elsewhere in this file
    (_SIMPLE_SIGNALS/_DETAIL_SIGNALS). This only needs to catch pure
    acknowledgments: it requires a reaction lead-in AND the absence of any
    question-request pattern, so a message like "oh interesting, but does
    it also cover theft without forced entry?" still gets treated as a
    real question, not a reaction, and goes through normal retrieval.
    """
    q = question.strip()
    if not q or not _REACTION_LEADIN_RE.match(q):
        return False
    return not _REACTION_QUESTION_RE.search(q)


# Specific insurance-type nouns, used only to deterministically re-anchor a
# reformulated follow-up whose LLM rewrite silently dropped the topic — see
# the repair step inside _reformulate_query for why this exists.
#
# This list is fixed-phrase and therefore fragile by construction (same
# class as _SIMPLE_SIGNALS/_DETAIL_SIGNALS — see the fragile-signal-lists
# note elsewhere in this file): any KB topic missing from it is invisible to
# both the "does the question already name a type" check AND the "what type
# did history establish" check below. Confirmed live: "actually never mind
# that, what does aviation insurance cover" (a self-contained, explicitly
# topic-switched question) failed BOTH checks because "aviation" wasn't
# here, so the repair below wrongly force-appended "medical insurance" left
# over from the prior turn — corrupting retrieval into pulling travel-
# insurance chunks and answering with travel-insurance content (medical
# evacuation, air ambulance) under the "aviation insurance" heading. Cross-
# checked the KB's actual document text for other real, well-represented
# (7+ chunk) types missing here — aviation, burglary, workmen's
# compensation, fidelity guarantee, engineering, business interruption,
# micro-insurance, and unit-linked all had solid, dedicated content and
# were missing; added all of them rather than just the one that happened to
# get hit, per the standing instruction to fix the whole bug class.
_ANCHOR_TYPE_RE = re.compile(
    r"\b(term|motor|car|vehicle|auto|bike|two.wheeler|four.wheeler|"
    r"life|whole\s*life|endowment|ulip|unit.linked|"
    r"health|medical|"
    r"travel|trip|aviation|"
    r"home|house|property|householder|"
    r"marine|cargo|fire|burglary|"
    r"liability|third.party|public\s*liability|"
    r"critical\s*illness|"
    r"group|corporate|micro|"
    r"personal\s*accident|personal\s*insurance|road\s*accident|accident|disability|workmen.?s?\s*compensation|"
    r"employer.?s?\s*liability|fidelity(?:\s*guarantee)?|"
    r"engineering|business\s*interruption|"
    r"retirement|pension|annuity|takaful|"
    r"crop|agricultur\w*)\b(\s+insurance)?",
    re.IGNORECASE,
)

# The hardcoded list above will keep having this exact gap for every future
# insurance type a new KB document introduces — it was already missed once
# for 9 real, well-represented types before anyone noticed. Rather than
# relying solely on a human to notice and patch the list again next time,
# derive additional candidate types directly from the KB's own document
# text at runtime, so a newly-added document's type is picked up
# automatically without a code change. This is intentionally additive
# (union with the hardcoded list, never a replacement) — the hardcoded list
# is a reliable floor; the mined list only ever adds coverage on top of it,
# so a bad or missing mined term can't remove something that used to work.
_STOPWORD_TAIL_RE = re.compile(
    r"^(the|a|an|in|on|at|for|to|and|or|with|by|from|as|is|are|was|were|"
    r"this|that|these|those|notes?|project|safe|duty|double|effective|"
    r"comprehensive|differentiation|construction|energy|other|all|each|"
    r"such|said|above|below|certain|various|special|select|digital|"
    r"modified|pure|floater|united|india|royal|london|globe|triton|"
    r"oriental|indian|mercantile|national|public|sector|commercial|"
    r"operational|variable|savings|regulations?|affecting|framework|"
    r"governance|licensing|provisions|categor(?:y|ies)|role|history|"
    r"report|period|preconditions|commencement|registration|"
    r"certification|coverage|course|application|countering|fraud|agents|"
    r"appointed|controller|fellow|wing)$"
)
_KB_TYPE_PHRASE_RE = re.compile(r"\b((?:[A-Z][a-z]+'?s?\s+){0,2}[A-Z][a-z]+)\s+Insurance\b")
_MIN_KB_TYPE_FREQ = 3

def _discover_kb_anchor_types(vector_store) -> set:
    """Mine specific insurance-type phrases directly from the KB's chunk
    text, to extend _ANCHOR_TYPE_RE with types no one has hardcoded yet.

    Looks for 1-3 capitalized words immediately before "Insurance" (e.g.
    "Aviation Insurance", "Officers Liability Insurance") — requiring
    capitalization is what keeps this clean without heavy NLP: genuine
    product/type names are capitalized in this KB's prose, while stray
    connector words ("the", "of the", "an") almost never are. What survives
    that filter still needs two more passes to be usable as a topic anchor:
    a small blocklist for document-structure/regulatory vocabulary and
    insurer company names that happen to be capitalized too ("Oriental
    Insurance", "United India Insurance" are companies, not types), and a
    minimum-frequency bar to drop one-off mentions. A last pass drops any
    bare single word that's just a fragment of an already-accepted
    multi-word phrase (e.g. bare "linked" once "unit linked" is present) —
    single words carry the most false-positive risk since they're most
    likely to also be ordinary English words.

    Also unions in every value of the KB's own `policy_type` chunk-metadata
    field (e.g. "cyber", "marine") with NO filtering — confirmed live this
    was a real gap the prose-mining alone missed: "cyber insurance" only
    appears in 2 chunks in this KB, below the 3-chunk frequency bar, so it
    silently failed the same topic-switch bug the rest of this mechanism
    exists to prevent ("switching to cyber insurance" after a marine-
    insurance turn got "marine insurance" wrongly re-appended). `policy_type`
    is structured, curated data assigned at ingestion time, not prose
    mined from free text, so it carries none of the false-positive risk
    (company names, sentence fragments) the text-mining pass has to guard
    against — safe to trust unconditionally, and it catches genuinely
    under-represented types the frequency bar would otherwise miss.
    """
    counts: dict = {}
    try:
        docs = vector_store.get_all_by_filter({})
    except Exception:
        logger.debug("[_discover_kb_anchor_types] KB scan failed, using hardcoded list only", exc_info=True)
        docs = []
    for doc in docs:
        text = getattr(doc, "page_content", "") or ""
        for m in _KB_TYPE_PHRASE_RE.finditer(text):
            phrase = m.group(1).strip().lower()
            if len(phrase) < 3:
                continue
            if any(_STOPWORD_TAIL_RE.match(w) for w in phrase.split()):
                continue
            counts[phrase] = counts.get(phrase, 0) + 1
    clean = {p for p, c in counts.items() if c >= _MIN_KB_TYPE_FREQ}
    multiword = {p for p in clean if " " in p}
    final = set()
    for p in clean:
        if " " not in p and any(p in mw.split() for mw in multiword):
            continue
        final.add(p)

    try:
        for policy_type in vector_store.list_values("policy_type"):
            if policy_type:
                final.add(policy_type.strip().lower())
    except Exception:
        logger.debug("[_discover_kb_anchor_types] policy_type lookup failed", exc_info=True)

    return final


_dynamic_anchor_pattern_cache: Optional[re.Pattern] = None

def _get_dynamic_anchor_pattern(vector_store) -> re.Pattern:
    """_ANCHOR_TYPE_RE extended with types mined live from the KB, computed
    once per process and cached — the KB doesn't change size often enough
    to justify re-scanning every request. Call _reset_dynamic_anchor_cache()
    after adding new documents to pick up their types without a restart.
    Falls back to the bare hardcoded pattern on any failure so a KB-scan
    problem degrades to the old (safe, previously-shipped) behavior rather
    than breaking reformulation entirely.
    """
    global _dynamic_anchor_pattern_cache
    if _dynamic_anchor_pattern_cache is not None:
        return _dynamic_anchor_pattern_cache
    try:
        discovered = _discover_kb_anchor_types(vector_store)
        new_terms = sorted(discovered - _hardcoded_anchor_terms())
        if new_terms:
            logger.info("[_get_dynamic_anchor_pattern] mined %d new anchor type(s) from KB: %r", len(new_terms), new_terms)
        if new_terms:
            extra = "|".join(re.escape(t) for t in new_terms)
            pattern = re.compile(
                _ANCHOR_TYPE_RE.pattern.replace(r")\b(\s+insurance)?", f"|{extra})\\b(\\s+insurance)?"),
                re.IGNORECASE,
            )
        else:
            pattern = _ANCHOR_TYPE_RE
        _dynamic_anchor_pattern_cache = pattern
        return pattern
    except Exception:
        logger.debug("[_get_dynamic_anchor_pattern] falling back to hardcoded pattern", exc_info=True)
        return _ANCHOR_TYPE_RE


# Plain-text mirror of the alternatives inside _ANCHOR_TYPE_RE, used only to
# avoid logging an already-hardcoded term as "newly discovered" from the KB.
# Kept as an explicit set rather than reverse-parsed from the compiled
# pattern's regex source — an earlier version tried stripping backslashes
# out of the pattern string directly, which mangled `\s*`-joined terms
# ("personal\s*accident" -> "personalsaccident" instead of "personal
# accident") and made genuinely-already-hardcoded terms look new in the
# discovery log. This set going stale (someone edits _ANCHOR_TYPE_RE
# without updating it) only costs a cosmetic duplicate log line, never
# breaks matching — the dynamic pattern still unions in the "duplicate"
# term harmlessly.
_HARDCODED_ANCHOR_TERMS = {
    "term", "motor", "car", "vehicle", "auto", "bike", "two wheeler", "four wheeler",
    "life", "whole life", "endowment", "ulip", "unit linked",
    "health", "medical",
    "travel", "trip", "aviation",
    "home", "house", "property", "householder",
    "marine", "cargo", "fire", "burglary",
    "liability", "third party", "public liability",
    "critical illness",
    "group", "corporate", "micro",
    "personal accident", "personal insurance", "disability", "workmens compensation",
    "employers liability", "fidelity", "fidelity guarantee",
    "engineering", "business interruption",
    "retirement", "pension", "annuity", "takaful",
    "crop", "agriculture",
}

def _hardcoded_anchor_terms() -> set:
    return _HARDCODED_ANCHOR_TERMS


def _reset_dynamic_anchor_cache() -> None:
    """Force the next _get_dynamic_anchor_pattern() call to re-scan the KB —
    call this after documents are added/removed so new types are picked up
    without a container restart."""
    global _dynamic_anchor_pattern_cache
    _dynamic_anchor_pattern_cache = None


def _last_anchor_type_match(text: str, pattern: re.Pattern = _ANCHOR_TYPE_RE) -> Optional[str]:
    """Last (most recent) specific-insurance-type phrase mentioned in *text*,
    or None.

    Checks the most recent "User:" turn first — the user's own wording is
    the authoritative signal for what topic they actually asked about. The
    "Assistant:" turn often re-describes it via a broader category ("Term
    insurance is a type of life insurance...") which, under a plain
    last-match-anywhere search, would wrongly outrank the real, more
    specific topic the user named ("term") just because "life insurance"
    happens to appear later in the same turn's prose. Only falls back to
    searching the whole text when the user's own turn has no type mention
    (e.g. a topic introduced solely by the assistant, never restated).

    The fallback (assistant-only) search requires the matched type to
    appear at least twice in *text* — a single occurrence is often just an
    illustrative aside within an otherwise generic answer, not the actual
    established topic. Confirmed live: "What does the policy document
    include?" (names no type) got an answer that mentioned "Fire Insurance"
    exactly once, as a passing example among several ("...in Fire Insurance
    the particulars of the building...", alongside a car-insurance example
    in the same sentence) — a plain last-match-anywhere search still picked
    it up as "the established topic" and the repair step below injected
    "for fire insurance" into a follow-up about something else entirely
    ("how can relatives be informed about the policy?"), reintroducing the
    exact type-hallucination failure the _reformulate_query LLM-prompt
    guardrail was built to prevent — this deterministic repair runs after
    that LLM call and isn't covered by its prompt instructions at all. A
    genuinely-established topic (the documented term-insurance/"how to
    claim it?" case this repair exists for) is discussed substantively
    enough to be named more than once, so the frequency check doesn't
    weaken the intended case.
    """
    user_turns = re.findall(r"User:\s*(.*?)(?=\n(?:User|Assistant):|\Z)", text, re.DOTALL)
    if user_turns:
        user_matches = list(pattern.finditer(user_turns[-1]))
        if user_matches:
            phrase = user_matches[-1].group(0).strip()
            if not re.search(r"insurance\s*$", phrase, re.IGNORECASE):
                phrase = f"{phrase} insurance"
            return phrase

    matches = list(pattern.finditer(text))
    if not matches:
        return None
    base_counts: dict = {}
    for m in matches:
        base = m.group(0).strip().lower().split()[0]
        base_counts[base] = base_counts.get(base, 0) + 1
    phrase = matches[-1].group(0).strip()
    if base_counts[phrase.lower().split()[0]] < 2:
        return None
    if not re.search(r"insurance\s*$", phrase, re.IGNORECASE):
        phrase = f"{phrase} insurance"
    return phrase


# Legislative/tax/administrative boilerplate — a chunk matching this is
# almost never what a consumer-facing question is actually asking about,
# even when it happens to name the right insurance type (e.g. "the Act
# guarantees amounts assured by LIC policies" mentions "life insurance"
# but is about a government solvency guarantee, not payout amounts). See
# _prioritize_topic_chunks's docstring for the concrete failure this fixes.
#
# "ICP \d+" and "the supervisor" extend this to insurance-REGULATOR/
# supervisory-framework boilerplate (IAIS Insurance Core Principles text —
# licensing, board-member suitability, governance requirements aimed at
# insurers-as-regulated-entities). Confirmed live: "How can relatives be
# informed about the policy?" cross-encoder-scored a chunk about board-
# member/significant-owner suitability licensing at 0.94 — higher than
# every genuinely relevant chunk in the pool — even though the selected
# rerank window didn't contain the word "relative" at all. Same underlying
# judgment as the original regulatory-boilerplate case: this class of
# supervisor-facing governance text is essentially never what a consumer
# question wants, regardless of how the cross-encoder happens to score it.
# "the supervisor" specifically (not "the regulator"/"the authority" more
# broadly, which are too generic and risk false-positiving on unrelated
# content) because in this KB's consumer-facing prose the acting party is
# always "the insurer"/"the insured"/"the policyholder"/"the agent" — "the
# supervisor" only appears in the regulatory-oversight framework sections.
# "grievance redressal|adjudicat\w*" extends this to the same category
# confirmed live via the hollow-answer investigation: "my claim got
# rejected, what do I do" retrieved a chunk about IRDA's statutory power to
# adjudicate disputes between insurers and intermediaries — regulatory/
# supervisory content about the regulator's OWN powers, not a consumer-
# facing "how do I appeal my own claim" answer, but lexically close enough
# ("claim", "dispute") to score highly on the cross-encoder anyway. Scoped
# tightly to just these two terms after confirming live they're safe:
# every occurrence of "adjudicat*" in this KB (8/8) and a sample of
# "grievance redressal" occurrences are exclusively inside the IRDA
# statutory-powers listing, never inside consumer-facing policy content.
# Broader candidates considered and REJECTED after they caused a real
# regression on a well-covered compound question (fire + burglary
# insurance): bare "irda\b" and "insurance intermediar*" both appear
# routinely in ordinary consumer-education content in this KB (a table of
# contents entry, a "what is an intermediary" explainer chunk) — nowhere
# near narrow enough to safely exclude without also demoting genuinely
# relevant chunks that happen to mention the regulator or agents/brokers
# in passing.
_REGULATORY_BOILERPLATE_RE = re.compile(
    r"\b(the act|the bill|stamp duty|income tax act|central government|"
    r"section\s+\d+[a-z]?\b.{0,20}\bact\b|"
    r"guarantee[sd]?\s+by\s+the\s+(central\s+)?government|"
    r"amends?\b|gross\s+total\s+income|"
    r"icp\s*\d+|the\s+supervisor|"
    r"grievance\s+redressal|adjudicat\w*)\b",
    re.IGNORECASE,
)

# Chapter-end review/index material — never substantive answer content, but
# can still slip past the topic-match check above because it name-drops
# every type covered in that chapter as part of a summary or self-test
# question ("5. What do you mean by Motor Insurance?"). Confirmed live:
# "Explain motor insurance in detail" top-scored (0.475, the single
# highest-ranked candidate) a chunk that is actually a "General Insurance
# Products" survey listing crop and fidelity insurance, plus its chapter's
# self-test questions — it only survived the topic filter because "Motor
# Insurance" happens to appear inside one of those review questions, not
# because the chunk is actually about motor insurance. A chunk whose real
# subject is a review/index of MULTIPLE topics should never outrank one
# that's actually about the queried topic, regardless of what it name-drops.
_CHAPTER_REVIEW_RE = re.compile(
    r"\b(self.test questions?|lesson round.?up|(?:are\s+)?meant\s+for\s+re.capitulation)\b",
    re.IGNORECASE,
)


def _prioritize_topic_chunks(retrieval_query: str, chunks: list) -> list:
    """Reorder *chunks* so ones whose content mentions the query's named
    insurance type (e.g. "health insurance") come before ones that don't —
    same relative order preserved within each group (stable sort), so this
    only ever changes ORDER, never which chunks are included.

    Exists for two related failure modes, both confirmed live:
    (a) a generic, universal-to-any-policy glossary chunk outranking
    genuinely topic-specific content sitting right next to it in the same
    retrieved pool (see DETAILED_GROUNDED_PROMPT/STRICT_GROUNDED_PROMPT's
    "prioritize topic-specific content" rule, which helped but wasn't
    reliable alone), and (b) a chunk from a DIFFERENT insurance type
    entirely outranking the correct one because the wording happens to be
    lexically/semantically similar — confirmed with "are all types of
    illness covered under health insurance?": the top-scoring chunk (0.78)
    was travel insurance's exclusion list ("illnesses or injuries that
    occurred... before the start of the journey"), correctly rejected by
    the semantic grounding check as not actually about health insurance —
    but that refusal meant a REAL health-insurance exclusion chunk sitting
    lower in the same pool (0.10, cosmetic/aesthetic treatment exclusions)
    never got a chance to ground the answer either. Reordering so the
    correct-topic chunk is physically first gives it a chance to be what
    the coverage/grounding checks and generation actually see and use.

    A no-op when the query doesn't name a specific type (single-word
    concept lookups like "what is a deductible" are unaffected).

    Chunks matching _REGULATORY_BOILERPLATE_RE never count as a "topic
    match" for promotion, even when they literally contain the topic
    phrase. Confirmed live: "How much does life insurance pay out?"
    promoted a weak (0.10) chunk about the Insurance Act's central-
    government solvency guarantee for LIC purely because it contains the
    words "life insurance" — ahead of a higher-scoring but wrong-topic
    (health insurance) chunk. That regulatory chunk doesn't answer "how
    much", but the grounding check judged it "relevant enough" anyway
    (reproduced 15/15 across 5 different prompt phrasings, including ones
    naming this exact failure as an explicit exclusion — this is a hard
    model limitation, not a prompt-wording gap, so it's addressed here at
    the reordering step instead of asking the LLM to see through it).
    Legislative/tax/administrative boilerplate is essentially never what a
    consumer-facing "what/how much/how" question is looking for even when
    it happens to name the right insurance type — see _reformulate_query's
    existing "do not add a specific regulation, act, section... unless
    already named" rule for the same underlying judgment applied earlier
    in the pipeline.

    The boilerplate deprioritization runs even when the query names NO
    specific insurance type (topic is None below) — confirmed live with
    "How can relatives be informed about the policy?" (no type mentioned
    anywhere in the conversation): a supervisory-licensing boilerplate
    chunk outranked every genuinely relevant chunk by cross-encoder score
    alone, and topic-matching had nothing to gate on since there was no
    named topic to check against. Boilerplate is a category judgment
    independent of topic, so it applies unconditionally; only the topic
    promotion half of this function needs a named type to compare against.
    """
    m = _ANCHOR_TYPE_RE.search(retrieval_query)
    topic = m.group(0).lower() if m else None
    def _rank(c) -> int:
        content = (getattr(c, "page_content", "") or "").lower()
        if _REGULATORY_BOILERPLATE_RE.search(content) or _CHAPTER_REVIEW_RE.search(content):
            return 1
        if topic and topic not in content:
            return 1
        return 0
    return sorted(chunks, key=_rank)


async def _question_presupposes_history_type(question: str, history: str) -> bool:
    """Narrow, 3-way LLM classification used by _reformulate_query's own
    topic-anchor repair below: does *question* PRESUPPOSE the insurance
    type already established in *history* (its answer depends on
    inheriting that type), is it asking to DISCOVER/CHOOSE a type from
    scratch, or is it GENERIC (same answer regardless of type)? Only the
    first case should get the historical type force-appended.

    Deliberately given the FULL retained history (up to
    _MAX_HISTORY_TURNS exchanges, api.py), not narrowed to the single
    most recent turn the way _reformulate_query's own rewrite prompt
    below is (see that prompt's own comment for why narrowing helps
    there specifically — it's an open-ended generation task where extra
    turns risk the model borrowing vocabulary from a stale, unrelated
    topic). This is a different, narrower judgment: "what type is this
    conversation ABOUT," which is exactly the kind of question a wider
    window should improve, not hurt — the type may have been established
    several turns back and never restated since, and this app now
    deliberately retains a much larger window (bumped 3 -> 15 exchanges)
    specifically so a longer-running conversation doesn't lose that
    context turn by turn.

    Deliberately a narrow yes/no-shaped question, not an open-ended
    rewrite — confirmed live (2026-09-09) this small local model reliably
    echoes a pronoun-free, content-bearing follow-up back unchanged even
    when explicitly instructed about type-dependency and given a matching
    example (i.e. _reformulate_query's own prompt genuinely cannot be
    trusted to catch this on its own for this exact question shape), but
    the SAME model correctly classifies the narrower 3-way question most
    of the time. Routed through Groq specifically (backend_override, a
    much larger hosted model than this app's default local vLLM one) —
    confirmed live it got all 3 of the following test cases right where
    the local model missed one: (1) "Does treatment received while
    abroad get paid for too?" after a health-coverage turn -> correctly
    PRESUPPOSES health; (2) "what type of insurance should I buy [for
    family protection after death]" after a travel-insurance turn ->
    correctly DISCOVERS, not anchored to travel; (3) "How can relatives
    be informed about the policy?" after a health-coverage turn ->
    correctly GENERIC (the local model wrongly said PRESUPPOSES here,
    which would have appended an unneeded "for health insurance").

    Fails toward True (presupposes -> append the type) on any error/
    timeout/empty response: the risk this repair exists to prevent
    (silently answering the wrong insurance type entirely) is worse than
    its own failure mode (an occasional unneeded type qualifier appended
    to a genuinely type-independent question).
    """
    prompt = (
        f"Conversation so far:\n{history}\n\n"
        f"New question: {question}\n\n"
        "Does this new question PRESUPPOSE a specific insurance type/policy "
        "already established in the conversation above (i.e. its answer "
        "would depend on inheriting that same type)? Or is it asking the "
        "user to DISCOVER/CHOOSE a type from scratch (e.g. \"what type of "
        "insurance should I buy\"), independent of what was discussed "
        "before? Or is it a GENERIC question whose answer is the same no "
        "matter which insurance type is involved? Answer with exactly one "
        "word: PRESUPPOSES, DISCOVERS, or GENERIC."
    )
    try:
        raw = await _backend_completion(prompt, max_tokens=10, timeout=10, backend_override="groq")
        if not raw:
            return True
        return raw.strip().upper().startswith("PRESUPPOSES")
    except Exception:
        return True


async def _reformulate_query(
    question: str, history: str, anchor_pattern: re.Pattern = _ANCHOR_TYPE_RE,
    selected_recent: Optional[str] = None,
) -> Optional[str]:
    """Rewrite a follow-up question as a standalone, natural-language question
    using conversation history — used both for retrieval and, for detected
    follow-ups, as the literal question text shown to the generation prompt.

    Examples:
      history: "User: tell me about life insurance\nLayla: Life insurance ..."
      question: "what about premiums?"
      returns: "What is the premium amount for life insurance?"

    Uses max_tokens=30 and a 4-second timeout so it adds <0.5 s to latency.

    Returns None on genuine failure (backend call failed/timed out, or
    returned degenerate output) — the caller then falls back to
    _reformulate_with_history. Returns *question* UNCHANGED (not None) when
    the model correctly determines no rewrite is needed — this is a
    successful outcome, not a failure, and must not trigger that fallback:
    the prompt below now explicitly instructs the model to echo an
    already-self-contained follow-up back verbatim rather than force a
    paraphrase (confirmed live: unnecessary rewrites of a fine question —
    adding "typically", "regarding the details of" — introduced wording
    that swung the downstream cross-encoder's relevance score by 10-30x for
    no benefit). Collapsing "unchanged because unnecessary" into the same
    signal as "failed" would defeat that fix by re-triggering the history-
    snippet fallback for a question that didn't need any rewrite at all.
    """
    # Use only the last 2 turns (the single most recent Q&A pair) of history.
    # Used to slice by raw newline count instead of turn boundaries —
    # confirmed live: a multi-paragraph, numbered-list detailed answer alone
    # spans more than 6 newlines, so "last 6 lines" only captured the tail
    # end of the MOST RECENT answer (e.g. "...the lump-sum payment helps
    # Sarah focus on recovery") and never saw the subject established earlier
    # in that same answer ("critical illness insurance"). The follow-up "what
    # is its purpose" got reformulated to "lump-sum payment purpose in
    # insurance policy" — grammatically fine, but missing the actual topic —
    # so retrieval pulled unrelated content and the question was refused.
    # _split_history_turns() slices on "User:"/"Assistant:" boundaries so a
    # long answer is kept whole instead of being cut mid-turn.
    #
    # Window then narrowed 6 -> 2: confirmed live again with a longer, multi-
    # topic conversation (marine insurance -> takaful -> an off-topic aside ->
    # term insurance) — with 3 Q&A pairs of history in view, "explain in
    # detail with an example" got reformulated to "takaful insurance
    # principle example real case", pulling the more distinctive-sounding
    # topic from two turns back instead of the actually-current one (term
    # insurance) from the immediately preceding turn. Generic modifier-only
    # follow-ups ("give me an example", "explain in detail") are asking about
    # whatever was JUST discussed — the single most recent turn is both
    # necessary and sufficient, and including more only risks the model
    # anchoring on an earlier, more salient-sounding topic instead. This
    # matches _contextualize_query's existing narrower window for the same
    # reason.
    #
    # selected_recent (2026-09-07): an optional override from
    # _select_followup_anchor_turn's code-side, embedding-similarity
    # decision — used ONLY when that mechanism found clear, threshold-
    # gated evidence the follow-up is actually about an EARLIER retained
    # turn (not the most recent one), for genuinely indirect/scenario
    # follow-ups with no pronoun/keyword signal at all. Still only ever
    # ONE turn's text — never more — so this does not reintroduce the
    # regression documented above; it only changes, by a fixed rule
    # computed in code before this prompt is ever built, WHICH one turn.
    # None (the default for every existing caller) reproduces the
    # unconditional most-recent-turn behavior above exactly.
    recent = selected_recent if selected_recent is not None else '\n'.join(_split_history_turns(history)[-2:])
    # Output a complete, natural-language QUESTION — not a terse keyword
    # string. The old prompt asked for compact "textbook vocabulary" phrases
    # (e.g. "term insurance detailed explanation example"), which is exactly
    # what the few-shot examples below used to demonstrate. Confirmed live:
    # that exact keyword-salad phrase, tried directly against retrieval,
    # returned an EMPTY context (no chunks matched well enough) even though
    # the natural phrasing of the same request — "explain term insurance in
    # detail with an example" — retrieved rich, correct content and answered
    # fully. The embedding model matches natural sentences against this KB's
    # prose far better than a stripped keyword list. This same string also
    # doubles as the literal "question" shown to the generation prompt for
    # follow-ups (see prompt_question below), where a keyword salad reads as
    # not-a-real-question and biases the model toward refusing — a complete
    # question fixes both problems at once.
    prompt = f"""Rewrite the follow-up question as a complete, standalone, natural-language question using the conversation context.
Use precise insurance/legal terms that would appear in a textbook, but phrase it as a real question a person would ask — not a keyword list.
If the follow-up is ALREADY a complete, self-contained question that doesn't
depend on anything in the conversation below to be understood — no pronoun,
no missing topic, nothing implicit — output it EXACTLY AS-IS, character for
character, changing nothing. Do not add hedging words ("typically",
"usually"), do not add a topic that isn't needed, do not paraphrase just to
sound more natural — an unnecessary rewrite is not an improvement, and
different wording of an already-fine question can retrieve worse results
than the original. Only rewrite when something genuinely needs resolving.
"Reads as a grammatically complete sentence" is NOT the same as "self-
contained" — a question with no pronoun can still silently depend on
context. Before deciding a follow-up needs no rewrite, ask yourself: would
the ANSWER to this question actually differ depending on which specific
insurance type/product is being discussed (e.g. would health, travel, and
motor insurance genuinely answer this differently)? If YES, and the
follow-up itself does not already name a type, it is NOT self-contained —
you must add the type from the conversation even though the sentence
parses fine on its own. Only treat a follow-up as self-contained when
either it already names its own type, or the answer to it genuinely does
not depend on which type is involved at all (a generic administrative/
process question like "how can relatives be informed about the policy" —
that answer is the same regardless of policy type, so it stays unchanged).
The conversation below is ONLY the single most recent exchange — always ground
the follow-up in that topic, never in anything outside what's shown here.
Do NOT add a specific regulation, act, section, jurisdiction, or authority
(e.g. "under federal law", "under section 80C", "under IRDA regulations")
unless the conversation itself already named it — inventing one, even a
plausible-sounding one, measurably hurts retrieval when the actual source
material frames it differently or doesn't cite a specific provision at all.
Same rule for the insurance TYPE itself: do NOT introduce a specific
product name (e.g. "fire insurance", "marine insurance") that appears
NOWHERE in the conversation above AND nowhere in the follow-up itself —
only reuse a product name that was already used somewhere. This is about
not INVENTING a new product name out of nothing — it does not mean
dropping words that already appear in the follow-up; always keep
everything the follow-up itself asks about (e.g. "how can relatives be
informed" must still mention relatives in your rewrite).
If the follow-up ALREADY asks about multiple things joined by "and" (e.g.
"what is X and how to Y"), your rewritten question must keep EVERY part —
never drop a part just because it resembles something already discussed.
Output ONLY the rewritten question — no quotes, no explanation, nothing else.

Examples:
  Context: "User: what does the policy document include?\nLayla: The policy document includes the name and address of the insured, sum insured, period of insurance..."
  Follow-up: "How can relatives be informed about the policy?" → "How can relatives be informed about the policy?" (already self-contained — this answer is the same no matter what type of policy it is, so no type needs adding)

  Context: "User: what is covered under a health insurance policy?\nLayla: treatment for illness or injury, including hospitalisation, diagnostic tests, and medicines, are typically covered under a health insurance policy."
  Follow-up: "Does treatment received while abroad get paid for too?" → "Does health insurance pay for treatment received while abroad?" (NOT self-contained despite having no pronoun — whether this is covered depends entirely on which insurance type is being asked about, so the type must be carried over from the conversation, not left out just because the sentence reads fine on its own)

  Context: "User: tell me about life insurance\nLayla: Life insurance pays out..."
  Follow-up: "what about premiums?" → "What is the premium amount for life insurance?"

  Context: "User: explain life insurance\nLayla: Life insurance protects your family..."
  Follow-up: "is it tax deductible?" → "Are life insurance premiums tax deductible?"

  Context: "User: explain reinsurance\nLayla: Reinsurance is when insurers share risk..."
  Follow-up: "is it legally required?" → "Is reinsurance a legal requirement?"

  Context: "User: what is term insurance\nLayla: Term insurance is a type of life insurance..."
  Follow-up: "what is term insurance and how to claim it?" → "What is term insurance and how do you claim a term insurance policy?"

  Context: "User: what is subrogation\nLayla: Subrogation means the insurer steps in..."
  Follow-up: "give me an example" → "Can you give a real-life example of subrogation?"

  Context: "User: what is a deductible\nLayla: A deductible is what you pay first..."
  Follow-up: "how is it calculated?" → "How is a deductible amount calculated?"

The examples above (life insurance, premiums, reinsurance, subrogation, term
insurance, deductibles) are ONLY illustrations of the rewrite PATTERN — never
pull any topic, product name, or fact from them into your actual output.
Ground the rewrite ONLY in the real Conversation and Follow-up shown below;
if that real conversation is about something else entirely, your rewrite
must be about that, never about anything named in the examples above.

Conversation:
{recent}

Follow-up: {question}
Search query:"""
    reformulated = await _backend_completion(prompt, max_tokens=30, timeout=10)
    if reformulated:
        reformulated = reformulated.strip().strip('"\'')
        if len(reformulated) >= 3:
            # Deterministic repair for a confirmed non-determinism gap: even
            # at temperature=0, this call has been observed live to drop the
            # topic anchor on the *same* input across repeated calls — e.g.
            # "How to claim it?" after a term-insurance turn reformulated to
            # the correctly-anchored "How is a claim for term insurance
            # processed?" on one call, and the topic-less "What are the steps
            # involved in submitting a claim?" moments later on an identical
            # retry (same question, same history). A topic-less reformulation
            # isn't a refusal — it's a *different, legitimately generic*
            # question that goes on to confidently ground against whatever
            # generic claims content ranks highest, a wrong-topic answer that
            # nothing downstream can distinguish from an intentionally
            # generic question. Only repair when the topic could ONLY have
            # come from history (the raw follow-up itself names no specific
            # type) and the rewrite dropped the type history established.
            # Deterministic repair for the inverse gap, also confirmed live
            # (reproduced 3x, intermittently): the rewrite sometimes INVENTS
            # a specific insurance type out of nothing — "How can relatives
            # be informed about the policy?" after a generic policy-document
            # turn (no type named anywhere in the conversation) reformulated
            # to "...policy documents for fire insurance?", so retrieval
            # pulled fire-insurance chunks, the semantic grounding check
            # correctly rejected them, and the question was refused. The
            # prompt above already forbids exactly this and the model still
            # does it intermittently — same model limitation as the anchor-
            # drop case below, so same remedy: enforce in code. Only phrases
            # with an explicit "insurance" suffix are stripped; a bare type
            # word ("property", "group", "fire") is too ambiguous to remove
            # safely from an otherwise-good rewrite. Runs BEFORE the anchor-
            # append repair so that when history DOES name a real type, a
            # stripped wrong-type rewrite can still be re-anchored to it.
            _known_topics = f"{question}\n{recent}"
            # Hyphen/space forms are treated as interchangeable when checking
            # whether a type is "already known" — confirmed live: the raw
            # follow-up said "third party insurance" (space), the LLM's own
            # rewrite correctly wrote "third-party insurance" (hyphen), and
            # a literal-text comparison between the two treated the hyphen
            # form as a brand-new invented type never seen anywhere,
            # stripping "third-party insurance" out of an otherwise-correct
            # rewrite — "How is liability insurance different from
            # third-party insurance?" became the badly broken "How is
            # liability insurance different from?", which then answered a
            # completely different (and unasked) comparison against property
            # insurance instead. Splitting the matched phrase into words and
            # rejoining with a hyphen-or-space-tolerant separator fixes the
            # comparison without weakening the check itself — it's still an
            # exact word-sequence match, just insensitive to which of the
            # two equally-common spellings either side happened to use.
            def _flexible_known(phrase: str) -> bool:
                _words = [w for w in re.split(r"[\s-]+", phrase) if w]
                if not _words:
                    return False
                _pattern = r"[\s-]+".join(re.escape(w) for w in _words)
                return bool(re.search(rf"\b{_pattern}\b", _known_topics, re.IGNORECASE))

            for _ in range(3):  # rescan after each strip; bounded
                _invented = next(
                    (
                        _m for _m in anchor_pattern.finditer(reformulated)
                        if _m.group(2)
                        and not _flexible_known(_m.group(1))
                    ),
                    None,
                )
                if _invented is None:
                    break
                _stripped = re.sub(
                    rf"(?:\s+(?:for|of|in|under|on|about|regarding|with))?\s*\b{re.escape(_invented.group(0))}\b",
                    "",
                    reformulated,
                    flags=re.IGNORECASE,
                )
                _stripped = re.sub(r"\s{2,}", " ", _stripped).strip(" ,;:")
                if _invented.start() == 0 or len(re.findall(r"\w+", _stripped)) < 3:
                    # Invented type was the sentence subject, or stripping
                    # gutted the rewrite — the raw follow-up is safer than
                    # either a wrong-topic or a broken query.
                    logger.info(
                        "[REFORM] invented-type repair: %r names %r found nowhere in the conversation — falling back to raw follow-up",
                        reformulated, _invented.group(0),
                    )
                    reformulated = question
                    break
                logger.info(
                    "[REFORM] invented-type repair: %r names %r found nowhere in the conversation — stripped to %r",
                    reformulated, _invented.group(0), _stripped,
                )
                reformulated = _stripped
            # Searches the FULL retained history (not just `recent`, the
            # single-most-recent-turn slice the rewrite prompt above
            # deliberately narrows to) — the established type may sit
            # several turns back and never get restated since, and this
            # app now deliberately retains up to _MAX_HISTORY_TURNS
            # exchanges (api.py) specifically so that context survives a
            # longer conversation. _last_anchor_type_match already always
            # returns the MOST RECENT mention regardless of window size,
            # so widening this is safe — it can only find a real anchor
            # it would otherwise have missed, never pick a stale one over
            # a newer one.
            _hist_anchor = _last_anchor_type_match(history, pattern=anchor_pattern)
            if (
                _hist_anchor
                and not anchor_pattern.search(question)
                and not anchor_pattern.search(reformulated)
                # Content gate (2026-09-08, replaced 2026-09-09): this
                # repair exists to catch a follow-up losing the type
                # context it needs — but naively re-anchoring ANY
                # question missing a type word, even one with real
                # content of its own, risks the exact regression this
                # gate was originally built to prevent: "If I have to
                # protect my family from financial burden after my death
                # what type of insurance policy should I buy" (no "life"
                # anywhere) after a "What is travel insurance?" turn is a
                # genuine NEW question, not a travel follow-up, and must
                # not get "for travel insurance" appended. The original
                # fix was a blunt content-word check (_extract_topic_
                # terms) — safe, but it meant ANY follow-up with its own
                # content words never reached this repair at all, which is
                # exactly what let "Does treatment received while abroad
                # get paid for too?" (real content words, but genuinely
                # still about the established health-insurance topic)
                # fall through unrepaired. Replaced with a narrow LLM
                # classification of the actual distinction that matters —
                # does this question PRESUPPOSE the established type, or
                # is it asking to DISCOVER a new one / genuinely type-
                # independent — see _question_presupposes_history_type's
                # own docstring for the three confirmed live test cases
                # (including this exact regression case, still correctly
                # left unanchored) this was verified against before
                # replacing the cruder check.
                and await _question_presupposes_history_type(question, history)
            ):
                logger.info(
                    "[REFORM] topic-anchor repair: %r missing %r from history — appending",
                    reformulated, _hist_anchor,
                )
                reformulated = f"{reformulated.rstrip('?.! ')} for {_hist_anchor}?"
            logger.info("[REFORM] %r -> %r", question, reformulated)
            return reformulated
    return None


_INTENT_PROMPT = """\
Read the insurance question below and classify its content words/phrases into two groups.

SPECIFIC = names a particular concept, country, provider, rule, or number that only
           documents actually discussing that exact thing would contain.
GENERIC  = so common it appears in almost EVERY insurance document regardless of
           topic — quality/selection words (best, choose, recommend), audience
           words (family, individual, personal), or filler (important, options).

Output EXACTLY two lines, nothing else. Use "(none)" if a group is empty.
Keep specific compound terms together (e.g. "no-claim bonus", "free look period").

Examples:
Question: "what is a no-claim bonus"
Specific: no-claim bonus
Generic: (none)

Question: "what is a deductible"
Specific: deductible
Generic: (none)

Question: "choosing the best insurance policy in the uae for families"
Specific: uae
Generic: choosing, best, insurance, policy, families

Question: "how are premiums calculated for fire insurance"
Specific: fire insurance, premium
Generic: (none)

Question: "what should i know about maternity coverage for individuals vs families"
Specific: maternity
Generic: should, know, coverage, individuals, families

Question: {question}
"""


async def _extract_intent_topics(question: str) -> set[str]:
    """Fast LLM call (runs in parallel with retrieval) to extract core,
    discriminating topic words from the question for the coverage check.

    max_tokens=60 so the round-trip is <1 s on an idle backend.
    Falls back to an empty set on any error — caller uses regex fallback.
    """
    try:
        prompt = _INTENT_PROMPT.format(question=question)
        raw = await _backend_completion(prompt, max_tokens=60, timeout=15)
        if not raw:
            return set()

        specific_line = ""
        generic_line = ""
        for line in raw.split("\n"):
            line_l = line.strip().lower()
            if line_l.startswith("specific:"):
                specific_line = line.split(":", 1)[1] if ":" in line else ""
            elif line_l.startswith("generic:"):
                generic_line = line.split(":", 1)[1] if ":" in line else ""

        # Parse phrases like "no-claim bonus, deductible" keeping
        # multi-word/hyphenated compounds intact for phrase matching.
        topics: set[str] = set()
        for phrase in specific_line.lower().split(","):
            phrase = re.sub(r"[^a-z\- ]", "", phrase).strip()
            if phrase and phrase not in ("none", "n/a"):
                topics.add(phrase)

        # "Generic:" is still requested in the prompt — contrasting it
        # against "Specific:" helps the model reason about the split —
        # but its output is no longer persisted anywhere. An earlier
        # version fed it into a disk-backed learned-stopwords set
        # shared across queries, which caused two confirmed bugs: (1)
        # off-topic test/user queries taught it nonsense words with
        # nothing to do with insurance, and (2) each deployment
        # accumulates its own independent, un-synced state, so
        # identical code + identical KB behaved differently across
        # environments depending on each one's unrelated query
        # history. Kept for debug visibility only.
        generic_words: set[str] = set()
        for phrase in generic_line.lower().split(","):
            phrase = re.sub(r"[^a-z\- ]", "", phrase).strip()
            if phrase and phrase not in ("none", "n/a"):
                generic_words.update(w for w in phrase.split() if len(w) >= 3)

        logger.debug("[INTENT] %r → specific=%s generic=%s", question, topics, generic_words)
        return topics
    except Exception as exc:
        logger.debug("[INTENT] extraction failed (%s) — using regex fallback", exc)
        return set()


async def _reformulate_query_for_policy_type_classification(query: str) -> Optional[str]:
    """
    Same technique as _reformulate_scenario_query_for_retrieval further
    below (the reranker fix) — a real-world scenario question ("I'm
    flying my own small plane...") gets rewritten into a direct question
    using proper, SPECIFIC insurance terminology BEFORE it's classified,
    instead of classifying the raw colloquial phrasing.

    Applied one stage EARLIER than the reranker version: that one already
    knows the resolved policy_type/section and uses them to guide the
    rewrite ("rephrase this LIABILITY question about BENEFITS"); this one
    runs BEFORE policy_type is known — it's what the classification below
    itself runs on — so it can't be told the type, only instructed to
    name the real thing being asked about explicitly rather than
    paraphrasing it into something vaguer.

    Same motivating shape of bug as the reranker fix: a vague, colloquial
    phrasing ("...want to know about protection") shares loose incidental
    vocabulary with several unrelated type descriptions, while a specific,
    jargon-normalized rewrite ("insurance coverage for operating my own
    private aircraft") makes the actual real-world subject explicit,
    giving both the embedding ranker and the shortlist LLM below the same
    kind of clear signal the reranker fix already proved helps retrieval.

    Never used for the actual answer shown to the user, and never used
    for retrieval either — this is classification-only, upstream of both.
    Returns None (never the original query) on any failure or a clearly-
    unusable reply, same safety checks as the reranker version — the
    caller falls back to classifying the raw query, exactly as if this
    step didn't exist.
    """
    try:
        prompt = f"""The user's question below describes a real-world situation in plain,
everyday language. Rewrite it as a single direct question using proper insurance
terminology, naming the SPECIFIC real-world thing, activity, or asset involved
explicitly — don't paraphrase it into a vaguer or more generic term. Keep it
asking about the EXACT SAME underlying situation, don't add or invent new facts.

Do NOT name or invent a specific insurance PRODUCT, POLICY, or CATEGORY that
isn't already stated in the question — describe the concrete situation itself
(the object, activity, event, or loss involved) and let the reader work out
which category it belongs to. For example, if the question describes a food
truck owner worried a customer might get sick from their food, rewrite it as
asking whether a customer getting food poisoning from the truck is covered —
NOT as asking about "food truck liability insurance" or any other invented
product/category name. "insurance"/"policy"/"covered" alone is fine; a
specific category name is not, unless the original question already used one.

Question: "My neighbor's kid broke his arm playing in my backyard, could that end
up costing me money?"
Rewrite: Am I covered if a visitor is injured on my property?

Question: "My laptop got stolen out of my car last week, is there anything that
would have covered that?"
Rewrite: Does my policy cover theft of personal belongings from a vehicle?

The two examples above (backyard injury, stolen laptop) are ONLY illustrations
of the rewrite PATTERN — never reuse their wording, their scenario, or any
fact from them. Rewrite ONLY the real Question below, about its own actual
situation, whatever that situation is.

Question: {query!r}
Rewrite:"""
        raw = await _backend_completion(prompt, max_tokens=60, timeout=10)
        if not raw:
            return None
        rewritten = raw.strip().strip('"')
        if not rewritten or len(rewritten) > len(query) * 3 + 80:
            return None
        logger.info(
            "[QUERY_POLICY_TYPE] query reformulated for classification: %r -> %r",
            query, rewritten,
        )
        return rewritten
    except Exception as exc:
        logger.debug("[QUERY_POLICY_TYPE] classification reformulation failed (%s) — using original", exc)
        return None


# Dynamic per-type prototype embeddings backing _classify_query_policy_type_llm
# below — same architecture as _QUERY_SECTION_PROTOTYPES/_get_query_section_
# prototype_embeddings above, just built from get_active_vocab()'s own `desc`
# field instead of a hardcoded dict, since policy types aren't fixed (new
# ones get auto-promoted at runtime — see candidate_vocab.py). Cached and
# keyed off the vocab's own (label, desc) content, so a newly-promoted type
# or an edited description is picked up automatically on its very next call
# — no separate cache-invalidation hook needed anywhere else.
_policy_type_prototype_cache: Optional[tuple] = None


def _get_policy_type_prototype_embeddings():
    global _policy_type_prototype_cache
    vocab = get_active_vocab()
    signature = tuple(sorted((pt, info.get("desc", "")) for pt, info in vocab.items()))
    if _policy_type_prototype_cache is None or _policy_type_prototype_cache[0] != signature:
        _model = _get_shared_embed_model(EMBED_MODEL_NAME)
        _labels = [pt for pt, _ in signature]
        _descs = [desc for _, desc in signature]
        _vecs = _model.encode(_descs, normalize_embeddings=True)
        _policy_type_prototype_cache = (signature, _labels, _vecs)
    return _policy_type_prototype_cache[1], _policy_type_prototype_cache[2]


def _rank_policy_types_by_embedding(query: str) -> Optional[List[Tuple[str, float]]]:
    """Cosine-ranks every active policy type's own `desc` against the query,
    most-similar first. None only on a genuine failure (embed model
    unavailable, etc.) — an ordinary "nothing really fits" result still
    returns a normal ranked list, just with low scores throughout; turning
    that into "general" is the caller's job (see the floor/margin logic in
    _classify_query_policy_type_llm below), not this function's."""
    try:
        _labels, _vecs = _get_policy_type_prototype_embeddings()
        _model = _get_shared_embed_model(EMBED_MODEL_NAME)
        _qvec = _model.encode([query], normalize_embeddings=True)[0]
        _sims = np.dot(_vecs, _qvec)
        _order = np.argsort(-_sims)
        return [(_labels[i], float(_sims[i])) for i in _order]
    except Exception as exc:
        logger.debug("[QUERY_POLICY_TYPE] embedding ranking failed (%s)", exc)
        return None


# Same two-number shape as _QUERY_SECTION_EMBED_FLOOR/_MARGIN above and the
# same reasoning: an absolute score alone doesn't reliably separate "this
# really is the type" from "this is merely the least-bad option nothing
# else beat" — the MARGIN over the runner-up is what does that. Values are
# an initial calibration against this rewrite's own motivating failures
# (aviation/racehorse/drone, see the docstring below) — adjust from real
# logged (score, margin) pairs as more live queries accumulate, the same
# way the section-intent constants were originally set.
_POLICY_TYPE_EMBED_FLOOR = 0.40
_POLICY_TYPE_EMBED_MARGIN = 0.06


async def _classify_query_policy_type_llm(query: str) -> str:
    """Fallback for query policy_type, used only when the free regex pass
    (classify_query_policy_type) can't confidently name one.

    Most real queries don't name their type in the exact textbook phrase
    regex looks for — confirmed live: "what's not covered if my car is
    stolen" scores zero regex hits for every type (motor's list needs the
    full phrase "car insurance", not bare "car"; "stolen" isn't "theft")
    and falls through to "general," meaning the query gets no type signal
    at all despite obviously being about motor insurance to a human reader.

    Rewritten 2026-09-03 to rank by embedding similarity FIRST, asking an
    LLM only to break a genuine tie — not, as before, asking the LLM to
    freely pick 1 of ~30 types from scratch on every call. Root cause that
    forced this: with ~25-30 active types (12 hardcoded + auto-promoted
    ones, see get_active_vocab()), a flat one-shot classification over the
    whole list turned out to be beyond what the small model actually
    serving these calls (Qwen2.5-7B-Instruct-AWQ, local vLLM) can reliably
    do — confirmed by direct repeat-testing: the exact same query ("I'm
    flying my own small plane...") returned "motor" 5/5 times at
    temperature=0, every time, not occasionally — a reasoning-capacity
    ceiling, not sampling noise, so no amount of one-off worked examples in
    the old giant prompt could fix it without risking a regression
    elsewhere (confirmed: an earlier attempt to strengthen one case did
    exactly that to a different case). Routing the same call to a much
    larger model (Groq's 120B) was tried next and also rejected — not for
    accuracy, but because Groq's shared per-minute token quota (8000 TPM)
    was already exhausted by other traffic, so most calls got rate-limited
    (429) and silently fell back to the same weak local model anyway.

    Embedding similarity sidesteps the model-capacity problem entirely for
    the easy majority of cases — a clear best match, or clearly nothing
    plausible (-> general) — both fully deterministic, no LLM involved.

    For the genuinely ambiguous remainder (top types scoring close
    together), an earlier version of this narrowed the field down to a
    small shortlist (the top few close-scoring types) before asking the
    LLM to pick between just those. That was DROPPED (2026-09-03) after
    isolating it as the actual cause of a specific failure, not a fix for
    one: given only a shortlist of "the closest matches", the model kept
    picking the least-bad one of them even when NONE of them genuinely
    fit (confirmed: "I'm flying my own small plane..." against a
    narrowed shortlist [drone_insurance, motor, liability, ...] picked
    liability or motor depending on run; the SAME query against the FULL
    type list, same prompt otherwise, correctly said "general" 3/3).
    Seeing the full list — most of which is obviously irrelevant — gives
    the model the contrast it needs to recognize "even the closest
    option here doesn't really fit"; a pre-filtered shortlist removes
    that contrast and quietly pressures it toward picking something.
    So the tie-break call below always sees every active type, never a
    narrowed subset — embedding still does the real work of skipping the
    LLM entirely for confident/clearly-absent cases, it just no longer
    also decides which types the LLM is allowed to consider.

    Also reformulates the query into proper insurance terminology BEFORE
    ranking/classifying it (_reformulate_query_for_policy_type_
    classification above) — same technique already proven for the
    reranker (_reformulate_scenario_query_for_retrieval below): a vague,
    colloquial phrasing shares loose incidental vocabulary with several
    unrelated type descriptions, while naming the real thing explicitly
    gives the embedding ranker a clearer signal to work with. Falls back
    to the raw query on any reformulation failure, same as every other
    best-effort step in this file.

    Falls back to "general" (no filtering) on any failure, exactly like
    the regex path already does.
    """
    _reformulated = await _reformulate_query_for_policy_type_classification(query)
    _classify_query = _reformulated or query
    _ranked = _rank_policy_types_by_embedding(_classify_query)
    if not _ranked:
        return "general"
    _top_label, _top_score = _ranked[0]
    _runner_score = _ranked[1][1] if len(_ranked) > 1 else -1.0
    _margin = _top_score - _runner_score
    if _top_score < _POLICY_TYPE_EMBED_FLOOR:
        logger.debug(
            "[QUERY_POLICY_TYPE] embedding: no plausible match (top=%r score=%.3f) -> general",
            _top_label, _top_score,
        )
        return "general"
    if _margin >= _POLICY_TYPE_EMBED_MARGIN:
        logger.debug(
            "[QUERY_POLICY_TYPE] embedding confident: %r score=%.3f margin=%.3f",
            _top_label, _top_score, _margin,
        )
        return _top_label
    logger.debug(
        "[QUERY_POLICY_TYPE] embedding ambiguous (top=%r score=%.3f margin=%.3f) -> full-list LLM tie-break",
        _top_label, _top_score, _margin,
    )
    _llm_label = await _classify_query_policy_type_tiebreak_llm(_classify_query)
    # Falls back to "general", NOT _top_label (2026-09-03, explicit user
    # direction) — landing in this branch already means the embedding
    # score alone wasn't confident enough to trust on its own (that's WHY
    # the tie-break ran), so on top of that, an unconfident or failed
    # tie-break call is two weak signals stacked, not one — not a good
    # enough basis to force a specific type and hard-filter retrieval by
    # it. Confirmed live as the actual failure mode worth guarding
    # against: "I'm worried my ex might try to commit fraud using my
    # identity" resolved to "cyber" with no confidence gate at all,
    # which then hard-filtered retrieval down to cyber-tagged chunks —
    # an honest "general" (no filtering) is the safer default here.
    return _llm_label if _llm_label else "general"


async def _classify_query_policy_type_tiebreak_llm(query: str) -> Optional[str]:
    """Tie-break for when embedding similarity is ambiguous (see the
    docstring on _classify_query_policy_type_llm above for why this sees
    every active type rather than a narrowed shortlist — a narrowed list
    was tried and confirmed to bias the model toward over-picking).

    Also asks the model to self-rate its confidence and only accepts the
    label on "high" — since embedding was already ambiguous going in,
    this is the last chance to catch a low-confidence guess before it
    becomes a hard retrieval filter. Returns None on low/medium
    confidence, an invalid label, or any failure — the caller treats
    every one of those the same way: fall back to "general", not the
    guess.
    """
    try:
        vocab = get_active_vocab()
        label_list = "\n".join(f"  - {pt}: {info['desc']}" for pt, info in vocab.items())
        prompt = f"""Classify the ONE insurance policy type this question is about, using the
descriptions below to judge which one actually fits. Reply "general" if the question
genuinely doesn't match any of them, even if one looks like the closest available option.

{label_list}
  - general: none of the types above genuinely fits this question

Reply in EXACTLY this two-line format, nothing else — no explanation, no
"QUESTION"/"Reply" echoed back:
label: <the exact label word>
confidence: <high, medium, or low — how sure you actually are, not just
which option looks least-bad>

QUESTION: {query}"""
        raw = await _backend_completion(prompt, max_tokens=20, timeout=15)
        if not raw:
            return None
        _label_m = re.search(r"label\s*:\s*([a-z_]+)", raw.lower())
        _conf_m = re.search(r"confidence\s*:\s*(high|medium|low)", raw.lower())
        if not _label_m or not _conf_m or _conf_m.group(1) != "high":
            logger.info(
                "[QUERY_POLICY_TYPE] tie-break LLM not confident enough: query=%r raw=%r -> general",
                query[:80], raw[:80],
            )
            return None
        label = _normalize_policy_type(_label_m.group(1))
        result = label if label in _valid_policy_types() else None
        logger.info(
            "[QUERY_POLICY_TYPE] full-list tie-break LLM (high confidence): query=%r -> %s",
            query[:80], result,
        )
        return result
    except Exception as exc:
        logger.debug("[QUERY_POLICY_TYPE] tie-break LLM failed (%s)", exc)
        return None


async def _classify_query_policy_types_multi_llm(query: str) -> list[str]:
    """Multi-label sibling of _classify_query_policy_type_llm() — used
    ONLY at the primary retrieval-filter call site, when regex named a
    type on the weakest evidence it trusts (a single hit). NOT a
    replacement for _classify_query_policy_type_llm() itself — that
    function's own "regex says general" fallback path is unchanged and
    untouched; this is an additive, separate consultation for a different
    failure mode.

    A single query can genuinely span two insurance types where only one
    is named/matched by a regex phrase — forcing a single label onto that
    hard-excludes the OTHER type's chunks from the retrieval filter
    entirely, no matter how relevant they are. Confirmed live: "I am going
    to travel to europe so should i take the health insurance" classified
    single-label as "health" (regex: exactly one hit, no tie) — the
    resulting filter never let travel_insurance_guide.pdf's chunks reach
    the reranker at all, even though that document scored 0.9981 against
    this exact question with NO filter applied — the single highest
    rerank score in the entire KB — versus 0.9197 for the best chunk the
    health-only filter allowed through. The model then filled the
    Europe/Schengen gap from its own training data instead of the real
    retrieved answer.

    Validated against the same queries the existing single-label
    classifier already gets right, confirming this doesn't widen
    spuriously: a genuinely single-topic query (e.g. "what is not covered
    if my car is stolen") still returns exactly one label; a query that
    only NAMES one type but substantively concerns a second (the Europe/
    health case above) returns both. Returns [] on any failure or empty
    result — the caller must treat that as "no additional signal," never
    as license to drop the primary type it already has.
    """
    try:
        label_list = "\n".join(f"  - {pt}: {info['desc']}" for pt, info in get_active_vocab().items())
        prompt = f"""Which insurance policy types does this question involve? Usually exactly ONE.
Only name a SECOND type if the question genuinely involves both (e.g. it asks about one
type of cover in the context of a situation another type specifically covers).

Available types:
{label_list}

QUESTION: {query}

Reply with the label word(s), comma-separated, nothing else."""
        raw = await _backend_completion(prompt, max_tokens=15, timeout=10)
        if not raw:
            return []
        parts = [p.strip() for p in raw.strip().lower().split(",") if p.strip()]
        labels: list[str] = []
        for p in parts:
            label = _normalize_policy_type(re.split(r"[\s\n.:;()]", p)[0])
            if label in _valid_policy_types() and label not in labels:
                labels.append(label)
            if len(labels) == 2:
                break
        logger.debug("[QUERY_POLICY_TYPE] multi-label LLM: %r -> %s", query, labels)
        return labels
    except Exception as exc:
        logger.debug("[QUERY_POLICY_TYPE] multi-label LLM failed (%s) — no additional signal", exc)
        return []


async def _reformulate_scenario_query_for_retrieval(
    query: str, policy_type: Union[str, List[str]], section: str,
) -> Optional[str]:
    """
    Rewrites a real-world SCENARIO question ("my neighbor's kid broke his
    arm in my backyard, could that cost me money") into a direct question
    using proper insurance terminology ("am I covered under public
    liability insurance if a visitor is injured on my property") — for
    RETRIEVAL/RERANKING purposes only. Never used for the actual answer
    shown to the user; the generation prompt still sees the user's
    original, natural question.

    Root cause this exists to fix, confirmed live 2026-09-01: the cross-
    encoder reranker (a lightweight model leaning heavily on literal
    vocabulary overlap, not deep semantic reasoning) scores a scenario-
    phrased query against the exact correct chunk as pure noise —
    0.0000, actually LOSING to a genuinely irrelevant chunk that
    happened to share a few more incidental words. The SAME chunk
    against a jargon-phrased version of the identical underlying
    question scored 0.2320 — a real, clearly-correct signal, thousands
    of times higher. Swapping to a larger reranker model (bge-reranker-
    v2-m3) was tested and did NOT fix this — it showed the same
    near-zero, non-discriminating scores on the scenario phrasing, while
    also being markedly slower on CPU. The gap is specifically about
    HOW the question is phrased, not the model's general capability
    against this content, so fixing the phrasing (rather than the model
    or the scoring gate) is the actual fix.

    Told the ALREADY-resolved policy_type and section explicitly (both
    confidently known by the time this is called — see
    _metadata_scoped_retrieval's caller) so this is a narrow, guided
    rewrite task rather than a cold, open-ended one: "rephrase this
    LIABILITY question about BENEFITS using proper terms" is a much
    easier, more reliable job for an LLM than "figure out what this is
    about AND rephrase it" would be — that harder combined task is
    already handled by the classifiers that ran before this.

    Returns None (never the original query) on any failure or a
    clearly-unusable reply (empty, or suspiciously long — a real
    rewrite of a short scenario question should stay a similar length,
    not turn into a paragraph) — the caller falls back to the original
    query text exactly like every other LLM-assisted step in this file.
    """
    try:
        _type_label = (
            " / ".join(policy_type) if isinstance(policy_type, (list, tuple, set)) else policy_type
        )
        # section is optional (2026-09-01) — when the caller only has a
        # confident policy_type and no section (see _metadata_scoped_
        # retrieval's own docstring), the "(specifically about X)" aside
        # is simply omitted rather than printing a literal "None".
        _section_aside = f" (specifically about {section})" if section else ""
        prompt = f"""The user's question below describes a real-world situation in plain,
everyday language, for a chatbot answering questions about {_type_label} insurance{_section_aside}.
Rewrite it as a single direct question using proper insurance terminology, so it can be
matched against formal policy-document language —
but keep it asking about the EXACT SAME underlying situation, don't add or invent
new facts.

Question: "My neighbor's kid broke his arm playing in my backyard, could that end
up costing me money?"
Rewrite: Am I covered under public liability insurance if a visitor is injured on
my property?

Question: "My laptop got stolen out of my car last week, is there anything that
would have covered that?"
Rewrite: Does my policy cover theft of personal belongings from a vehicle?

The two examples above (backyard injury, stolen laptop) are ONLY illustrations
of the rewrite PATTERN — never reuse their wording, their scenario, or any
fact from them. Rewrite ONLY the real Question below, about its own actual
situation, whatever that situation is.

Question: {query!r}
Rewrite:"""
        raw = await _backend_completion(prompt, max_tokens=60, timeout=10)
        if not raw:
            return None
        rewritten = raw.strip().strip('"')
        if not rewritten or len(rewritten) > len(query) * 3 + 80:
            return None
        logger.info(
            "[ask_stream] scenario query reformulated for retrieval: %r -> %r",
            query, rewritten,
        )
        return rewritten
    except Exception as exc:
        logger.debug("[ask_stream] scenario query reformulation failed (%s) — using original", exc)
        return None


async def _classify_query_candidate_type_llm(query: str) -> Optional[str]:
    """
    Open-vocabulary sibling of _classify_query_policy_type_llm() — no list
    constraint, can name anything, even a label the candidate vocabulary has
    never seen before. Never touches retrieval filtering; its only purpose
    is comparison against a chunk's candidate_policy_type during reranking
    (see _effective_sort_score in ask_stream). Callers only invoke this
    when the retrieved pool actually contains a chunk with
    candidate_policy_type set — the common case has nothing to compare
    against, so this call would otherwise be pure wasted latency on every
    single query.
    """
    from candidate_vocab import match_candidate_vocab, normalize_candidate_label, upsert_candidate

    hit = match_candidate_vocab(query)
    if hit:
        upsert_candidate(hit, [], query, "query")
        return hit

    # Backend failure (timeout, connection error, empty completion) is
    # deliberately allowed to propagate here rather than being swallowed
    # into a `return None` — the caller (ask_stream) uses None from THIS
    # function as "confirmed general, no specific candidate topic," which
    # licenses _candidate_mismatch to drop every candidate-tagged chunk
    # that disagrees. A classification that never actually ran (backend
    # down/busy) is not evidence the query is general — it's no evidence
    # at all. Confirmed live: under concurrent load this call failed
    # outright for "Is loss of milk yield covered under livestock
    # insurance?", and the resulting None silently dropped the correctly
    # candidate-tagged livestock chunk that contained the answer, even
    # though the query literally names "livestock insurance."
    prompt = f"""This is a short insurance-related question. If it names or clearly
implies ONE specific insurance product or coverage type — even an unusual
or unfamiliar-sounding one — extract that name in 1-3 words. If the
question itself already uses a specific term for the coverage (even a term
you don't recognize as a standard insurance category), use that exact term
rather than judging whether it "sounds like" a real product.

- If yes, reply with ONLY that name, lowercase, 1-3 words, nothing else.
- If the question is generic, spans multiple types, or doesn't name or
  imply one specific product at all, reply with exactly: general

QUESTION: {query}

ANSWER:"""
    # Classification-only route (get_classification_llm — prefers Groq,
    # see router.py), not _backend_completion's shared vLLM-by-default
    # path. Confirmed live 2026-08-10: for the exact query above, vLLM
    # answered "general" despite the prompt's own explicit instruction to
    # use the query's stated term — a genuine instruction-following miss,
    # not a backend failure (raw='general', a real, well-formed reply).
    # The same query via get_classification_llm() correctly answered
    # "livestock insurance". This is the same fix already applied to the
    # ingestion-side classification calls in api.py/metadata_tagger.py
    # this session, for the identical reason: a short, single-label
    # extraction judgment, not full answer generation — the class of task
    # Groq has been shown to help with here, distinct from the generation
    # role it was tried and reverted for three times (see .env's own
    # history on that).
    try:
        _completion = await get_classification_llm(temperature=0, max_tokens=10).ainvoke(prompt)
        raw = _completion.content if hasattr(_completion, "content") else str(_completion)
    except Exception as exc:
        raise RuntimeError(f"query candidate-type classification call failed: {exc}") from exc
    if not raw:
        raise RuntimeError("empty completion from backend for query candidate-type classification")

    label = normalize_candidate_label(raw)
    if label is None:
        return None
    # Same dedup guard as classify_candidate_type() (metadata_tagger.py) —
    # this open-ended LLM has zero knowledge of the 12 hardcoded type
    # names, so it can rename an EXISTING type under different phrasing
    # ("term insurance" for a query the closed classifier already
    # correctly resolved to "life") and pollute the promotion pipeline
    # with a fake "new type" that's really just evidence of nothing new.
    # Confirmed live 2026-07-23: "term_insurance" logged 4x from a query
    # that classify_query_policy_type() already correctly tags "life"
    # (life's own regex list literally contains \bterm insurance\b) —
    # this function runs independently of that result whenever the
    # retrieved pool has a chunk carrying a candidate_policy_type to
    # compare against, so a query resolving correctly elsewhere doesn't
    # stop this path from mislogging it as a new candidate.
    if _is_duplicate_of_existing_type(label, get_active_vocab().keys()):
        logger.info(
            "[CANDIDATE_TYPE] query-side closed-classifier miss suspected: "
            "open-ended guess %r duplicates an existing type (query=%r) — "
            "not logging as a new candidate",
            label, query[:60],
        )
        return None
    upsert_candidate(label, [], query, "query")
    logger.debug("[CANDIDATE_TYPE] query open-ended guess: %r -> %r", query, label)
    return label


# Context passed to the grounding-check prompt is capped so this stays a
# fast, cheap call (max_tokens=10 output either way) — not specified by the
# original design, but consistent with the context[:1000] pattern elsewhere
# in this file bounding auxiliary-call input size for latency.
#
# Doubled 3000 -> 6000 alongside _build_grounding_context's window-joining
# fix (see that function's docstring/comment) — that fix doubled how much
# text each chunk contributes (both _rerank_windows candidates instead of
# arbitrarily just one), which at the OLD 3000 cap roughly halved how many
# of the already-best-first-sorted chunks actually fit before truncation,
# silently losing lower-ranked-but-still-relevant chunks that used to be
# visible. Confirmed live: "What is the maximum compensation for legal
# expenses under travel insurance?" needs a phrase from the chunk ranked
# #3 (the word "legal", establishing which of two adjacent, identically-
# shaped clauses a figure in chunk #1 belongs to) — at the old cap that
# phrase sat at char ~3849, past the truncation point, even though it was
# genuinely present in the retrieved pool. Doubling the cap alongside the
# per-chunk content restores roughly the same number of visible chunks as
# before the window-joining fix, so this isn't a net increase in how much
# "extra" content the model sees per chunk actually retrieved — only a
# correction to keep the same chunk-count budget intact.
_GROUNDING_CONTEXT_CHARS = 6000


def _build_grounding_context(query: str, chunks: list) -> str:
    """Join *chunks* into a single preview string for _verify_grounding(),
    using each chunk's most query-relevant excerpt (via _rerank_windows,
    already computed cheaply during reranking with no extra model call)
    instead of its raw, full page_content.

    Confirmed live: with several full multi-hundred-word chunks joined and
    then hard-capped at _GROUNDING_CONTEXT_CHARS, a genuinely answering
    sentence sitting past the opening of a long chunk gets buried among
    unrelated boilerplate (exam questions, generic definitions, other
    chunks) ahead of it in the same budget — "How are relatives typically
    notified about the contents of a policy document?" against a context
    that DID contain "...kept in safe custody and in the knowledge of the
    close relatives" still got NO from the grounding check, but the exact
    same sentence, isolated from the surrounding noise, reliably got YES.
    Using each chunk's best-matching window keeps the signal-to-noise ratio
    high regardless of where in a long chunk the relevant sentence sits —
    the same fix already proven for the reranker's own scoring step.
    """
    parts = []
    for c in chunks:
        text = getattr(c, "page_content", "") or ""
        if not text:
            continue
        windows = _rerank_windows(text, query)
        # Used to take ONLY windows[1] (the keyword-weighted window),
        # discarding windows[0] (the plain start-of-chunk slice) whenever
        # both existed. That's an arbitrary fixed-index choice, not "pick
        # whichever window actually scored higher" — _rerank_windows'
        # caller (the real reranking pass) takes the MAX score across
        # windows, but that per-window score isn't threaded through to
        # here, so this function had no way to know which one actually
        # mattered. Confirmed live: "What is the maximum compensation for
        # legal expenses under travel insurance?" against a chunk whose
        # relevant sentence ("...the maximum amount of compensation is
        # €8,500...") sits right at the start (windows[0]) — the
        # keyword-weighted windows[1] drifted past it to an adjacent,
        # differently-scoped clause ("...liability...€170,000...") that
        # scores similarly on keyword density but doesn't answer the
        # question at all. Dropping windows[0] unconditionally threw away
        # the one window that actually had the answer, and the reranker's
        # own 0.976 score (which DOES account for windows[0]) never gets a
        # chance to inform this check. Joining both windows instead of
        # picking one fixes this without needing to plumb the winning
        # window's score through from reranking — bounded to ~1400 chars
        # per chunk (2 windows of length _RERANK_TEXT_CHARS=700), and since
        # chunks arrive sorted best-first (this function's caller already
        # requires that), the top chunk's full ~1400 chars land within the
        # first slice of _GROUNDING_CONTEXT_CHARS=3000 regardless of what
        # lower-ranked chunks contribute afterward. This is a different
        # tradeoff than the ORIGINAL single-full-chunk-per-entry approach
        # this function replaced (see docstring above) — that discarded
        # windowing entirely and diluted signal with multiple full,
        # uncapped chunks; two short curated windows per chunk doesn't
        # reintroduce that problem.
        parts.append("\n".join(windows))
    return "\n\n".join(parts)


async def _verify_grounding(question: str, context: str, backend_override: Optional[str] = None) -> bool:
    """LLM-based semantic grounding backstop — an authoritative layer on top
    of the lexical/regex coverage checks (_context_covers_query,
    _enumeration_query_covered, _quoted_comparison_covered), not a
    replacement for them.

    Those lexical checks are pattern-matching heuristics: every new
    phrasing that slips past them needs a new regex rule. This closes that
    gap by directly asking the model whether the SPECIFIC question is
    answerable from the SPECIFIC retrieved context — which catches the
    failure mode the lexical checks structurally can't: a chunk that's
    topically adjacent but not actually about the thing asked (e.g. a
    Takaful-insurance-model chunk confidently used to answer "which
    insurers cover travel to South Africa" — same broad category
    (insurance), wrong specific topic, no lexical rule can enumerate every
    such near-miss in advance).

    backend_override: see _backend_completion — used by the query-cleaning
    fallback path to re-check grounding on vLLM specifically, so that path
    stays independent of Groq's daily quota (the whole reason it exists).

    Fail-safe: any exception, timeout, or ambiguous/empty response returns
    False (not grounded) — matches the fail-safe direction already used
    elsewhere in this file for needs_human (when in doubt, refuse rather
    than risk answering ungrounded).
    """
    if not context or not context.strip():
        return False
    # Framed as "is there relevant info here" rather than "can this EXACT
    # question be answered" — the earlier "exact question" framing made the
    # 7B model demand something close to a literal restatement of the
    # question in the context. That broke down specifically on totality/
    # completeness questions ("are all types of illness covered?") against
    # a long, multi-topic joined context: an exclusions list is exactly the
    # right way to answer such a question (implies "no, not everything —
    # here are the exceptions"), but the model wouldn't credit it without
    # an explicit "not all are covered" sentence to point to. Confirmed via
    # a 3x-repeated, 4-case comparison (this exact case + 3 known-good
    # regression cases) that the "exact question" framing failed the
    # exclusions case 100% of the time regardless of added exclusion-list
    # guidance, while this framing passes it and still correctly returns NO
    # on genuinely wrong-topic context (Takaful/South-Africa mismatch case).
    prompt = (
        f"Context:\n{context[:_GROUNDING_CONTEXT_CHARS]}\n\n"
        f"Question: {question}\n\n"
        "Does this context contain information directly relevant to "
        "answering this question — enough that someone could give a real, "
        "specific answer (not necessarily complete or exhaustive)? Answer "
        "NO if: the context is about a different, unrelated topic; the "
        "question asks for a specific fact (a country, provider, number) "
        "that is simply absent; OR the question describes a specific "
        "triggering event or scenario (e.g. a policy reaching its natural "
        "end date without any claim made) and the context only discusses a "
        "DIFFERENT triggering event in the same general area (e.g. "
        "cancelling a policy early, or returning it during an initial "
        "review window) — sharing a general subject like \"refunds\" is not "
        "the same as the context actually addressing the specific event "
        "asked about. This does not apply to a list that implies its own "
        "completeness (e.g. an exclusions list correctly implies everything "
        "not listed IS covered) — that is still a real answer, not a "
        "different scenario. "
        "Answer with a single word: YES or NO."
    )
    try:
        raw = await _backend_completion(prompt, max_tokens=10, timeout=10.0, backend_override=backend_override)
        if not raw:
            return False
        cleaned = re.sub(r"[^a-z\s]", "", raw.strip().lower())
        words = set(cleaned.split())
        return "yes" in words and "no" not in words
    except Exception:
        return False


async def _verify_point_faithfulness(point: str, context: str) -> bool:
    """Post-GENERATION entailment check — does ONE numbered point of a
    finished answer actually hold up against the retrieved evidence?

    This is a different question from _verify_grounding above, which runs
    BEFORE generation and asks "is the QUESTION answerable from this
    context" — a go/no-go gate that, once passed, never looks at what
    actually gets written. A model can pass that gate (the context IS
    genuinely relevant) and still write an answer that goes beyond what
    the context supports — confirmed live: asked whether one policy could
    cover both a flooded house and a storm-damaged car, _verify_grounding
    correctly said the retrieved motor-comprehensive content was relevant
    enough to attempt an answer, and the model then combined "comprehensive
    cover includes flood/storm" (true, for the vehicle) with the user's own
    mention of "house" into a bundling claim neither source ever makes.
    Two direct prompt-instruction attempts to stop this failed identically
    on live re-test (see prompt_template.py's own "STOP. Before writing..."
    addition, kept for the cases it DOES catch).

    Directly reimplements the evidence/hypothesis/entailment framing NeMo
    Guardrails' `self_check_facts` action uses. The framework itself added
    nothing beyond that prompt — no Colang flow, no new dependency, just a
    short call to the SAME backend already used everywhere else in this
    file, kept here rather than adding nemoguardrails as a dependency. The
    prompt below is close to NeMo's own default wording DELIBERATELY, not
    a paraphrase — an earlier, more elaborate version of this prompt
    (explaining the task as a question, with extra caveats about combining
    separately-true facts) measurably under-performed it: same real
    retrieved context and same real answer text both times, the elaborate
    version caught a real target fabrication only 1 time in 6 live
    attempts; installing the actual NVIDIA library in an isolated
    environment and testing it directly against the SAME real (truncated)
    context caught the SAME fabrication 4/4 once re-tested with THIS
    terser prompt. A short, cloze-style completion ("...\"entails\":")
    apparently gives this size of model a cleaner signal to complete than
    a longer question-plus-caveats framing — the same lesson this session
    already learned elsewhere (e.g. the policy-type classifier needing a
    short worked example over an abstract rule).

    This function checks ONE point, not a whole answer — an earlier
    version checked the whole answer in one shot and was dropped entirely
    after two separate confirmed failure modes: (1) checking the exact
    same real context and real 6-point answer both as a numbered list AND
    as rewritten flowing prose, it said "faithful" 3/3 times either way —
    a single yes/no over a MIX of mostly-plausible points and one
    fabricated one gets dominated by the plausible majority, reformatting
    alone doesn't fix that; checking each of the 6 points individually
    against that SAME context instead correctly caught 4 of the 6
    unsupported points, including the one whole-answer checking missed
    every time. (2) The same whole-answer approach, even on plain,
    single-source, pre-SRG prose with no composite sentence at all, also
    false-positived on a genuinely correct, repeatedly-verified motor-claim
    answer and replaced it with a refusal shown to a real user — multi-
    claim prose folded into one paragraph hits the same whole-block
    unreliability, just in the opposite direction (one point the model is
    slightly unsure about can sink an otherwise-fine answer). Only
    checking one self-contained claim at a time has actually proven
    reliable — prose answers now get this SAME check, one SENTENCE at a
    time (see the prose branch of the caller in ask_stream), reusing this
    exact function.

    One retry on an empty response — confirmed live this call can hit a
    transient network failure against the remote backend (same class of
    intermittent outage already documented elsewhere in this file), and
    the fail-open default would otherwise silently treat a dropped
    connection as "yes, entailed" for the one point that most needed
    checking.

    The prompt explicitly says a PARTIAL claim still counts as entailed.
    Confirmed live (2026-08-27), reproduced with the EXACT live context
    and point text captured from a real request (not a reconstruction —
    an earlier attempt to reproduce this via a fresh, separately-fetched
    context gave a different, misleading result, since retrieval isn't
    perfectly deterministic run to run): the source literally says "1.
    Ensure everyone's safety first, and if the accident involves injury...
    inform the police..." — combining two actions into ONE numbered
    source point. The generated answer split this into two separate
    sentences (as it should — they're two distinct actions). Without this
    line, the model consistently said "No" to the safety-only half, 5/5
    times against the identical real context — apparently penalizing a
    hypothesis for being a SUBSET of a longer evidence sentence rather
    than crediting it as still true. Adding this one line fixed it 5/5,
    without weakening the check's ability to catch a real fabrication
    (re-verified against the known target case afterward). A second
    attempted fix — requiring two independent "No" verdicts to agree
    before dropping anything — was tried FIRST and reverted: it didn't
    address this failure mode at all (both calls agreed "No" consistently,
    since the underlying misjudgment was systematic, not noisy), and a
    boolean-logic bug in that version's own final line briefly also
    broke the fabrication catch outright — caught and fixed before this
    version shipped.

    A "No" verdict requires TWO independent calls to agree before this
    function actually returns False. Confirmed live (2026-08-27): a
    genuinely grounded sentence ("ensure everyone's safety", matching the
    source's own "make sure everyone is safe" — confirmed present in the
    exact evidence used) was flagged False on one live call, then passed
    True on 5/5 immediate retests against the identical context — not a
    real ungrounded claim, a one-off noisy response (the remote backend
    logged a connection failure in the same window). A single "No" isn't
    trustworthy enough on its own to discard content that already passed
    every earlier check in the pipeline; requiring a second, independent
    "No" before dropping trades a little extra latency (only for the
    minority of points that fail once) for a much lower risk of throwing
    away genuinely correct content.
    """
    if not point or not point.strip() or not context or not context.strip():
        return True
    prompt = (
        "You are given a task to identify if the hypothesis is grounded "
        "and entailed to the evidence.\n"
        "You will only use the contents of the evidence and not rely on "
        "external knowledge.\n"
        "The hypothesis may state only PART of a longer evidence sentence "
        "— that still counts as entailed.\n"
        "The hypothesis may use plainer, more general wording than the "
        "evidence's own — that alone is not a reason to say no; judge "
        "whether the evidence supports its MEANING, not whether it repeats "
        "the evidence's exact words.\n"
        "A hypothesis stating that two named things are SEPARATE, not "
        "combined, or not covered by the same product also counts as "
        "entailed when the evidence discusses one of them without ever "
        "stating they are combined — the evidence does not need to "
        "explicitly say \"these are separate\" for that to be true.\n"
        "Some evidence passages start with a bracketed label such as "
        "\"[Policy Type: Marine Insurance]\" naming the policy type that "
        "passage is actually about. If the hypothesis claims something is "
        "a coverage type, branch, or product OF one specific policy type "
        "(e.g. \"X is a type of marine insurance\"), and the only passage "
        "naming X carries a label for a DIFFERENT policy type, answer no — "
        "that passage merely mentions X in passing, it is not evidence X "
        "belongs to the claimed type. Ignore the label entirely for a "
        "hypothesis that does not itself claim a specific policy type.\n"
        f'Answer with yes/no. "evidence": {context[:_ENTAILMENT_CONTEXT_CHARS]} '
        f'"hypothesis": {point[:800]} "entails":'
    )

    async def _single_check(backend: str) -> Optional[bool]:
        try:
            raw = await _backend_completion(
                prompt, max_tokens=10, timeout=15.0, backend_override=backend,
            )
            if not raw:
                return None
            cleaned = re.sub(r"[^a-z\s]", "", raw.strip().lower())
            words = set(cleaned.split())
            if "no" in words and "yes" not in words:
                return False
            return True
        except Exception:
            return None

    # Hybrid, user-directed 2026-08-27: each backend showed a DIFFERENT
    # reliability profile on this exact task, tested head-to-head against
    # the same real live cases both ways. vLLM catches real fabrications
    # more consistently (correctly flagged the target case in roughly
    # half to two-thirds of fresh live runs) but had shown a false
    # positive on genuinely correct content before the partial-claim
    # prompt fix. Groq never reproduced that false positive (5/5 clean)
    # and returns a cleaner, easier-to-parse "yes"/"no" — but its catch
    # rate on the SAME target fabrication dropped to roughly 1 in 8 fresh
    # live runs, a reasoning model apparently finding a generous, loosely
    # plausible connection more often than vLLM's more literal read.
    # Neither one alone is clearly better — this uses each one's own
    # strength: vLLM does the FIRST-PASS detection (it catches more), and
    # a point only actually gets dropped if Groq INDEPENDENTLY agrees on
    # a second call (it doesn't over-flag) — vLLM's flag alone is not
    # enough. Groq is called only for the minority of points vLLM
    # flags, keeping the common case (vLLM says yes) to one call.
    _vllm_verdict = await _single_check("vllm")
    if _vllm_verdict is None:
        _vllm_verdict = await _single_check("vllm")
    if _vllm_verdict is not False:
        return True  # None (still failed after retry) or True -> fail open / pass

    # vLLM flagged it — confirm with Groq before actually dropping
    # content. An explicit Groq "Yes" fails open (True, keep) — Groq
    # independently disagreeing with vLLM's flag is a real signal, same
    # direction as every other ambiguous case here.
    _groq_verdict = await _single_check("groq")
    if _groq_verdict is None:
        _groq_verdict = await _single_check("groq")
    if _groq_verdict is None:
        # Confirmation genuinely UNREACHABLE both attempts (not "Groq
        # looked and said yes" — the call itself failed, e.g. rate-
        # limited or down) — trust vLLM's own flag rather than silently
        # treating an unreachable confirmation step as if it had cleared
        # the content. Confirmed live (2026-08-27): Groq hit its own
        # daily token quota mid-session (a 429 with "Used 199717/200000"
        # visible in the logs), and the OLD "None -> keep" behavior let a
        # genuinely invented figure ("the deductible is exactly Rs.
        # 25,000", nothing like it anywhere in the evidence) pass
        # straight through untouched the moment Groq stopped answering —
        # silently defeating the whole hybrid mechanism for as long as
        # the outage/rate-limit lasted, right when the safety net matters
        # most. vLLM's own "No" is a real signal on its own (see this
        # function's whole earlier history before Groq was added) — it
        # shouldn't count for nothing just because the confirmation step
        # couldn't be reached.
        return False
    return _groq_verdict is not False


_PGF_CLAIMS_PROMPT = (
    'Based on the given text, extract a list of separate FACTUAL claims made in it. '
    'Split any sentence that bundles more than one distinct fact into separate claims, '
    'so each claim can be checked independently. Each claim must be a coherent, '
    'standalone statement, not cherry-picked out of context. '
    'Preserve the actual instruction or fact from the text in each claim — do NOT '
    'reduce a claim to a vague, circular restatement of the category it belongs to.\n'
    'Example: "Gather your documents, like the policy and the ID card." splits into '
    '["Gather the policy.", "Gather the ID card."] — NOT into '
    '["There are documents to gather.", "The policy is a document.", '
    '"The ID card is a document."], which throws away the actual instruction.\n'
    'Return ONLY JSON in this exact format, no explanation: {{"claims": ["...", ...]}}\n\n'
    'Text:\n{text}\n\nJSON:'
)


def _looks_like_runon_enumeration(text: str) -> bool:
    """Cheap regex pre-filter: does *text* contain a sentence chaining 3+
    comma-separated segments together with a trailing "and"/"or" — the
    "list crammed into one run-on sentence" shape confirmed live 2026-09-07
    (repeatedly, on identical retries of the same question): a prompt rule
    telling the model to switch to a numbered list when the CONTEXT
    genuinely supports 2+ separate items did NOT reliably change its
    behavior — 2/2 test runs still produced e.g. "This plan covers
    emergency medical treatment and hospitalization, trip cancellation or
    curtailment due to a covered reason like your own serious illness,
    loss, theft, or delay of checked baggage, and emergency medical
    evacuation or repatriation to your home country." — a small local
    model reliably following a CONDITIONAL formatting judgment made
    together with primary generation is a harder ask than the same model
    just restructuring already-written text afterward (the same "verify
    and repair after the fact" shape that already works well for SRG/PGF
    elsewhere in this file). This is only the CHEAP gate deciding whether
    that repair call below is worth attempting — never used to decide the
    actual restructuring, since reliably SPLITTING a comma-chained
    sentence into the right items needs real language understanding, not
    regex (a nested list-within-an-item like "loss, theft, or delay of
    checked baggage" would naively over-split into 3 fake items instead
    of the 1 real one a human reads it as).
    """
    for sentence in re.split(r'(?<=[.!?])\s+', text):
        if sentence.count(',') >= 3 and re.search(r',\s*(?:and|or)\s+\S', sentence):
            return True
    return False


async def _restructure_runon_as_list(answer: str) -> Optional[str]:
    """Rewrites a comma-chained run-on sentence (flagged by
    _looks_like_runon_enumeration above) into a short numbered list,
    leaving every other sentence in *answer* untouched in its original
    position. A dedicated, focused post-generation repair step — asking
    the model to ONLY restructure already-written text, not simultaneously
    generate new content AND make a structural judgment call the way the
    original prompt-rule attempt required — the same principle behind
    every other "verify and repair after the fact" mechanism in this file
    (SRG's weave, PGF's claim-salvage rewrite) succeeding where getting it
    right in one generation pass did not.

    Verified the same word-survival way _pgf_rewrite_surviving_claims and
    _srg_weave_items_into_unit verify their own rewrites elsewhere in this
    file: every content word (4+ letters) in the original answer must
    still appear in the rewrite, within a small tolerance for natural
    rephrasing of connecting words — catches the model silently dropping
    or inventing content while "restructuring". Returns None (caller keeps
    the original answer untouched) on any failure, empty response, or a
    rewrite that fails this check — never risks losing content for the
    sake of better formatting.
    """
    try:
        prompt = f"""The ANSWER below may contain a sentence that crams 3 or more separate,
parallel items (distinct coverage types, steps, or options) together with commas into one
run-on sentence, instead of a clear list. If so, rewrite ONLY that sentence as a short
numbered list ("1. ... 2. ... 3. ..."), one complete sentence per item, keeping every OTHER
sentence in the ANSWER exactly as it already is, in its original position (before/after the
list). Do not add, remove, or change any fact — only restructure the run-on sentence's own
items into separate numbered points. If the ANSWER does NOT contain this shape at all,
output it EXACTLY AS-IS, character for character, changing nothing.

ANSWER: {answer}

Output ONLY the (possibly restructured) answer, nothing else — no preamble, no quotes."""
        # timeout=40, not the usual short ~12-15s budget most auxiliary
        # calls in this file use — confirmed live 2026-09-07: this call
        # rewrites a WHOLE answer (max_tokens=400), and this backend has
        # measured throughput as low as ~7-8 tok/s under real load, which
        # a 15s timeout structurally cannot survive for anything near a
        # full-length response — 2/2 real runs failed with an empty error
        # (httpx's own timeout exceptions often stringify to nothing),
        # while a trivial 5-token call on the same backend at the same
        # moment succeeded instantly, confirming this was a timeout
        # mismatch, not a genuine backend outage. This step only ever
        # runs on the minority of answers the cheap regex gate flags, so
        # the extra latency headroom costs nothing on the common path.
        raw = await _backend_completion(prompt, max_tokens=400, timeout=40)
        if not raw:
            return None
        raw = raw.strip().strip('"')
        if not raw:
            return None
        orig_words = set(re.findall(r"[a-zA-Z]{4,}", answer.lower()))
        new_words = set(re.findall(r"[a-zA-Z]{4,}", raw.lower()))
        missing = orig_words - new_words
        if len(missing) > max(2, len(orig_words) * 0.05):
            logger.debug(
                "[ask_stream] run-on restructure dropped too many words (%d missing), skipping",
                len(missing),
            )
            return None
        return raw
    except Exception as exc:
        logger.debug("[ask_stream] run-on restructure failed: %s", exc)
        return None


async def _detect_unjustified_recommendation(
    question: str, answer: str, context_chunks: Optional[list] = None,
) -> Optional[list]:
    """
    Catches an answer that settles on and recommends one or more specific
    named options (a particular plan/product/type) as clearly the right
    choice, when the QUESTION itself provides no basis to prefer that
    option over other valid alternatives the source material lists.
    Confirmed live, reproduced identically on this same local machine (not a backend/Groq
    quality fluke): "What should travel insurance cover before I buy it?"
    — a plain coverage-checklist question, no recommendation asked for —
    got "let's focus on a Single-Trip Plan... designed specifically for
    one journey" as its opening framing, inventing an assumption about the
    user's trip (that it's a single, occasional one) the question never
    stated, to justify picking ONE of five plan types the source actually
    lists (Single-Trip, Annual Multi-Trip, Family, Student, Senior
    Citizen).

    Deliberately an LLM judgment call, not a regex/keyword check — "did
    the question actually justify singling out this one option" requires
    understanding what the question asked and what the source offers as
    alternatives, which a pattern match structurally can't do (and this
    codebase has already hit this exact wall before: layering more regex
    onto a semantic question just moves the false-negative surface around
    rather than closing it). Kept to a single cheap call for the common
    case (nothing flagged) — the caller only pays for a second call when
    this one actually finds something.

    context_chunks (2026-09-07, revised same day): confirmed live this
    check was ALSO false-positiving the opposite way — flagging a
    genuinely correct, information-grounded recommendation ("Comprehensive
    Policy" for "what type of insurance should I buy to protect MYSELF
    from huge bills in a road accident") purely because it judged from the
    question's wording in isolation, with no way to check what the source
    material actually says each option covers. A prompt-only fix (adding a
    worked counter-example) did NOT reliably resolve this — 3/3 repeat
    tests still flagged it.

    First attempt at a real fix embedded `answer` against the retrieved
    chunk texts and narrowed to the top few by cosine similarity — this
    was WRONG and still confirmed live flagging 3/3 genuinely-justified
    recommendations the same afternoon ("Term life insurance", "Building
    or Structure Cover", "Comprehensive Policy" — all correct, all
    flagged). The bug: embedding the ANSWER and ranking chunks by
    similarity TO THE ANSWER is circular — it surfaces more chunks
    confirming the option the answer already picked, not chunks about the
    ALTERNATIVES that would let the model judge whether picking this one
    was actually justified over them. It can confirm the pick is real,
    never whether it was justified.

    Fixed by dropping the narrowing entirely: `context_chunks` is now
    expected to be the exact POST-COMPRESSION chunk pool (same scope SRG
    uses, see that mechanism's own chunk-scoping comment) — i.e. everything
    the model actually saw when generating the answer, already sized to
    fit a generation prompt's own budget, so no additional narrowing is
    needed for a judgment call over the same material. Joined into the
    prompt in full, unranked, so alternative options genuinely present in
    what the model saw are visible to the judge too, not just corroborating
    evidence for the one option already chosen. Optional and defaults to
    None so this still works (falling back to the original context-free
    prompt) if a caller can't supply chunks.

    Returns a list of the recommended items' own names (e.g. ["Single-Trip
    Plan"], or ["Term life insurance", "Critical Illness Rider"] when an
    answer makes more than one separate unjustified pick) if flagged, so
    the rewrite step below knows exactly what to remove without
    re-deriving it. Returns None on no-flag or on any failure — fails
    toward leaving the answer untouched, same fail-safe direction as
    every other best-effort check in this file.

    is_type_decision (2026-09-07): callers should skip calling this
    function entirely — not pass a flag into it — when the question is
    already a confirmed type-decision query (_is_type_decision_query(),
    already computed once per request and reused elsewhere in ask_stream
    for exactly this reason). Confirmed live: "If my house catches fire,
    what type of insurance should I buy?" got its correct, sole answer
    ("Building or Structure Cover") flagged and hedged even WITH the
    context-grounding fix above, because the detection prompt judges any
    single-name answer the same way regardless of whether the question
    itself explicitly asked for exactly one pick. A question that IS
    asking "which one type should I buy" makes a single named answer
    inherently justified by definition — there is no "unsolicited" pick to
    catch here, so the right fix is not calling this check at all for that
    question shape, not asking the judge to somehow reason its way to the
    same exemption every time.
    """
    try:
        # No narrowing — context_chunks is already the post-compression
        # pool (see this function's own docstring for why narrowing by
        # similarity-to-the-ANSWER was actively wrong: it only surfaces
        # more evidence for the option already picked, never the
        # alternatives needed to judge whether picking it was justified).
        context = "\n\n".join(context_chunks) if context_chunks else ""

        _context_block = (
            f"\nSOURCE CONTEXT (what the material actually says about the relevant options):\n{context}\n"
            if context else ""
        )
        prompt = f"""Does the ANSWER below settle on and recommend one or more SPECIFIC named
options (e.g. a particular plan, product, or type) as clearly the right choice, even though
the QUESTION doesn't specify anything that would justify preferring that option over other
valid alternatives the source material might offer? An answer can make MORE THAN ONE separate
unjustified pick — e.g. recommending one specific plan for the main need AND a separate
specific rider/add-on for something else, each with its own invented justification — check
the WHOLE answer for every such pick, not just the first one. This is about UNSOLICITED,
UNJUSTIFIED picks — not about a genuinely correct answer to a question that actually asked
for one, and not about simply naming an option as an EXAMPLE among several mentioned side by
side.

This also has to tell an UNJUSTIFIED pick apart from a GENUINELY CORRECT one, not just check
whether the question named the option explicitly. "What should travel insurance cover before
I buy it?" recommending "Single-Trip Plan" IS unjustified — the question gives no basis to
assume a single, occasional trip over an annual multi-trip, family, student, or senior-citizen
need; nothing in the source context ties "protect against X" to specifically the Single-Trip
Plan over the others. But if the SOURCE CONTEXT below shows that one option is defined as
covering something the QUESTION specifically asks to be covered, while another option
mentioned is defined as NOT covering that — e.g. the question asks about protecting the
policyholder's OWN losses, and the context says one option (e.g. third-party-only cover)
never covers the policyholder's own vehicle or medical costs while another option does —
then recommending the option the context says actually covers it is a real, information-
grounded answer, not an arbitrary pick, even though it names one specific option. Flag only
when picking the one option requires assuming some UNSTATED detail (trip length, family
status, budget, and similar) that the source context doesn't resolve either; never flag when
the question's own stated need, checked against what the SOURCE CONTEXT says each option
actually covers, already points to one specific correct answer.
{_context_block}
QUESTION: {question}

ANSWER: {answer}

If the ANSWER does this, reply with each such option's exact name on its own line (e.g.
"Single-Trip Plan" alone on one line; two lines if there are two separate unjustified picks),
nothing else — no numbering, no extra commentary. If it does not do this at all — including if
the QUESTION itself provided enough information to justify a specific recommendation, or the
ANSWER just neutrally describes options without picking one — reply with exactly: NONE"""
        # Pinned to Groq first (2026-09-03) — confirmed live this specific
        # judgment call is genuinely beyond the small local vLLM model, not
        # a prompt-phrasing problem: 8/8 identical "NONE" on a confirmed
        # real case even after adding a worked example (the technique that
        # fixed comparable small-model failures elsewhere this session).
        # The SAME prompt against Groq's larger model correctly flagged it
        # 3/3. Unlike the earlier attempt to pin EVERY policy-type
        # classification call to Groq (abandoned — that fires on most
        # queries and exhausted the shared 8000 TPM quota), this check
        # only runs once per generated answer, and the follow-up rewrite
        # call only fires on the rare answer that actually gets flagged —
        # low enough volume to be worth the quota. Falls back to whatever
        # backend is active if Groq is unavailable, same as every other
        # Groq-preferring call in this file.
        raw = await _backend_completion(prompt, max_tokens=60, timeout=12, backend_override="groq")
        if not raw:
            raw = await _backend_completion(prompt, max_tokens=60, timeout=12)
        if not raw:
            return None
        # One item per line — cap at 5 (an answer making more than 5
        # separate unjustified picks is far more likely a parsing
        # artifact than a real finding) and drop anything that's clearly
        # not a short option name (e.g. the model echoing "NONE" on its
        # own line alongside real picks, or a stray blank).
        flagged_items = []
        for _line in raw.strip().splitlines():
            _item = _line.strip().strip('"').lstrip("-*0123456789. )")
            if not _item or _item.upper() == "NONE":
                continue
            if len(_item) > 80:
                continue
            flagged_items.append(_item)
            if len(flagged_items) >= 5:
                break
        return flagged_items or None
    except Exception as exc:
        logger.debug("[ask_stream] unjustified-recommendation detection failed (%s)", exc)
        return None


async def _neutralize_unjustified_recommendation(
    question: str, answer: str, flagged_items: list, context_chunks: Optional[list] = None,
) -> Optional[str]:
    """
    Rewrites an answer flagged by _detect_unjustified_recommendation above
    — removes every unsolicited specific recommendation in *flagged_items*
    (there may be more than one — see that function's own docstring) and
    any invented assumption used to justify each, while preserving every
    other real fact in the answer unchanged. Same "try an LLM rewrite,
    fall back to the original on any failure or suspicious output"
    discipline already used for _srg_weave_items_into_unit elsewhere in
    this file — this can only improve the answer on success, never make
    it worse on failure, since the caller keeps the original untouched
    unless this returns a real rewrite.

    No length-ratio or word-overlap validation here (unlike the SRG weave
    check) — removing a whole sentence's worth of unjustified content is
    an EXPECTED, not suspicious, shrink, so a length-based safety check
    would just fight the very thing this function is meant to do. The
    prompt's own explicit "keep every other fact exactly as stated"
    instruction is the safeguard instead.

    context_chunks (2026-09-07): this used to rewrite completely blind —
    question, answer, and the flagged item's bare name, nothing about what
    the source material actually says. Confirmed live this produced a real
    loss, not just a neutral rephrase: "Term life insurance" got
    genericized down to bare "Life insurance" — losing the one distinction
    (term vs. whole vs. endowment) that actually matters, since "life
    insurance" alone isn't a real product. Same context_chunks the
    detector above now receives (the post-compression pool, unnarrowed —
    see that function's own docstring) is passed here too, so a rewrite
    that needs to describe what the OTHER real options are can draw on
    what the source genuinely states about them, instead of guessing at a
    vaguer, less useful generalization.
    """
    try:
        _context_block = (
            f"\nSOURCE CONTEXT (what the material actually says about the relevant options):\n"
            f"{chr(10).join(context_chunks)}\n"
            if context_chunks else ""
        )
        _items_quoted = ", ".join(f'"{i}"' for i in flagged_items)
        _plural = len(flagged_items) > 1
        prompt = f"""The ANSWER below recommends {_items_quoted} specifically, but the QUESTION
doesn't provide enough information to justify {"those specific choices" if _plural else "that specific choice"}
over other valid alternatives. Rewrite the ANSWER to remove {"those specific recommendations" if _plural else "that specific recommendation"}
and any invented assumption used to justify {"them" if _plural else "it"} (don't say "you should buy X" or
invent details about the user's own situation/trip) — but keep every OTHER real fact in the
ANSWER exactly as stated, just presented neutrally rather than tied to the recommended
option(s). Don't add any new fact that wasn't already in the ANSWER or in the SOURCE CONTEXT
below.

If removing {_items_quoted} leaves a gap where naming what the OTHER real alternatives are
(not recommending one, just naming them) would make the answer more useful, and the SOURCE
CONTEXT below actually names those alternatives, you may add them neutrally, side by side,
with no preference expressed. Do not invent alternatives that aren't in the SOURCE CONTEXT.
{_context_block}
QUESTION: {question}

ANSWER: {answer}

Rewrite:"""
        # Groq-first, same reasoning as the detection call above — this
        # only fires on the rare answer detection already flagged, so the
        # extra quota cost is small.
        raw = await _backend_completion(prompt, max_tokens=250, timeout=15, backend_override="groq")
        if not raw:
            raw = await _backend_completion(prompt, max_tokens=250, timeout=15)
        if not raw:
            return None
        rewritten = raw.strip().strip('"')
        if not rewritten:
            return None
        return rewritten
    except Exception as exc:
        logger.debug("[ask_stream] unjustified-recommendation rewrite failed (%s)", exc)
        return None


async def _pgf_extract_claims(text: str) -> list:
    """LLM-based atomic-claim decomposition — a SALVAGE step for the prose
    post-generation faithfulness path in ask_stream, only invoked after a
    sentence has already failed the whole-sentence _verify_point_faithfulness
    check above. Inspired by (not a dependency on) DeepEval's
    FaithfulnessMetric generate_claims prompt
    (deepeval/metrics/faithfulness/templates/generate_claims.txt) — tested
    standalone 2026-08-27 in an isolated venv against this app's own real
    retrieved context and Groq backend before wiring in, same methodology
    as the NeMo Guardrails evaluation this whole mechanism traces back to.

    NOT adopting DeepEval's own verdict step alongside the claim-extraction
    one: its default FaithfulnessMetric only flags a claim as unfaithful
    when the retrieval context DIRECTLY CONTRADICTS it (confirmed by
    reading generate_verdicts.txt and its guidelines fragment) — a claim
    that's simply absent from context with nothing to contradict it scores
    "idk", which does NOT count against the metric's score unless the
    caller opts into penalize_ambiguous_claims=True. That would silently
    fail to catch a pure fabrication (nothing in context to contradict —
    exactly this app's original "wellness programs and 24/7 helpline" bug).
    _verify_point_faithfulness's own entailment prompt already requires
    POSITIVE support, so it's kept unchanged as the verdict step here —
    only the claim-splitting idea is reused.

    Confirmed live: a bundled sentence combining one TRUE sub-claim with
    one FABRICATED sub-claim ("...within the specified time limit, and
    the insurer will also give you a free annual health checkup
    voucher...") gets a single DROP verdict from the existing whole-
    sentence check — correct in that the fabrication doesn't get through,
    but the genuinely correct half bundled with it is lost too, worse UX
    than necessary. Extracting claims and checking each independently
    kept the true half and dropped only the fabricated half on the same
    case. A fully-correct bundled sentence, by contrast, extracted as a
    single claim and passed unchanged in the same test — no over-
    splitting observed on real content.

    Runs on Groq specifically, not vLLM — this app's smaller vLLM model
    has an established pattern of poor compliance on structured-output/
    judgment tasks (see _verify_point_faithfulness's own hybrid design
    and its docstring), and a malformed claims list here would just fall
    back to the original whole-sentence drop anyway, so there's little to
    gain from risking a less reliable model on a salvage path that only
    ever runs after a failure.

    Returns an empty list — "nothing salvageable via decomposition" — on
    any failure (empty response, unparseable JSON, fewer than 2 claims
    found) or exception, so the caller's fallback is always to keep
    today's behavior of dropping the whole sentence, never to falsely
    claim a successful decomposition.
    """
    try:
        raw = await _backend_completion(
            _PGF_CLAIMS_PROMPT.format(text=text[:1500]),
            max_tokens=400, timeout=15.0, backend_override="groq",
        )
        if not raw:
            return []
        import json as _pgf_json
        _m = re.search(r'\{.*\}', raw, re.DOTALL)
        if not _m:
            return []
        _claims = _pgf_json.loads(_m.group(0)).get("claims")
        if not isinstance(_claims, list):
            return []
        _cleaned = [str(c).strip() for c in _claims if str(c).strip()]
        return _cleaned if len(_cleaned) >= 2 else []
    except Exception:
        return []


_PGF_STOPWORDS = frozenset({
    "the", "a", "an", "this", "that", "these", "those", "it", "its", "of",
    "to", "in", "on", "at", "for", "with", "by", "from", "as", "is", "are",
    "was", "were", "and", "or", "also", "such", "typically", "which",
})


def _pgf_claim_core_words(claim: str) -> list:
    """First 1-3 content words of *claim* (stopwords filtered) — used only
    to VERIFY a rewrite actually contains this claim's substance, the same
    word-overlap-tolerant technique _srg_weave_items_into_unit uses
    elsewhere in this file for the identical "did the LLM rewrite keep
    what it was supposed to" problem. Reimplemented locally (not a shared
    call) since that SRG closure is defined much later in ask_stream, well
    after this salvage path already needs to run.
    """
    words = [w for w in re.findall(r"[a-zA-Z][a-zA-Z'\-]{2,}", claim.lower()) if w not in _PGF_STOPWORDS]
    return words[:3]


async def _pgf_rewrite_surviving_claims(original_sentence: str, surviving_claims: list) -> Optional[str]:
    """Rewrites the VERIFIED-TRUE claims that survived _pgf_extract_claims'
    salvage split into one natural, smoothly-flowing sentence — used
    instead of a plain ". ".join() of the leftover claim fragments.

    Confirmed live 2026-09-07: a sentence bundling one true claim ("a
    policy typically includes third-party insurance") with a fabricated
    one ("...and also covers your own medical expenses") correctly had
    the fabrication dropped by per-claim verification, but naively joining
    the two TRUE leftover fragments back in — right after a DIFFERENT
    sentence about protecting the user's own losses — created a
    misleading juxtaposition: it read as if third-party insurance were
    part of protecting the user's own losses, which it structurally never
    covers. Each kept word was independently true; the SHAPE of gluing
    fragments back together is what was misleading.

    Same "can only shrink/rephrase already-verified-true content, never
    add scope" safety argument _neutralize_unjustified_recommendation's
    own docstring already relies on — the prompt is given ONLY the
    surviving claims and told to add nothing beyond them. Verified the
    same word-overlap-tolerant way _srg_weave_items_into_unit verifies its
    own rewrites elsewhere in this file: each surviving claim's own core
    content words (_pgf_claim_core_words) must appear in the rewrite, or
    this returns None and the caller falls back (see the call site's own
    comment for the exact fallback tiers — this function never decides
    the fallback itself, only whether ITS rewrite is safe to use).
    """
    try:
        _claims_joined = "; ".join(surviving_claims)
        _prompt = f"""You are given the original version of a sentence, and a list of ONLY the \
facts from it that have been independently verified as accurate. Rewrite those verified \
facts into ONE natural, smoothly-flowing sentence that reads as if it was written this way \
originally — not a list, not choppy fragments glued together.

Do not add, invent, or imply any fact beyond what is listed below — only rephrase and \
connect the facts given. Keep the same tone and person (you/your, etc.) as the original.

Original sentence (for tone/context only — do not restate anything from it that isn't \
also in the verified facts list): {original_sentence}

Verified facts (the ONLY things allowed in your rewrite): {_claims_joined}

Output ONLY the rewritten sentence, nothing else — no preamble, no quotes."""
        _raw = await _backend_completion(_prompt, max_tokens=150, timeout=12)
        if not _raw:
            return None
        _raw = _raw.strip().strip('"')
        if not _raw:
            return None
        _raw_lower = _raw.lower()
        for _claim in surviving_claims:
            _core = _pgf_claim_core_words(_claim)
            if not _core:
                continue
            _hits = sum(1 for w in _core if w in _raw_lower)
            _need = len(_core) if len(_core) <= 2 else 2
            if _hits < _need:
                logger.debug(
                    "[PGF-SALVAGE] rewrite dropped claim %r, falling back", _claim,
                )
                return None
        return _raw
    except Exception as exc:
        logger.debug("[PGF-SALVAGE] rewrite failed: %s", exc)
        return None


async def _verify_grounding_any_chunk(
    question: str, chunks: list, backend_override: Optional[str] = None,
) -> bool:
    """Grounded if EITHER the full joined multi-chunk context grounds the
    question OR the single top-ranked chunk alone does — checked in
    parallel, not sequentially, so this costs no extra latency over the
    plain multi-chunk check on the common (already-passing) path.

    Chunks must already be sorted best-first (true of every caller — all
    come from _rerank()/rerank_documents() output).

    Confirmed live: joining even one additional, lower-relevance chunk
    alongside the correct one can flip _verify_grounding()'s YES to a NO
    for the WHOLE block — "How are relatives typically notified about the
    contents of a policy documents?" against just the top chunk (containing
    "...kept in safe custody and in the knowledge of the close relatives")
    returned YES in isolation, but adding a second, merely-topically-
    adjacent chunk (about policy document contents generally) flipped the
    combined judgment to NO, even though the first chunk's relevant content
    didn't change. This is a real limitation of this codebase's small model
    when judging heterogeneous multi-chunk blocks (see _reformulate_query's
    docstring for other confirmed instances of this model's unreliability
    on nuanced multi-part judgments) — checking the strongest single
    candidate on its own recovers the case without weakening the existing
    multi-chunk check, which still runs and still catches genuinely
    wrong-topic content (verified: an off-topic single chunk alone is still
    correctly rejected, so this isn't a blanket loosening).
    """
    if not chunks:
        return False
    full_context = _build_grounding_context(question, chunks)
    top_context = _build_grounding_context(question, chunks[:1])
    full_result, top_result = await asyncio.gather(
        _verify_grounding(question, full_context, backend_override=backend_override),
        _verify_grounding(question, top_context, backend_override=backend_override),
    )
    return full_result or top_result


async def _contextualize_query(question: str, history: str) -> str:
    """Rewrite the question into a standalone, self-contained form by
    resolving pronouns and implicit references against recent conversation
    history. Runs on every turn — a true first-turn or already-standalone
    question should be returned unchanged, not gated behind a separate
    followup/not-followup classifier.

    *history* is a flat "User: ...\\nAssistant: ..." string as built by
    ConversationAgent._build_history_string(). Uses only the last 1-2
    turns via _split_history_turns().

    Fast-path: skip the LLM call entirely only when the question has no
    reference token AND is longer than ~6 words — a longer question with
    no pronoun/ordinal is reliably self-contained, but a SHORT one can
    still carry an implicit reference with no literal pronoun at all (a
    bare topic noun like "the exclusions", "the premium"), the same
    "definite article + generic policy-aspect noun" shape confirmed live
    2026-09-09: "What are the exclusions?" right after a health-insurance
    coverage answer had no pronoun to match, skipped this function's LLM
    check entirely, and (compounded by the same gap in
    _is_likely_followup, fixed separately — see _GENERIC_PROCESS_RE's own
    comment) retrieval ran on the bare phrase and answered with unrelated
    home-insurance exclusions instead. This is a latency optimization
    only for the genuinely-safe case (a long question with nothing to
    resolve); the LLM prompt below is what actually enforces correctness
    — a false-positive here just costs one extra LLM call that correctly
    returns the question unchanged.

    Fail-safe: on any exception, timeout, or empty response, return the
    original question unchanged.
    """
    if not history or not history.strip():
        return question

    if not _REFERENCE_TOKENS.search(question.strip().lower()) and len(question.split()) > 6:
        return question

    lines = _split_history_turns(history)
    recent = lines[-4:]
    if not recent:
        return question
    history_text = "\n".join(recent)

    prompt = (
        f"Recent conversation:\n{history_text}\n\n"
        f"New question: {question}\n\n"
        "Does the new question contain a pronoun or implicit reference "
        "(e.g. 'it', 'that', 'those', 'their', 'the second one') that "
        "depends on the conversation above to be understood? This "
        "includes a bare topic noun with no product/subject named — "
        "e.g. 'What are the exclusions?' or 'What is the premium?' "
        "right after a conversation about a specific insurance type "
        "implicitly means the exclusions/premium OF THAT SAME TYPE, "
        "even though it has no literal pronoun at all. This also covers "
        "a question with NO pronoun and NO obviously missing subject "
        "that still implicitly depends on context — e.g. 'Does treatment "
        "received while abroad get paid for too?' right after a health-"
        "insurance conversation is really asking about HEALTH insurance "
        "specifically, even though the sentence reads as grammatically "
        "complete on its own. The real test is not whether the sentence "
        "parses fine alone — it's whether the ANSWER would differ "
        "depending on which insurance type is involved (health vs travel "
        "vs motor, etc.). If the answer would differ by type and the "
        "question doesn't name one, that's an implicit reference needing "
        "resolution, same as a literal pronoun would be.\n"
        "If YES, rewrite the question to resolve that reference, "
        "replacing the pronoun/reference with the specific thing it "
        "refers to. If the reference is to an ordinal position in a "
        "numbered or listed answer above (e.g. 'the second point', "
        "'point 3', 'the last one'), rewrite it to name the SPECIFIC "
        "subject of that one point only — do not fold in neighboring "
        "points.\n"
        "If NO — the question is already a complete, standalone "
        "question, even if it's on a different topic than the "
        "conversation above — return the question completely "
        "UNCHANGED. Do not add topic context to a question that "
        "doesn't need it.\n"
        "Respond with ONLY the question (rewritten or unchanged), "
        "nothing else."
    )
    try:
        raw = await _backend_completion(prompt, max_tokens=60, timeout=15.0)
        if not raw or not raw.strip():
            return question
        return raw.strip()
    except Exception:
        return question


async def _extract_pasted_followup(question: str) -> Tuple[Optional[str], str]:
    """Detect a message that's really "<a block of previously-given text>"
    plus "<a short question about it>" pasted together as one message — e.g.
    a user copying a chunk of an earlier answer (even one from many turns
    back, well outside the retained history window) and asking about it
    directly, rather than relying on the system to still remember that far.

    Returns (pasted_context, actual_question). pasted_context is None (and
    actual_question is the original, unmodified question) when no paste is
    detected, including on any failure or ambiguity — the caller then
    behaves exactly as it did before this function existed.
    """
    # An ordinary question is never this long — skip the LLM round-trip
    # entirely below the bar where a paste becomes plausible.
    if len(question.split()) < 40:
        return None, question
    prompt = (
        f"Message:\n{question[:6000]}\n\n"
        "This message may be a block of previously-given text (e.g. copied "
        "from an earlier answer) followed by a short question or "
        "instruction about it (e.g. 'explain this simply', 'summarize the "
        "above', 'what does point 3 mean'). If so, respond with ONLY that "
        "short question or instruction, copied VERBATIM from the message — "
        "nothing else. If the message is just one ordinary question with "
        "no pasted block, respond with exactly: NONE"
    )
    try:
        raw = await _backend_completion(prompt, max_tokens=60, timeout=15.0)
    except Exception:
        return None, question
    if not raw or not raw.strip():
        return None, question
    extracted = raw.strip()
    if extracted.upper() == "NONE":
        return None, question
    idx = question.rfind(extracted)
    if idx == -1:
        # Couldn't confidently locate the extracted question verbatim in the
        # original message — be conservative and treat this as no paste
        # rather than guessing at a split point.
        return None, question
    pasted = (question[:idx] + question[idx + len(extracted):]).strip()
    # The remaining "pasted" portion must itself be substantial, or this was
    # likely just an ordinary question the model over-matched on.
    if len(pasted.split()) < 20:
        return None, question
    return pasted, _strip_paste_reference_filler(extracted)


# A follow-up about pasted content naturally opens with a connector back to
# it ("now based on this,", "given the above,") — these add no topical
# signal of their own and measurably dilute retrieval quality (embedding
# score for "what is the free look period..." dropped from 0.34 to 0.06
# once such a prefix was added, in testing). Stripped only from the
# extracted question, not from pasted_context or the user-facing answer —
# the LLM answering the question still has pasted_context available to
# resolve "this" against; only the KB search string needs to be clean.
_PASTE_FILLER_RE = re.compile(
    r'^\s*(?:now|so|then|well|okay|ok)?[,\s]*'
    r'(?:based on (?:this|that|the above)|given (?:this|that|the above)(?: information)?|'
    r'considering (?:this|that|the above))'
    r'(?: information)?[,\s]*',
    re.IGNORECASE,
)


def _strip_paste_reference_filler(text: str) -> str:
    stripped = _PASTE_FILLER_RE.sub('', text).strip()
    return stripped if stripped else text


# ── Ordinal point-reference follow-ups ("explain point 2", "the 2nd point") ──
# _contextualize_query() resolves these into a standalone retrieval query, but
# that resolution is itself unreliable: sometimes the model substitutes the
# point's real subject matter (works), sometimes it only normalizes the
# wording ("point 2" -> "the second point", still no topical content), and
# retrieval then has nothing to search with — confirmed in testing on two
# back-to-back examples that only differed in which the model happened to
# produce. The most reliable source for "what was point 2 about" is the
# numbered list already sitting in conversation history, not a fresh KB
# search trying to rediscover the same content. _extract_point_reference()
# pulls that point's own text out of history and feeds it through the exact
# same pasted-context path as a live paste (verify-then-bypass-or-blend) —
# so this reuses tested machinery rather than adding a parallel one.
_ORDINAL_WORDS = {
    'first': 1, 'second': 2, 'third': 3, 'fourth': 4, 'fifth': 5,
    'sixth': 6, 'seventh': 7, 'eighth': 8, 'ninth': 9, 'tenth': 10,
}
_POINT_REFERENCE_RE = re.compile(
    r'\bpoint\s+number\s+(\d+)\b|'
    r'\bpoint\s+(\d+)\b|'
    r'\bthe\s+(\d+)(?:st|nd|rd|th)?\s+point\b|'
    r'\bthe\s+(' + '|'.join(_ORDINAL_WORDS) + r')\s+point\b|'
    # Bare "N point" with no leading "the" — e.g. "explain 2 point in detail".
    # Confirmed live: "can you explain 2 point in simple language with
    # example" fell through every existing alternative above (all require
    # either "point N" ordering or a leading "the"), so _extract_point_number
    # returned None, point-text extraction never ran, and the question
    # reached the standalone-retry tier as an apparently topic-less query.
    r'\b(\d+)(?:st|nd|rd|th)?\s+points?\b|'
    r'\bnumber\s+(\d+)\b|'
    r'\bthe\s+(\d+)(?:st|nd|rd|th)\b(?!\s+\w)',
    re.IGNORECASE,
)
_NUMBERED_POINT_RE = re.compile(r'(?:^|\n)\s*(\d+)\.\s+')


def _extract_point_number(question: str) -> Optional[int]:
    """Return the 1-based point number *question* refers to (digit or
    spelled-out ordinal), or None if it doesn't reference one at all."""
    m = _POINT_REFERENCE_RE.search(question.lower())
    if not m:
        return None
    for g in m.groups():
        if g is None:
            continue
        if g.isdigit():
            return int(g)
        if g in _ORDINAL_WORDS:
            return _ORDINAL_WORDS[g]
    return None


def _extract_point_text_from_history(history: str, point_num: int) -> Optional[str]:
    """Find point *point_num*'s own text in the MOST RECENT assistant turn's
    numbered list — None if that turn isn't numbered, or that point number
    isn't in it.

    Deliberately does NOT keep searching older turns when the most recent
    answer has no numbered list. Used to `continue` past it and grab a
    numbered list from further back in history — confirmed live: the most
    recent answer used a "Term: description" glossary-style format with no
    digit markers (a real, separate formatting drift, tracked elsewhere),
    so this fell through to a numbered list from an unrelated, much earlier
    turn in the same long-running session (a property/fire insurance
    example) and fed it into a follow-up about the CURRENT health insurance
    answer — wrong-topic content injected as if it were "point 2" of what
    the user was actually looking at. "Point 2" always means point 2 of the
    answer on screen right now; if that answer isn't numbered, there's no
    point 2 to find, full stop — don't guess from history.
    """
    turns = _split_history_turns(history)
    for turn in reversed(turns):
        if not turn.startswith("Assistant:"):
            continue
        content = turn[len("Assistant:"):].strip()
        matches = list(_NUMBERED_POINT_RE.finditer(content))
        if not matches:
            return None
        for i, m in enumerate(matches):
            if int(m.group(1)) == point_num:
                start = m.end()
                end = matches[i + 1].start() if i + 1 < len(matches) else len(content)
                point_text = content[start:end].strip()
                return point_text or None
        return None
    return None


_MEANING_QUERY_RE = re.compile(
    r"^(?:"
    r"what\s+(?:does|do|is)\s+(?:the\s+word\s+|the\s+term\s+)?"
    r"['\"]?(?P<w1>[a-z][a-z\s'-]{0,40}?)['\"]?\s+mean\b"
    r"|what\s+do\s+you\s+mean\s+by\s+['\"]?(?P<w2>[a-z][a-z\s'-]{0,40}?)['\"]?\s*\??$"
    r"|what\s+is\s+the\s+meaning\s+of\s+['\"]?(?P<w3>[a-z][a-z\s'-]{0,40}?)['\"]?\s*\??$"
    r"|meaning\s+of\s+['\"]?(?P<w4>[a-z][a-z\s'-]{0,40}?)['\"]?\s*\??$"
    r"|define\s+['\"]?(?P<w5>[a-z][a-z\s'-]{0,40}?)['\"]?\s*\??$"
    r"|what\s+does\s+['\"]?(?P<w6>[a-z][a-z\s'-]{0,40}?)['\"]?\s+stand\s+for\b"
    r")",
    re.IGNORECASE,
)

# Pronouns/generic fillers the regex above will happily capture as "the
# word" (e.g. "what does that mean?" → w1="that") but that are never what
# the user actually wants defined — that phrasing means "explain the thing
# you just said differently", handled elsewhere by the meta-clarify and
# contextualization paths, not "look up the dictionary meaning of 'that'".
_MEANING_QUERY_STOPWORDS = frozenset({
    "that", "this", "it", "they", "them", "he", "she", "we", "you", "i",
    "something", "anything", "everything", "nothing", "one", "these", "those",
})


def _extract_meaning_query_word(question: str) -> Optional[str]:
    """Return the word/short phrase *question* is asking the meaning of
    ("what does X mean?", "meaning of X", "define X", "what does X stand
    for?"), or None if it isn't that kind of question.

    Deliberately narrow (anchored patterns, not a loose "contains 'mean'"
    check) so it doesn't fire on unrelated sentences that happen to contain
    the word "mean" (e.g. "what does this mean for my premium" — a real
    coverage question, not a word-definition request). Also filters out
    pronouns/fillers via _MEANING_QUERY_STOPWORDS, since the regex alone
    can't distinguish "what does 'discount' mean?" (real word) from "what
    does that mean?" (pronoun — regex would otherwise capture "that").
    Callers should still verify the extracted word actually appears in
    recent history before using it, same discipline as
    _extract_point_number's callers.
    """
    m = _MEANING_QUERY_RE.match(question.strip())
    if not m:
        return None
    for name in ("w1", "w2", "w3", "w4", "w5", "w6"):
        w = m.group(name)
        if w and w.strip() and w.strip().lower() not in _MEANING_QUERY_STOPWORDS:
            return w.strip()
    return None


_HANDOFF_MSG = (
    "I don't have that in my knowledge base right now. "
    "Let me get a human agent to help you! 😊"
)


def _strip_markdown(text: str) -> str:
    """Convert markdown-formatted LLM output to plain conversational prose.

    The chat prompt forbids bullet points and bold, but the model sometimes
    ignores that — especially when the retrieved context itself contains
    formatted content. Called by api.py's streaming handler on each small
    flushed chunk of the response as it streams (not the whole response at
    once), so the user never sees raw markdown mid-stream.

    Deliberately does NOT strip numbered-list markers ("1. ", "2. ") the
    way it used to — DETAILED_GROUNDED_PROMPT explicitly wants numbered
    points, and ask_stream() already handles both directions correctly on
    the complete response before this ever runs: it enforces numbering
    deterministically when a detailed answer's model output didn't use it,
    and strips stray markers when a brief answer's shouldn't have any (see
    multi_source_rag.py's "Strip stray numbered-list markers" section).
    Stripping markers here too, on arbitrary small per-flush chunks, was
    actively harmful rather than redundant: since api.py flushes as soon as
    a chunk contains ANY space or newline, whether "\n2. " for a genuinely
    correct detailed-mode point landed inside the SAME flush as its
    trailing space (letting this regex match and destroy it) or got split
    across two separate flushes (leaving it untouched) came down to
    arbitrary token-boundary luck for that specific generation — confirmed
    live: the exact same "explain in detail" request rendered as a clean
    numbered list in some runs and a single unbroken paragraph in others,
    with no difference in the underlying model output's actual formatting.
    That, in turn, silently broke follow-up "explain point N" references,
    since the numbering that later parsing depends on had already been
    destroyed before it was ever saved to conversation history.
    """
    import re
    # Remove bold/italic markers
    text = re.sub(r'\*{1,3}([^*]+)\*{1,3}', r'\1', text)
    # Remove ATX headers (## Heading -> Heading)
    text = re.sub(r'^#{1,4}\s+', '', text, flags=re.MULTILINE)
    # Convert bullet list items to flowing prose: "- item" or "* item" -> "item, "
    text = re.sub(r'\n\s*[-*]\s+', ' ', text)
    # Inline code backticks
    text = re.sub(r'`([^`]+)`', r'\1', text)
    # Collapse 3+ newlines -> 2
    text = re.sub(r'\n{3,}', '\n\n', text)
    return text


def _strip_model_preamble(text: str) -> str:
    """Remove auto-generated meta-commentary lines the LLM prepends to answers."""
    # Use simple string replace to strip robot emoji — avoids regex encoding issues
    text = text.replace('\U0001F916', '').replace('\U0001f916', '')
    _TEXT_STARTS = (
        "response was brief",
        "no specific values or formulas",
        "no further action was needed",
    )
    lines = text.split("\n")
    clean = [l for l in lines if not any(l.strip().lower().startswith(p) for p in _TEXT_STARTS)]
    # Remove leading blank lines
    while clean and not clean[0].strip():
        clean.pop(0)
    return "\n".join(clean).strip()


_RULE4_MARKER_RE = re.compile(r"i don.t have that specific", re.IGNORECASE)

# Matches the filler-word usage of "honest,"/"honestly," (comma right after,
# functioning as a sentence-starting interjection) — not a legitimate
# adjective use like "an honest answer". The prompt now bans this word
# outright, but see the ask_stream call site for why that alone isn't
# trusted: this filler was already a known compliance gap when the prompt
# only asked for the full "honestly," spelling (the model unreliably
# shortened it to "honest,"), so banning the word entirely needs the same
# deterministic backstop, not just the new instruction. Only matches at a
# sentence boundary (start of string, after ./!/?  + space, or after a
# newline) so it strips the discourse-marker usage and capitalizes what
# follows, without touching "an honest answer" mid-sentence.
_HONESTLY_FILLER_RE = re.compile(r"(?:^|(?<=[.!?]\s)|(?<=\n))[Hh]onest(?:ly)?,\s*(\w)")

# The frontend renders assistant messages as plain text (no markdown
# parser) — confirmed live: the model sometimes writes "**Legal
# Expenses**: ..." for emphasis, which the chat UI shows as literal
# asterisks around the words instead of bold text. Stripped
# deterministically rather than adding markdown rendering to the
# frontend, consistent with how this session has handled every other
# case of "the model does something the display layer doesn't expect."
# Non-greedy and requires the pair to close on the same line so it
# can't accidentally swallow unrelated text if the model ever emits an
# unpaired "**".
_MARKDOWN_BOLD_RE = re.compile(r"\*\*([^\n*]+?)\*\*")

# Every live prompt explicitly bans the em dash (—), but the model doesn't
# reliably follow that — same lesson as every other formatting-compliance
# gap in this file (numbered lists, the "honestly" filler, markdown bold):
# don't trust a prompt-only instruction, enforce it deterministically too.
# Confirmed live: "wat is a deductable in helth insurnace" (a fresh, never-
# tested typo-laden query) came back with "It's like setting a threshold —
# you handle the cost..." despite the ban. Replaced with a comma rather
# than a period — safer as a universal default since guessing "does this
# em dash join two independent clauses" wrong would produce a sentence
# split with broken capitalization; a comma splice reads fine in the
# casual, conversational tone this bot already uses everywhere.
_EM_DASH_RE = re.compile(r"\s*—\s*")

# The vLLM backend (Qwen2.5-7B) occasionally code-switches into Chinese
# mid-response even though the question and the rest of the answer are
# English — confirmed live: "...plus any bonuses累积的。具体金额取决于
# 你的保单条款..." tacked onto an otherwise-complete English sentence.
# Re-running the identical question 4/4 times came back clean English,
# so this is a non-deterministic generation-sampling artifact, not a
# retrieval or prompt bug worth chasing upstream. Stripped
# deterministically like every other display-layer mismatch this
# session: delete the non-Latin-script run and clean up what's left
# rather than showing garbled mixed-language text. Covers CJK ideographs
# plus Japanese kana, Hangul, and CJK/fullwidth punctuation so it isn't
# tied to this one Chinese-specific incident.
_NON_LATIN_SCRIPT_RE = re.compile(
    r"[　-〿぀-ヿ㐀-䶿一-鿿가-힯＀-￯]+"
)


def _strip_rule4_fallback(text: str, trust_content: bool = True) -> Optional[str]:
    """Handle the LLM appending the canned Rule 4 fallback ("Hmm, I don't
    have that specific info...") after already writing something, or
    putting the refusal marker FIRST and real content AFTER it.

    Returns:
      None            — marker not found, caller should leave text untouched.
      non-empty str   — marker found, trust_content was True, and there was
                         real content on at least one side of the marker
                         (>40 chars) — return the best trustworthy content
                         (before, after, or both joined).
      ""              — marker found but trust_content was False (or neither
                         side has enough content) — the marker is the model's
                         own admission the text isn't solidly grounded.
                         Caller should discard and show the standard refusal.

    trust_content should reflect independent evidence (e.g. a high reranker
    score) that the content is actually grounded — text pattern matching
    alone can't tell a correct answer with a pointless disclaimer apart from
    a shaky inference with a legitimate one.

    Applied both to freshly-generated answers AND to KV cache hits — a cache
    hit can replay an answer that was cached before this fix existed, so the
    check has to run on served text either way, not just on fresh generations.
    """
    stripped = (text or "").rstrip()
    m = _RULE4_MARKER_RE.search(stripped)
    if not m:
        return None

    real_before = stripped[:m.start()].strip()

    # The refusal sentence itself can run several sentences past the
    # marker start (e.g. "...I don't have that specific info right now.
    # Let me get one of our agents on it!") before real content resumes.
    # Find where the NEXT sentence after the marker begins so we don't
    # keep fragments of the refusal itself in real_after.
    tail = stripped[m.end():]
    # Skip to the first sentence boundary in the tail (end of the
    # refusal sentence/clause), then trim any immediately-following
    # generic handoff filler sentence if present.
    sentence_end = re.search(r'[.!?]\s+', tail)
    real_after = tail[sentence_end.end():].strip() if sentence_end else ""
    # Drop a leading handoff-filler sentence from real_after if the model
    # chained it right after ("...Let me get one of our agents on it...").
    # Optional "but (don't worry,)?" prefix added 2026-07-23 — the canned
    # refusal template in prompt_template.py (line 183) phrases this exact
    # filler sentence as "But don't worry, I can get one of our agents to
    # help you out!", not "Let me get...". Without the prefix, that whole
    # sentence survived into real_after untouched — the standard refusal
    # ("Hmm, I don't have that specific info...") has TWO sentences, both
    # boilerplate, but only the first (before the marker) was ever being
    # recognized as boilerplate; the second read as "real content" and got
    # returned verbatim. Confirmed live this then fed straight into the
    # warm-lead-in fallback further downstream, which doesn't recognize a
    # sentence starting with "But" as a natural opener and prepends "So, "
    # (lowercasing "But"->"but" to fit), producing the nonsensical
    # "So, but don't worry, I can get one of our agents to help you out!"
    # actually shown to a live user instead of the correct full refusal.
    handoff_lead = re.match(
        r'((?:but\s+)?(?:don\'t worry,?\s*)?(?:let me get|i can get)\s+'
        r'(?:one of our agents|a human agent)[^.!?]*[.!?]\s*)',
        real_after, re.IGNORECASE,
    )
    if handoff_lead:
        real_after = real_after[handoff_lead.end():].strip()

    if not trust_content:
        return ""

    if len(real_before) > 40 and len(real_after) > 40:
        return f"{real_before} {real_after}".strip()
    if len(real_before) > 40:
        return real_before
    if len(real_after) > 40:
        return real_after
    return ""


# ── Rider-to-standalone-product misattribution detector (log-only) ─────────
# Confirmed live 2026-07-23: "Hospital cash and surgical care riders" — an
# optional add-on to a TERM LIFE policy, the source video explicitly framing
# it as "for those without comprehensive health insurance" — got restated in
# a generated answer as if it were a feature of "a mediclaim policy" itself.
# This is a different failure axis than the existing cross-policy-TYPE
# contamination work (Phase 0-2, plan.md): every source here is genuinely,
# correctly on-topic (all health/hospital-bill-adjacent) — nothing from the
# wrong policy TYPE leaked in. The failure is the model blending a fact
# across two DIFFERENT NAMED PRODUCTS that happened to both be retrieved,
# not a wrong-type retrieval. A dedicated prompt rule now asks the model not
# to do this (see prompt_template.py, "sounds grounded but isn't" rule (d)),
# but confirmed live that prompt-only compliance holds only part of the
# time (3/4 fresh test runs after the prompt fix still merged rider content
# into "health insurance"/"mediclaim" framing without saying "rider").
#
# Log-only for now, same measure-before-act approach this codebase already
# used for the point-relevance gate (Phase 0 traced real frequency before
# Phase 2 built an active gate) — not enough real-traffic data yet to know
# how often this actually fires, or how precise the signal is, to justify
# an active correction. Revisit once there's real trace volume to look at.
_RIDER_MARKER_RE = re.compile(r"\brider(s)?\b", re.IGNORECASE)
# Requires 2+ words immediately before "rider(s)", each 3+ letters — a bare
# regex with no minimum word count (tried first) matched garbage like "This
# riders" or "What are the riders" from unrelated sentences that merely
# happen to end in the word "rider(s)" (a generic listicle intro, a stray
# mid-sentence occurrence), which then false-fired on almost any answer
# containing a common short word like "this". Requiring a real 2+ word
# phrase filters those out while still matching genuine feature names
# ("Hospital cash and surgical care riders", "Accidental death benefit
# rider").
_RIDER_FEATURE_RE = re.compile(
    r"\b([a-z]{3,}(?:[ ,&/-]+[a-z]{3,}){1,6})\s+riders?\b", re.IGNORECASE,
)
# Filler words that satisfy the 3+-letter/2+-word shape above but aren't a
# real feature name on their own — confirmed live in _RIDER_FEATURE_RE's
# false-positive sweep (e.g. "another interesting riders", "what are the
# riders").
_RIDER_FEATURE_STOPWORDS = frozenset({
    "this", "that", "what", "some", "unique", "another", "interesting",
    "coming", "are", "the", "for", "and", "very", "also", "one", "two",
})
_STANDALONE_PRODUCT_TERMS = (
    "mediclaim", "medi-claim", "medi claim",
    "health insurance", "health policy", "health plan", "medical insurance",
)


def _detect_rider_misattribution(answer_text: str, context_text: str) -> Optional[dict]:
    """
    True (well, a dict) when the answer names a standalone health product
    (mediclaim/health insurance) without ever saying "rider", while also
    reusing 2+ distinctive words from context text that explicitly describes
    a "<feature> rider(s)" — i.e. the answer likely dropped the "this is an
    add-on, not an inherent feature" context the source itself made clear.

    Takes the PRE-COMPRESSION context string (_full_context_uncompressed,
    already captured earlier in ask_stream for exactly this reason — see
    its own comment there), not the post-compression `all_chunks` used for
    generation. Confirmed live this distinction is load-bearing, not
    theoretical: the compressor keeps only the highest-scoring ~7% of each
    chunk's text (one real trace showed "12901 chars across 5 chunks ->
    target 900 chars"), and it kept the sentences describing the rider's
    coverage while dropping the SAME chunk's "...riders, who is it for?"
    framing sentence — so checking the compressed chunks the model actually
    saw found zero matches for a case that had very clearly happened (the
    generated answer itself proved the model saw the rider content from
    somewhere). The pre-compression string is what was actually retrieved,
    which is the correct question to ask here, same reasoning
    _full_context_uncompressed's own existing comment already gives for
    every other check that reads it.

    Deliberately loose (word-overlap, not exact-phrase) since the model
    paraphrases freely — this only needs to be a good-enough signal, not a
    precise auto-corrector. Scans every match rather than stopping at the
    first hit, and keeps the strongest (most-overlapping) candidate — a KB
    with several rider mentions shouldn't have its verdict decided by
    whichever happened to appear first in the joined string.
    """
    if _RIDER_MARKER_RE.search(answer_text):
        # Answer already says "rider" somewhere -- it's correctly framing
        # this as an add-on, not attributing it to a standalone product.
        return None
    answer_lower = answer_text.lower()
    if not any(term in answer_lower for term in _STANDALONE_PRODUCT_TERMS):
        return None
    best_hits, best_result = 0, None
    for m in _RIDER_FEATURE_RE.finditer(context_text or ""):
        feature_phrase = m.group(1).strip()
        feature_words = [
            w for w in re.findall(r"[a-z]+", feature_phrase.lower())
            if len(w) > 3 and w not in _RIDER_FEATURE_STOPWORDS
        ]
        if len(feature_words) < 2:
            continue
        hits = sum(1 for w in feature_words if w in answer_lower)
        if hits >= 2 and hits > best_hits:
            best_hits = hits
            best_result = {"feature_phrase": feature_phrase}
    return best_result


def _correct_rider_misattribution(answer_text: str, context_text: str) -> Optional[str]:
    """
    Active correction on top of _detect_rider_misattribution(): appends a
    short clarifying parenthetical to whichever sentence carries the
    misattributed rider content — never edits or removes any existing
    text. Deliberately additive-only: _strip_rule4_fallback's own
    handoff_lead gap (fixed 2026-07-23, same day) is a direct, confirmed
    example of what goes wrong when this codebase deletes/splices
    generated text instead — it left an orphaned sentence fragment that a
    DIFFERENT downstream fixer (the warm-lead-in fallback) then mangled
    further into "So, but don't worry...". Appending a parenthetical at
    the end of the flagged sentence can't produce that failure mode —
    worst case it reads as a slightly redundant aside, never a broken one.

    Returns None when nothing needs correcting (mirrors
    _detect_rider_misattribution's own None-means-clean contract).
    """
    hit = _detect_rider_misattribution(answer_text, context_text)
    if not hit:
        return None
    feature_words = [
        w for w in re.findall(r"[a-z]+", hit["feature_phrase"].lower())
        if len(w) > 3 and w not in _RIDER_FEATURE_STOPWORDS
    ]
    sentences = re.split(r"(?<=[.!?])(?<!\d\.)\s+", answer_text)
    best_idx, best_hits = None, 1  # same >=2-hit bar the detector itself uses
    for i, sent in enumerate(sentences):
        hits = sum(1 for w in feature_words if w in sent.lower())
        if hits > best_hits:
            best_hits, best_idx = hits, i
    if best_idx is None:
        return None
    sent = sentences[best_idx].rstrip()
    m = re.match(r"^(.*?)([.!?]+)?$", sent, re.DOTALL)
    body = (m.group(1).rstrip() if m else sent) or sent
    punct = (m.group(2) if m and m.group(2) else ".")
    sentences[best_idx] = (
        f"{body} (usually available as an optional add-on rider, "
        f"not a standard policy feature){punct}"
    )
    return " ".join(sentences)


# ── Source self-reference stripping (deterministic) ─────────────────────────
# Backstop for prompt_template.py's "never say 'the video'/'this video',
# never name a file/document" rule (all 3 grounded prompts) — confirmed
# live the prompt rule alone isn't fully reliable (roughly 1 in 4-5
# generations still said "The video mentions that..." even with the
# explicit instruction in place), the same "prompt-only compliance isn't
# fully reliable" pattern as every other formatting rule in this file.
#
# Originally video-only; broadened 2026-07-26 after a live "explain travel
# insurance in detail" answer said "The guide mentions that you can find
# more information about definitions..." and "The guide suggests visiting
# the customer service web page..." — the SAME self-reference leak, just
# for a PDF/document source instead of a video transcript. The existing
# rule already banned this in spirit (rule 14/9: "never repeat [the
# source label], or part of one, to the user"), it just hadn't been
# generalized past the one confirmed phrase shape ("the video ...").
#
# Purely subtractive on a narrow, confirmed phrase shape, and ONLY at the
# very start of a sentence — a whole leading clause ("The guide mentions
# that X" -> "X") drops cleanly with just a recapitalized first letter,
# the same lesson the warm-lead-in fallback already learned about not
# leaving a stray lowercase opener behind. Deliberately does NOT also
# strip a mid-sentence or trailing occurrence ("...are also covered in
# the guide.") — tried the mid-sentence case for the video-only version
# and confirmed live it produces broken grammar; every dominant real
# instance seen so far is sentence-initial anyway, a mid-sentence/trailing
# occurrence is a smaller, rarer residual gap safer to leave to the
# prompt rule than to risk a broken splice on.
#
# "that" is REQUIRED, not optional — also tried making it optional (to
# also catch "The guide mentions a term insurance plan that provides X"),
# and confirmed live that's unsafe too: stripping down to just "a term
# insurance plan that provides X" leaves a bare noun phrase with no main
# verb, not a real sentence — the leading "that" is what guarantees
# whatever follows is already a complete subject-verb clause on its own,
# since "mentions THAT" always introduces one. Without "that" present, the
# verb's object is a noun phrase, not a clause, and this fixer correctly
# leaves it alone rather than risk a fragment.
_SOURCE_SELF_REF_RE = re.compile(
    r"\A(?:the|this|that|our|my)\s+(?:videos?|guides?|documents?|policy\s+wording|sources?|articles?)\s+"
    r"(?:mentions?|shows?|explains?|says?|discusses?|covers?|notes?|states?|talks?\s+about)\s+"
    r"that\s+",
    re.IGNORECASE,
)


def _strip_source_self_reference(text: str) -> str:
    sentences = re.split(r"(?<=[.!?])(?<!\d\.)\s+", text)
    changed = False
    for i, sent in enumerate(sentences):
        m = _SOURCE_SELF_REF_RE.match(sent)
        if not m:
            continue
        rest = sent[m.end():]
        if rest:
            rest = rest[0].upper() + rest[1:]
        sentences[i] = rest
        changed = True
    if not changed:
        return text
    return " ".join(s for s in sentences if s.strip())


# ── Numbered-list format enforcement (deterministic backstop) ──────────────
# prompt_template.py's FORMAT section requires a numbered list, one point per
# line, for TYPES/KINDS QUESTIONS and COMPARISON QUESTIONS — confirmed live
# (2026-07-24) the prompt rule alone isn't fully reliable: the same query
# ("What are different types of life insurance?") returned a clean numbered
# list on most fresh test runs but plain prose on others, no code change in
# between — the same "prompt-only compliance holds most but not all of the
# time" pattern as _DETAIL_PATTERN's "in detail" gap and
# _strip_source_self_reference's source-reference gap above, this time driven
# by vLLM's own batched-inference run-to-run variance rather than a phrasing
# gap in the prompt. Since it's a sampling issue, not a prompt-wording issue,
# strengthening the prompt text further (already tried twice this session)
# won't close it — only a deterministic backstop can.
_NUMBERED_LINE_RE = re.compile(r"(?m)^\s*\d+\.\s")


def _has_numbered_list_format(text: str) -> bool:
    return len(_NUMBERED_LINE_RE.findall(text)) >= 2


async def _enforce_numbered_list_format(
    query: str, answer_text: str, is_type_decision: bool = False,
) -> Optional[str]:
    """
    When `query` is a TYPES/KINDS question (see _TYPES_OF_QUERY_RE) and
    `answer_text` came back as prose instead of the required numbered
    list, makes ONE narrow, temperature=0 LLM call whose only job is to
    RESTRUCTURE the existing text into numbered lines — never to add,
    remove, or reword any fact. Purely a formatting pass, not a
    regeneration.

    COMPARISON questions (_COMPARISON_QUERY_RE) used to trigger this too,
    reformatting into a numbered list — moved to
    _enforce_comparison_table_format below instead (2026-08-13, user
    feedback: a numbered list reads badly for a two-item comparison,
    wants a real table), which produces a genuine HTML <table> via the
    same ui-marker mechanism travel_bot's format_compare_quotes already
    proved out, not markdown table syntax (the chat bubble's renderMarkdown
    has no pipe-table support — confirmed by that exact same comment in
    format_compare_quotes). Comparison queries are EXCLUDED here rather
    than left to also match, to avoid two back-to-back reformat LLM calls
    on the same answer (list, then table) for one query.

    is_type_decision: the caller's already-resolved _is_type_decision_query()
    result (see that function and _TYPE_DECISION_RE's block comment) —
    reused rather than re-derived here to avoid a second LLM round trip
    reaching a possibly different conclusion. _TYPES_OF_QUERY_RE alone
    can't tell a genuine "what types of X are there" enumeration apart
    from "what type of X should I buy" naming the user's own situation;
    without this, this reformatter would turn a short, correct,
    already-generated recommendation answer BACK into a numbered list
    of unrelated coverage details, undoing the whole point of the
    decision-vs-enumeration prompt override upstream.

    Returns None (no correction, safe to keep the original prose) when: the
    query isn't a TYPES/KINDS enumeration (or is a TYPES/KINDS decision
    question, not a real enumeration), the answer already has numbered
    lines, the answer is a refusal message, the answer is too short to
    plausibly hold 2+ distinct points, or the reformat call fails, times
    out, or produces something that fails a basic length-sanity check
    (guards against a truncated or hallucinated rewrite slipping through).
    """
    _is_types_query = await _is_types_enumeration_query(query)
    if _is_types_query and is_type_decision:
        return None
    if not _is_types_query:
        return None
    if _has_numbered_list_format(answer_text):
        return None
    if answer_text.strip().lower().startswith("hmm, i don't have"):
        return None
    if len(answer_text) < 80:
        # Too short to plausibly hold 2+ distinct points — a genuine
        # one-fact answer the KNOWLEDGE BASE only partially supports, not a
        # formatting failure prompt_template.py's own rules already cover
        # (TYPES/KINDS QUESTIONS: "if the KB genuinely gives zero detail...
        # fall back to rule 8's decline instead of an empty-feeling list").
        return None

    prompt = f"""Reformat the ANSWER below into a numbered list — one distinct point per
line, each starting with "1. ", "2. ", "3. " etc. Do NOT add, remove, change, or reword
any fact or word — only restructure it with line breaks and numbering, preserving the
exact wording. If the ANSWER genuinely does not contain 2 or more distinct separable
points, return it completely unchanged, exactly as given, with no numbering added and no
extra commentary.

ANSWER:
{answer_text}

REFORMATTED:"""

    try:
        # timeout=35, not the 3s used by the tiny classification calls
        # elsewhere in this file (e.g. _classify_query_policy_type_llm) —
        # confirmed live those calls generate ~10 tokens while this one
        # generates up to 700, and the main answer generation itself over
        # this same backend has been observed taking 7-38s (see ask_stream's
        # own TIMING log) for comparable output lengths. A short timeout
        # here just silently no-ops the whole fix on the backend's normal
        # slow path instead of actually reformatting.
        raw = await _backend_completion(
            prompt, max_tokens=min(700, max(200, len(answer_text) // 3 + 150)),
            timeout=35, temperature=0,
        )
    except Exception as exc:
        logger.debug("[ask_stream] numbered-list reformat call failed: %s", exc)
        return None
    if not raw:
        return None
    reformatted = raw.strip()

    # Drop any conversational preamble before the first numbered point
    # ("Here's the reformatted list:\n\n1. ...") — the model is a chat
    # model, not a raw completion model, so a stray lead-in is possible even
    # with an explicit "no extra commentary" instruction.
    first_marker = re.search(r"(?m)^\s*1\.\s", reformatted)
    if first_marker:
        reformatted = reformatted[first_marker.start():]

    if not _has_numbered_list_format(reformatted):
        return None
    # A pure restructure shouldn't shrink or grow the content meaningfully —
    # guards against a truncated or hallucinated rewrite.
    if not (0.6 * len(answer_text) <= len(reformatted) <= 1.6 * len(answer_text)):
        logger.debug(
            "[ask_stream] numbered-list reformat rejected on length sanity check (%d -> %d chars)",
            len(answer_text), len(reformatted),
        )
        return None
    return reformatted


async def _enforce_prose_format(
    query: str, answer_text: str, is_type_decision: bool = False,
) -> Optional[str]:
    """
    Mirror of _enforce_numbered_list_format above, for the opposite
    failure direction: a DECISION question ("what type should I buy for
    my pet") whose answer STILL came back as a numbered list despite the
    prompt override that's supposed to force plain prose for exactly
    this case (see _TYPE_DECISION_RE's block comment and the "Type-of-X
    decision-vs-enumeration override" in ask_stream, which reassigns
    `detailed = False` and routes to a prose-capable prompt with an
    explicit "Plain prose, no numbered list" instruction specifically
    because DETAILED_GROUNDED_PROMPT's own FORMAT section has no prose
    branch at all).

    Confirmed live 2026-09-01: even with that override correctly firing,
    the model still generated a numbered list anyway — the same "a
    prompt's own worked examples/habits beat a one-off instruction"
    failure already documented elsewhere in this file, just recurring
    for a DIFFERENT prompt. The real damage isn't the numbering itself —
    it's what happens NEXT: downstream numbered-list-specific checks
    (the dangling they/these opener check, PGF's per-point grounding
    check) evaluate each numbered line as an independent, isolated unit.
    A pronoun that clearly refers back to the PREVIOUS point when read as
    connected prose ("...Accident and Illness Plans. They typically
    include...") reads as a dangling reference with no antecedent once
    that previous point is a separate numbered line instead of the
    previous sentence — and gets dropped, taking real, correct content
    down with it. Confirmed live: "what type of policy should I buy for
    my pet" lost its single most informative sentence ("They typically
    include a wide range of medical treatments and can help with
    unexpected vet bills...") to exactly this, leaving a thin, one-line
    answer. Converting back to prose HERE, before either downstream
    check runs, means the pronoun is read in its original, correct
    context and never gets isolated in the first place.

    Same "restructure only, never add/remove/reword a fact" discipline
    and safety checks as _enforce_numbered_list_format: a temperature=0
    LLM call whose only job is to join numbered lines into flowing
    prose, rejected if the result still has numbered-list formatting or
    fails the same length-sanity bounds a truncated/hallucinated rewrite
    would fail.
    """
    if not is_type_decision:
        return None
    if not _has_numbered_list_format(answer_text):
        return None
    if answer_text.strip().lower().startswith("hmm, i don't have"):
        return None

    prompt = f"""Reformat the ANSWER below from a numbered list into flowing prose — plain
sentences, no numbering, no line-by-line list structure. Do NOT add, remove, change, or
reword any fact — only restructure it: join the points into natural connected sentences,
so a pronoun like "it", "this", or "they" clearly refers back to what it's about within
the flowing text, the same way it would if it had been written as prose from the start.

ANSWER:
{answer_text}

REFORMATTED:"""

    try:
        raw = await _backend_completion(
            prompt, max_tokens=min(700, max(200, len(answer_text) // 3 + 150)),
            timeout=35, temperature=0,
        )
    except Exception as exc:
        logger.debug("[ask_stream] prose reformat call failed: %s", exc)
        return None
    if not raw:
        return None
    reformatted = raw.strip()
    if _has_numbered_list_format(reformatted):
        return None
    if not (0.6 * len(answer_text) <= len(reformatted) <= 1.6 * len(answer_text)):
        logger.debug(
            "[ask_stream] prose reformat rejected on length sanity check (%d -> %d chars)",
            len(answer_text), len(reformatted),
        )
        return None
    return reformatted


# ── Named-pair depth enforcement (deterministic trigger, LLM-executed) ─────
# prompt_template.py's COMPARISON QUESTIONS rule already asks the model to
# give both named items equal depth — confirmed live (2026-07-24) this
# alone isn't reliable even after strengthening it with a concrete example:
# "What are Form A and Form B motor insurance?" explained Form B (the
# Comprehensive Policy) in real detail and reduced Form A to a throwaway
# clause ("which is typically a basic policy") or dropped it to one
# dismissive sentence, on 3/3 fresh runs AFTER the prompt fix — while
# asked about Form A alone, the model explains it fine (same KNOWLEDGE
# BASE, same retrieved source pages in both cases — confirmed by comparing
# the "sources" list of both requests). This is a content-completeness
# gap, not a formatting one — _enforce_numbered_list_format can't fix it,
# it only reformats whatever content exists into numbered lines, lopsided
# or not.
#
# The underlying bug is general — ANY two specifically named things in one
# question or point can end up with one explained and the other
# shortchanged, not just capitalized labels like "Form A"/"Form B" (that
# was just the reproduction case, not the scope of the fix — capitalization
# was an implementation shortcut, not a property of the actual failure).
# _PHRASE deliberately does NOT require capitalization, so "health
# insurance and term insurance" is extracted exactly like "Form A and Form
# B" — the depth-balance check downstream (_sentence_chars_mentioning
# etc.) doesn't care about casing either. The negative lookahead excludes
# WH-words/aux-verbs from starting a captured phrase — without it, "What
# is car insurance and how does it work?" would greedily capture "how does
# it work" as if it were a second named item, since it's 4 word-chars that
# otherwise fit the shape. Capped at 2 words (not 4): confirmed live that a
# longer cap over-captures a shared trailing category noun into the SECOND
# name with nothing to stop it there — "What are Form A and Form B motor
# insurance?" extracted name_b as "Form B motor insurance" instead of
# "Form B", since nothing bounds the second phrase's end the way the
# literal "and" bounds the first. 2 words still covers every real case
# seen (Form A/Form B, health insurance/term insurance) and a slightly
# truncated capture (e.g. "personal accident" instead of "personal
# accident insurance") is still distinctive enough for the substring
# matching _sentence_chars_mentioning does downstream — it only needs to
# recognize which sentences are about which name, not reproduce the exact
# phrase.
_PHRASE = r"(?!(?:how|why|what|where|when|does|do|did|is|are|can|will|would|should|could|shall)\b)(?:the\s+|an?\s+)?[A-Za-z][\w'-]*(?:\s+[A-Za-z][\w'-]*){0,1}"

# Same as _PHRASE, but also refuses to sweep a trailing subordinating
# conjunction into the optional second word — needed for the bundling
# patterns below specifically, which (unlike "compare X and Y") commonly
# have a conditional clause immediately after the second name ("...cover
# both my house and my car IF a storm damages both"). Confirmed live
# (2026-08-27): plain _PHRASE captured "car if" as the second item
# verbatim. Kept separate from _PHRASE itself rather than editing the
# shared pattern, since _PHRASE's existing 2-word greediness is relied on
# by the comparison patterns above, where a trailing conjunction isn't a
# real risk (a comparison question ends at the second name, it doesn't
# keep going into a conditional clause).
_BUNDLE_PHRASE = (
    r"(?!(?:how|why|what|where|when|does|do|did|is|are|can|will|would|should|could|shall)\b)"
    r"(?:the\s+|an?\s+)?[A-Za-z][\w'-]*"
    r"(?:\s+(?!(?:if|since|unless|because|as|so|though|although|when|while)\b)[A-Za-z][\w'-]*){0,1}"
)

# Patterns tried against the QUERY, in order — these are all genuine
# comparison-intent phrasings ("compare X and Y", "what are X and Y",
# etc.), so a match here is a strong, low-false-positive signal of which
# two things the user is actually asking about.
_NAMED_PAIR_QUERY_PATTERNS = [
    re.compile(rf"\bcompare\s+({_PHRASE})\s+and\s+({_PHRASE})", re.IGNORECASE),
    re.compile(rf"\bdifference\s+between\s+({_PHRASE})\s+and\s+({_PHRASE})", re.IGNORECASE),
    re.compile(rf"\b({_PHRASE})\s+(?:vs\.?|versus)\s+({_PHRASE})", re.IGNORECASE),
    re.compile(rf"\bwhat\s+(?:is|are)\s+({_PHRASE})\s+and\s+({_PHRASE})", re.IGNORECASE),
    # Bundling shape, not a comparison — "does one policy cover both my
    # house and my car" names two separate items too, just to ask whether
    # ONE product spans both rather than to contrast them. Confirmed live
    # (2026-08-27) this shape has zero regex hit for either type on its
    # own (no "home insurance"/"motor insurance" phrase anywhere in it),
    # so it fell through to a single-label LLM guess that could only pick
    # ONE side — which then fed a single-type retrieval reservation
    # skewed entirely toward that one side, fabricating a bundling claim
    # exactly like [[project_cross_type_bundling_hallucination]] already
    # fixed once at the prompt level, just reached via a different path.
    # Feeding this into the SAME named-pair machinery as the comparison
    # patterns above gets it the SAME dual-type retrieval split (both
    # sides actually retrieved and merged, see _np_pair_for_retrieval's
    # own call site) — NOT the comparison-TABLE formatting, which is
    # gated separately on _COMPARISON_QUERY_RE and doesn't match this
    # phrasing at all, so a bundling question still reads as prose.
    # Optional possessive ("my"/"our"/"your") kept OUTSIDE the capturing
    # group, same reasoning as _LEADING_ARTICLE_RE's article-stripping —
    # every caller wants the bare noun, not "my house" verbatim.
    re.compile(
        rf"\b(?:one|the\s+same|a\s+single)\s+policy\s+cover\s+(?:both\s+)?"
        rf"(?:my|our|your|the)?\s*({_BUNDLE_PHRASE})\s+and\s+(?:my|our|your|the)?\s*({_BUNDLE_PHRASE})",
        re.IGNORECASE,
    ),
    re.compile(
        rf"\bcover\s+both\s+(?:my|our|your|the)?\s*({_BUNDLE_PHRASE})\s+and\s+(?:my|our|your|the)?\s*({_BUNDLE_PHRASE})",
        re.IGNORECASE,
    ),
]

# Tried against the ANSWER text (not the query) — this is the
# in-detailed-answer sub-point shape confirmed live ("There are two forms
# of motor insurance policies: Form A and Form B.") where the ORIGINAL
# question never named either item, so nothing in the query itself could
# have triggered the patterns above. Deliberately scoped narrow (requires
# the explicit "are types/kinds/forms of" framing) rather than matching
# any "X and Y" in the answer — that would false-positive on every
# ordinary list ("covers damage and theft").
_NAMED_PAIR_ANSWER_PATTERN = re.compile(
    rf"\b({_PHRASE})\s+and\s+({_PHRASE})\s+are\s+(?:types|kinds|forms)\s+of\b", re.IGNORECASE
)


_LEADING_ARTICLE_RE = re.compile(r"^(?:the|an?)\s+", re.IGNORECASE)

# English elides a shared trailing word off every item but the last: "crop
# and livestock insurance" means "crop insurance and livestock insurance",
# but _PHRASE only ever captures what's literally there, so group 1 comes
# back as bare "crop" while group 2 keeps "livestock insurance" — an
# asymmetric pair that then leaks straight into comparison-table column
# headers ("Crop" next to "Livestock Insurance"). Confirmed live. Reconstruct
# the elided word onto whichever side is missing it.
_ELIDED_SUFFIX_RE = re.compile(r"\s+(insurance|policy|policies|coverage)$", re.IGNORECASE)

# Term names from insurance_terms_glossary.pdf ([[project_insurance_glossary_and_pipeline_check]]),
# restricted to entries that _PHRASE can actually capture (1-2 whitespace
# words — a hyphenated word like "co-payment" or "free-look" counts as
# one). Used ONLY to decide whether a general/general named-pair query
# ("deductible" vs "premium") is safe to split-retrieve like a
# cross-type comparison already does — see the retrieval-split block
# below for why this needs to be a real, content-backed list rather than
# a shape-based guess.
_GENERAL_VOCAB_TERMS = frozenset({
    "premium", "deductible", "co-payment", "copayment", "co-pay", "copay",
    "grace period", "lapse", "policy lapse", "sum insured", "idv",
    "cash value", "surrender value", "rider", "endorsement", "exclusion",
    "policyholder", "insurer", "insured", "beneficiary", "nominee",
    "underwriter", "actuary", "tpa", "claim", "indemnity", "subrogation",
    "ncb", "no-claim bonus", "waiting period", "pre-existing condition",
    "proposal form", "policy term", "renewal", "free-look period",
    "moral hazard", "reinsurance", "third-party insurance",
})


def _extract_named_pair(text: str, patterns: List[re.Pattern]) -> Optional[Tuple[str, str]]:
    for pat in patterns:
        m = pat.search(text)
        if not m:
            continue
        # _PHRASE's leading "(?:the\s+|an?\s+)?" is nested INSIDE this
        # capturing group, not excluded by it — a non-capturing group only
        # means "no separate group reference," it doesn't remove the text
        # from an outer group that wraps it. So a query like "difference
        # between a deductible and a premium" was capturing "a deductible"
        # verbatim, article included, which then leaked straight into
        # comparison-table column headers. Strip it here instead of
        # reworking the shared regex, since every caller wants the bare
        # noun phrase.
        a = _LEADING_ARTICLE_RE.sub("", m.group(1).strip())
        b = _LEADING_ARTICLE_RE.sub("", m.group(2).strip())
        a_suffix, b_suffix = _ELIDED_SUFFIX_RE.search(a), _ELIDED_SUFFIX_RE.search(b)
        if b_suffix and not a_suffix:
            a += b_suffix.group(0)
        elif a_suffix and not b_suffix:
            b += a_suffix.group(0)
        if a and b and a.lower() != b.lower():
            return a, b
    return None


# ── Comparison-table format (2026-08-13, user feedback) ────────────────────
# _enforce_numbered_list_format used to reformat comparison answers into a
# numbered list, same as TYPES/KINDS answers — but a numbered list reads
# badly for a two-item comparison ("1. deductible is X, 2. premium is Y"
# doesn't read as a comparison at all). Redirected here instead: produces
# a genuine HTML <table> via the SAME structured-ui mechanism travel_bot's
# format_compare_quotes.py already proved end-to-end (ChatResponse.ui,
# ui.type == "comparison_table", frontend's buildComparisonTable()) rather
# than embedding markdown table syntax in the answer text — the chat
# bubble's renderMarkdown has no pipe-table support (confirmed live by
# that exact same comment in format_compare_quotes.py: a plain-text pipe
# table used to show up as literal '|'/'---' characters). Reuses
# _extract_named_pair/_NAMED_PAIR_QUERY_PATTERNS/_NAMED_PAIR_ANSWER_PATTERN
# above (same named-item extraction _enforce_named_pair_depth already
# relies on) for the table's column headers, rather than re-deriving or
# asking the LLM to guess the two names.
# Confirmed live: the model's first output row is sometimes its OWN prompt
# template line echoed back as if it were real data — "attribute label |
# value for deductible | value for premium" — despite the prompt saying
# "no header row". _TABLE_VALUE_ECHO_RE below catches this independent of
# the label wording (the literal "value for" substring only ever appears
# in the template itself, never in genuine restructured content), which is
# a more robust signal than trying to enumerate every header-ish label the
# model might echo.
_TABLE_ROW_SKIP_LABEL_RE = re.compile(
    # "^step\s*\d*$" confirmed live: adding a Definition-row instruction to
    # the prompt once caused the model to echo "Step 1"/"Step 2" literally
    # as row labels, with the row's real label/values shifted into the
    # wrong slots — the same template-echo failure mode as the other
    # entries here, just triggered by the word "step" instead of a
    # placeholder token.
    r"^-{2,}$|^attribute(\s+label)?$|^point$|^criteria$|^comparison$|^colou?r$|^step\s*\d*$",
    re.IGNORECASE,
)
_TABLE_VALUE_ECHO_RE = re.compile(
    r"\bvalue\s+for\b|\bthe\s+fact\s+about\b|\bshort\s+attribute\s+name\b|"
    # Confirmed live: the prompt's non-insurance "apples and oranges" shape
    # illustration ("Color | Red or green | Orange") leaked verbatim into a
    # real deductible/premium table — no insurance policy attribute is
    # ever legitimately "Red or green" or "Orange", so these are safe,
    # unambiguous echo signals, same idea as "value for" above.
    r"\bred\s+or\s+green\b|^orange$",
    re.IGNORECASE,
)
# Confirmed live: a row can echo just ONE side's name rather than both
# (e.g. "Cost | Deductible | Out-of-pocket before insurance helps" — the
# deductible column is just the bare word "Deductible", not a real fact,
# while the premium column holds a real sentence). The two-sided
# _is_name_echo_row check in the parsing loop only catches the case where
# BOTH sides are bare names; this catches EITHER side alone.
_TABLE_ROW_DIGIT_RE = re.compile(r"\d[\d,]*")
# Deliberate, scoped exception to the general "no currency/payment figures
# unless the query says 'example'" policy (see ask_stream's own
# _is_example_request block, and [[feedback_numbers_only_in_examples]]) —
# user feedback (2026-08-13): a comparison table specifically benefits
# from a concrete example figure regardless of whether the user's
# question used the word "example", since it helps the reader picture
# the comparison concretely. If the ANSWER already has a real example
# figure, the reformat prompt below uses it; if not, the model is
# explicitly permitted to invent one plausible illustrative figure per
# side FOR THIS ONE ROW ONLY — every other row still must come from facts
# actually stated in the ANSWER. This is the one place in this file that
# deliberately allows non-grounded content into a response; everything
# else stays under GROUNDING's normal no-hallucination rules. Only
# applies to _enforce_comparison_table_format — the general prose policy
# for every other query shape is unchanged.


async def _enforce_comparison_table_format(query: str, answer_text: str) -> Optional[Tuple[str, dict]]:
    """
    When `query` is a COMPARISON question (_COMPARISON_QUERY_RE) naming two
    specific things, converts `answer_text` into
    {"columns": [name_a, name_b], "rows": [{"label": attribute, "values":
    [val_a, val_b]}, ...]} via ONE narrow, temperature=0 LLM call whose
    only job is to RESTRUCTURE existing facts into rows — never to add,
    remove, or invent one. Purely a formatting pass, not a regeneration,
    same discipline as _enforce_numbered_list_format.

    Returns (intro_text, table) on success — intro_text is the only text
    that replaces answer_text in the chat bubble; the caller attaches
    table separately via the ui trailer (mirrors travel_bot's own
    (intro_text, table) return shape from format_compare_quotes). Returns
    None (keep answer_text unchanged) when: the query isn't a comparison
    question, no two named items can be extracted from it or the answer,
    the answer is a refusal message, too short to plausibly hold 2+
    comparison points, or the reformat call fails, times out, or produces
    fewer than 2 usable rows (guards against a truncated or hallucinated
    table slipping through — no length-ratio check here, unlike the
    numbered-list formatter, since collapsing prose into short row values
    is expected to shrink the character count substantially even when
    every fact survives).
    """
    if not _COMPARISON_QUERY_RE.search(query):
        return None
    pair = (
        _extract_named_pair(query, _NAMED_PAIR_QUERY_PATTERNS)
        or _extract_named_pair(answer_text, [_NAMED_PAIR_ANSWER_PATTERN])
    )
    if not pair:
        return None
    # Title-cased for display — the query itself is whatever case the user
    # typed ("difference between a deductible and a premium"), and that
    # verbatim casing was flowing straight into the table's column headers.
    # Every downstream comparison against name_a/name_b is already
    # case-insensitive (.lower() on both sides), so this is display-only.
    name_a, name_b = pair[0].strip().title(), pair[1].strip().title()
    if answer_text.strip().lower().startswith("hmm, i don't have"):
        return None
    if len(answer_text) < 80:
        return None

    # Split the ALREADY-GENERATED answer into its own sentences and hand
    # the LLM that numbered list directly, rather than the whole essay —
    # every one of these sentences already passed this pipeline's own
    # grounding/faithfulness checks before this function ever runs, so the
    # reformat call's job is narrowed to DECOMPOSING sentences already
    # known to be true into table rows, never discovering what to compare
    # or restating a fact from scratch. Confirmed live this distinction
    # matters: asked to "find each distinct attribute the ANSWER makes"
    # from a whole paragraph, this reformat call failed outright (produced
    # <2 usable rows, silently fell back to prose) in 2 of 3 fresh
    # attempts on the exact same question, and inverted one row's values
    # once (a "Coverage" row stated backwards from what the same table's
    # own Definition row said) — open attribute-discovery across an
    # entire paragraph is a much harder task than deciding, one given
    # sentence at a time, which two values it states.
    _table_example_re = re.compile(
        r'^(for example|for instance|as an example|to illustrate|'
        r"here'?s an example|let'?s say|let us say|say you|"
        r'suppose you|imagine you)\b', re.IGNORECASE,
    )
    _table_raw_sentences = [
        s.strip() for s in re.split(r'(?<=[.!?])\s+', answer_text.strip()) if s.strip()
    ]
    _table_example_sentences = [s for s in _table_raw_sentences if _table_example_re.match(s)]
    _table_fact_sentences = [s for s in _table_raw_sentences if not _table_example_re.match(s)]
    if len(_table_fact_sentences) < 1:
        return None
    _table_numbered_sentences = "\n".join(f"{i+1}. {s}" for i, s in enumerate(_table_fact_sentences))
    _table_example_hint = (
        " ".join(_table_example_sentences) if _table_example_sentences
        else "(none — the ANSWER never gave a worked example, invent one for STEP 2 below)"
    )

    prompt = f"""The numbered SENTENCES below are already-verified, true statements comparing
"{name_a}" and "{name_b}". Do not question, re-derive, or add to what they say — only
restructure them into a comparison table. Do this in two separate steps, both required.

STEP 1 — decompose the SENTENCES into rows, definition row first. Every row you write in
this step — INCLUDING the Definition row described below — must follow this shape: one
label, then BOTH items' values side by side on the SAME line. Never write a row whose LABEL
is {name_a} or {name_b} themselves — that produces one row per ITEM instead of one row per
shared POINT, which is wrong even for the Definition row. Wrong shape (never do this, for
any row, including Definition):
{name_a} | <something about {name_a}> | Not specified
{name_b} | Not specified | <something about {name_b}>
Right shape, illustrated with a completely unrelated, non-insurance example so it can never
be confused with real content (comparing apples and oranges — notice the LABEL is the shared
point, never the item's own name, and BOTH items get a value on the SAME row; never reuse
this wording or these facts, it is only to show the shape):
Color | Red or green | Orange

With that shape in mind: the SENTENCES near the start that introduce or define each term
(e.g. "A deductible is...", "Life insurance provides...") become ONE row labeled
"Definition" (literally that word — never {name_a} or {name_b}), one short plain clause per
side, only lightly reworded from those SENTENCES — enough that someone who has never heard
either term before understands what each one even IS, not just how they differ. This
Definition row is mandatory and must come first.

For every SENTENCE after that, output one row per SENTENCE, or per small group of adjacent
SENTENCES that state the exact same shared point — following the same right shape shown
above, with a shared-attribute label of your own choosing (such as cost, duration, who it
covers, when it applies) — but only when the SENTENCE actually is about that attribute; the
label must describe what the row's own two values actually say, never a label picked from
this list just because it sounds like a plausible comparison point in general. Confirmed
live: a row was labeled "Cost" for two values that were both really about the BREADTH of
what's covered ("wider range of coverage for various medical expenses" vs "focuses on
immediate financial needs") — neither value names a price, premium, or amount, so "Cost" was
wrong; "Scope of Coverage" would have matched what the row actually said. Never label a row
"Cost" (or "Duration", "Who It Covers", etc.) unless its own SENTENCE states a price, time
period, or covered-person fact — otherwise write a label straight from what that SENTENCE is
actually about. Cover every SENTENCE below with a row: do not skip one, and do not
add a row for a fact not stated in these SENTENCES — you are decomposing given true
statements, not researching or inventing new ones. Never invent a number or amount in this
step either — every figure in a STEP 1 row must appear in the SENTENCES verbatim; if you want
to state an amount that isn't there, that only belongs in the Example row from STEP 2, never
here. The same rule applies to LISTS, not just numbers: if a row restates something a
SENTENCE enumerates — which methods, types, categories, or items something covers or
involves — include only the items that SENTENCE itself names, never an extra item of your
own on top, even one that would obviously belong on that kind of list in general (confirmed
live: a "modes of transport" row correctly carried over the source sentence's own list, then
added two more transport methods that were never stated at all — invented because they're
common real-world examples of the category, not because the source said so). If a SENTENCE is
about some other insurance type entirely, skip it — it does not belong in this table. If a
SENTENCE only states a fact for one side of a real attribute, use "Not specified" for the
other side's value on that row rather than guessing — but never label the row with {name_a}
or {name_b} themselves, always with the shared attribute.

Before writing each row, double check which item the SENTENCE you're decomposing is actually
about — the FIRST value column is always {name_a}, the SECOND is always {name_b}, in that
order, every row. A fact a SENTENCE states about {name_a} must go in the {name_a} column,
never the {name_b} column, even if that SENTENCE happens to come later in the numbered list
than a SENTENCE about {name_b}. Putting a true fact in the wrong column states something
false about both items — re-read the SENTENCE and confirm which of the two names it names
before placing the value, and confirm the polarity of what it says (what it DOES cover/cost/
include versus what it does NOT) lands on the correct side, not swapped.

STEP 2 — add one example row, always, no exceptions. After ALL of the STEP 1 rows (not
after each one — exactly one Example row total for the whole table, no matter how many
STEP 1 rows you wrote), add exactly one more row, labeled "Example", giving one short,
concrete real-world SCENARIO sentence for EACH side, each with its OWN specific invented
figure worked in naturally. Neither a bare fragment like "₹500 hospital bill" nor a
scenario with no number at all is acceptable — every Example value needs both a
situation AND a figure, always, for both sides. ANY invented currency figure in this row
must use ₹ (Indian Rupees) — this is an Indian insurance context throughout, never $ or
any other currency symbol (confirmed live: an earlier version of this instruction's own
placeholder example used $, and the model copied that currency symbol into its own
invented insurance figures even though every other real figure in this KB is in ₹ —
jarring and wrong for a reader with Indian policies). Right shape (never reuse this
wording or the ₹15, it is a deliberately unrelated non-insurance example only to show the
shape — one that names a real insurance type gets copied verbatim into real answers about
that same type instead of prompting the model to invent its own, confirmed live): "A
commuter's train is delayed by two hours and the rail operator refunds ₹15 of their
ticket." Unlike STEP 1, this row does NOT need to come only from the numbered SENTENCES —
the ANSWER's own example, if any, is quoted below for this step specifically; adapt it into
one sentence each if present, otherwise invent one plausible, representative scenario for
each side, specifically about {name_a} and {name_b} (it only needs to help the reader
picture the comparison, not be a real quoted rate). This step is mandatory even if STEP 1
produced no rows at all. Never leave either side of the Example row as "Not specified" or
blank.

Output ONLY the rows from both steps — no header row, no markdown, no numbering, no extra
commentary before or after.

SENTENCES:
{_table_numbered_sentences}

ANSWER's own example (for STEP 2 only, may be "none"):
{_table_example_hint}

TABLE:"""

    try:
        # Same timeout/token-budget reasoning as _enforce_numbered_list_format
        # above — this backend's normal generation latency (7-38s observed)
        # means a short timeout would just silently no-op the whole feature.
        # Confirmed live: the mandatory Definition row (added same day)
        # makes every table systematically longer — a 4-attribute-row
        # table with full-sentence Definition/Cost/Coverage values ran up
        # against the old 500-token ceiling and got cut off mid-value in
        # its last row ("$1," instead of a full figure). Raised to 700.
        raw = await _backend_completion(
            prompt, max_tokens=min(700, max(150, len(answer_text) // 3 + 150)),
            timeout=35, temperature=0,
        )
    except Exception as exc:
        logger.debug("[ask_stream] comparison-table reformat call failed: %s", exc)
        return None
    if not raw:
        return None

    # Digit tokens (commas stripped) that genuinely appear in the ANSWER —
    # used below to catch a STEP 1 row inventing a number ($X, $500, etc.)
    # that was never actually stated, which STEP 1's own instructions
    # explicitly forbid (only the Example row may invent a figure).
    _answer_digit_tokens = {d.replace(",", "") for d in _TABLE_ROW_DIGIT_RE.findall(answer_text)}

    # Confirmed live: adding the mandatory Definition row (below) made the
    # reformat call, when asked to state "what {name_a}/{name_b} actually
    # is" as a standalone sentence, sometimes reach for a generic
    # memorized definition instead of the ANSWER's own — once producing
    # "Life insurance provides coverage based on regular payments made by
    # the policyholder" as the DEFINITION OF PREMIUM in a deductible-vs-
    # premium table, the exact cross-topic-contamination failure mode this
    # codebase has hit many times in the main answer path (same
    # [[project_cross_topic_contamination]] class), just newly reachable
    # here via the reformat call's own hallucination rather than
    # retrieval/generation.
    #
    # Two more precise approaches were tried and rejected before this one:
    # (1) raw _ANCHOR_TYPE_RE word matching false-flagged genuine "health
    # insurance" rows just for saying "medical" (a synonym the regex
    # groups with "health" for matching, but a plain word-vs-word set
    # comparison doesn't know is the same type); (2) reusing
    # classify_query_policy_type (the main retrieval path's own
    # query-length classifier) false-flagged short generic row cells —
    # confirmed live, classify_query_policy_type("Policyholder") alone
    # returns "livestock_insurance" from incidental keyword overlap, since
    # that classifier is tuned for 5-10-word QUERIES, not 1-3-word table
    # cells. Landed on requiring the STRONG, explicit "<Type> insurance"
    # phrase shape specifically — _ANCHOR_TYPE_RE's own optional trailing
    # "(\s+insurance)?" group, only counted when it actually matched. This
    # is exactly the shape the real contamination bug took ("Life
    # insurance provides...") and neither false-positive case above ever
    # produces that shape, so requiring it trades a little recall (a
    # contaminated row phrased without the word "insurance" would slip
    # through) for much higher precision (never wrongly drops a good row)
    # — the right tradeoff, since a missed row just leaves the table
    # slightly less complete while a false positive actively throws away
    # good content.
    def _anchor_types_in(text: str) -> set:
        return {m[0].lower() for m in _ANCHOR_TYPE_RE.findall(text or "")}
    def _strong_anchor_types_in(text: str) -> set:
        return {m.group(1).lower() for m in _ANCHOR_TYPE_RE.finditer(text or "") if m.group(2)}
    _expected_anchor_types = _anchor_types_in(name_a) | _anchor_types_in(name_b)

    rows = []
    _seen_row_labels: set = set()
    for line in raw.strip().split("\n"):
        line = line.strip().lstrip("-*").strip()
        if line.count("|") < 2:
            continue
        parts = [p.strip().strip("-").strip() for p in line.split("|")]
        if len(parts) < 3:
            continue
        label, val_a, val_b = parts[0], parts[1], parts[2]
        # Confirmed live (twice, independently): a row whose values are
        # just the two item names restated verbatim ("Label | Deductible |
        # Premium", "Coverage scope | Fire insurance | Home insurance") —
        # the model treating the column headers themselves as a row rather
        # than a real point of comparison. Not wrong, just content-free;
        # drop it the same way _TABLE_VALUE_ECHO_RE drops template echo.
        _is_name_echo_row = (
            val_a.strip().lower() == name_a.strip().lower()
            and val_b.strip().lower() == name_b.strip().lower()
        )
        # Confirmed live: a row where BOTH sides literally say "Not
        # specified" — the model attempting a row neither side of the
        # ANSWER actually supports. (not val_a and not val_b) below only
        # catches genuinely empty strings; this catches the placeholder
        # text itself, which is just as uninformative as a blank row.
        _is_blank_row = (
            val_a.strip().lower() == "not specified"
            and val_b.strip().lower() == "not specified"
        )
        # Confirmed live: without a shape example the model sometimes
        # degenerates into one row PER ITEM instead of one row per shared
        # attribute — label == the item's own name, with that item's real
        # content on its own side and "Not specified" on the other. Two such
        # rows (one per item) look superficially like a real comparison but
        # never let a reader see both items' values for the same attribute
        # side by side, defeating the table's whole purpose. Drop rather
        # than try to salvage — the fact still exists in the ANSWER's prose
        # even if this reformat call didn't manage to pair it up correctly.
        _is_item_name_label_row = label.strip().lower() in (name_a.strip().lower(), name_b.strip().lower())
        # Confirmed live: a row can echo just ONE side's name rather than
        # both — e.g. "Cost | Deductible | Out-of-pocket before insurance
        # helps" (val_a is the bare item name, not a real fact, while val_b
        # holds real content). _is_name_echo_row above only catches BOTH
        # sides being bare names; this catches either side alone. Also
        # checks each value against the OTHER side's name (cross-column) —
        # confirmed live: "Uncontrollable Factors | Livestock Insurance |
        # Not specified" in a crop-vs-livestock table put the LIVESTOCK
        # item's own name in the CROP column as if it were a fact about
        # crop insurance. A same-column check alone (val_a vs name_a,
        # val_b vs name_b) never catches this, since the echoed name is on
        # the wrong side.
        _is_partial_name_echo = (
            val_a.strip().lower() in (name_a.strip().lower(), name_b.strip().lower())
            or val_b.strip().lower() in (name_a.strip().lower(), name_b.strip().lower())
        )
        # Confirmed live: a STEP 1 row inventing a figure ("$X"/"$Y", or a
        # real-looking amount) that never appears in the ANSWER — the
        # prompt explicitly limits invented numbers to the Example row.
        # Drop the whole row rather than just the number, since a row that
        # invented one fact can't be trusted to have restructured the rest
        # of itself correctly either.
        _is_hallucinated_figure_row = label.strip().lower() != "example" and any(
            d.replace(",", "") not in _answer_digit_tokens
            for d in _TABLE_ROW_DIGIT_RE.findall(val_a) + _TABLE_ROW_DIGIT_RE.findall(val_b)
        )
        # Confirmed live: with a richer, multi-attribute ANSWER (more
        # source material after the retrieval-balance fix in
        # [[project_named_pair_retrieval_filter_gap]]), the model
        # sometimes repeats STEP 2's "add an Example row" after EVERY
        # STEP 1 row instead of once at the end — 4 separate rows all
        # labeled "Example" instead of the single row the prompt asks
        # for. Originally caught only for "example" specifically; widened
        # (2026-09-03) to any label after the same failure showed up on
        # "Definition" too — a source ANSWER with a definitional-sounding
        # sentence elsewhere besides its opening (e.g. a later summary
        # restating what each item is) gets its own row, and the model's
        # free-form labeling of a definitional row naturally lands on
        # "Definition" again, producing two rows with the same label
        # instead of one being folded into the first. No label in this
        # table is meant to repeat — Definition and Example are each
        # explicitly singular by the prompt's own instructions, and every
        # STEP 1 attribute row is supposed to be its own distinct point —
        # so a repeated label is always a formatting bug, never a
        # legitimate second row. Keep only the first occurrence.
        _is_duplicate_label = label.strip().lower() in _seen_row_labels
        # Confirmed live: the Example row is explicitly allowed to invent a
        # generic illustrative scenario ("$1,000 medical bill") that isn't
        # drawn from the ANSWER — exempted for the same reason the
        # hallucination-figure check above exempts it (STEP 2's content
        # isn't required to come from — or be scoped to — the ANSWER).
        #
        # Confirmed live (2026-08-25): "What is the difference between term
        # insurance and whole life insurance?" — the mandatory Definition
        # row got silently dropped every time. Root cause: _ANCHOR_TYPE_RE
        # has both "life" and "whole\s*life" as separate alternatives, so
        # _expected_anchor_types for this pair is {"term", "whole life"} —
        # but a genuinely correct Definition row explaining "Term insurance
        # is a type of LIFE INSURANCE that..." mentions the bare parent
        # category "life", not the compound "whole life", which isn't IN
        # _expected_anchor_types and got flagged as contamination. Term
        # insurance and whole life insurance are both named sub-types of
        # life insurance — mentioning that shared parent category while
        # defining either one is correct content, not a different product
        # leaking in, the same "named variant of the same broader thing"
        # distinction already generalized into this file's main answer
        # prompts (see DETAILED_GROUNDED_PROMPT rule 9d). An anchor type
        # that's a whole-word SUBSTRING of one of the expected types (like
        # "life" inside "whole life") is that type's own parent category,
        # not a genuinely different, unrelated product — exclude it from
        # the contamination set rather than flagging it.
        _flagged_anchor_types = (_strong_anchor_types_in(val_a) | _strong_anchor_types_in(val_b)) - _expected_anchor_types
        _flagged_anchor_types = {
            t for t in _flagged_anchor_types
            if not any(re.search(rf"\b{re.escape(t)}\b", e) for e in _expected_anchor_types)
        }
        _is_cross_topic_contaminated = label.strip().lower() != "example" and bool(_flagged_anchor_types)
        if (
            not label
            or _TABLE_ROW_SKIP_LABEL_RE.match(label)
            or (not val_a and not val_b)
            or _TABLE_VALUE_ECHO_RE.search(val_a) or _TABLE_VALUE_ECHO_RE.search(val_b)
            or _is_name_echo_row
            or _is_blank_row
            or _is_item_name_label_row
            or _is_partial_name_echo
            or _is_hallucinated_figure_row
            or _is_duplicate_label
            or _is_cross_topic_contaminated
        ):
            continue
        rows.append({"label": label, "values": [val_a or "Not specified", val_b or "Not specified"]})
        _seen_row_labels.add(label.strip().lower())

    # STEP 1 asks for the Definition row first, but prompt-only compliance
    # on row ORDER (as opposed to row presence) has proven unreliable
    # elsewhere in this function — cheap and safe to just move it to the
    # front here rather than trust generation order.
    _def_idx = next((i for i, r in enumerate(rows) if r["label"].strip().lower() == "definition"), None)
    if _def_idx is not None and _def_idx != 0:
        rows.insert(0, rows.pop(_def_idx))

    # Confirmed live (2026-08-19): despite the prompt's explicit "the FIRST
    # value column is always {name_a}... even if the ANSWER's sentence
    # about {name_a} happens to come later in the text" instruction, the
    # reformat call still sometimes transcribes values in the ANSWER's own
    # narrative order rather than by column identity — e.g. the ANSWER's
    # prose discusses Premium first then Deductible, and despite columns
    # being ["Deductible", "Premium"], every row's values[0] ends up
    # describing Premium and values[1] ends up describing Deductible. A
    # smaller model's positional bias winning out over an explicit identity
    # instruction, not a prompt-wording gap — the Definition row's own
    # mandatory "what {name_a} actually is" / "what {name_b} actually is"
    # shape makes it a reliable, cheap diagnostic: a real Definition row
    # opens with "A <name> is..."/"<name> is...", so checking which name
    # each side's value actually opens with catches a whole-table swap
    # directly, rather than trying to out-word the prompt further.
    def _value_is_about(value: str, name: str) -> bool:
        return bool(re.match(rf"^(?:a|an|the)?\s*{re.escape(name.strip().lower())}\b", value.strip().lower()))

    _def_row = rows[0] if rows and rows[0]["label"].strip().lower() == "definition" else None
    if _def_row is not None:
        _val_a, _val_b = _def_row["values"]
        _a_is_b = _value_is_about(_val_a, name_b)
        _b_is_a = _value_is_about(_val_b, name_a)
        _a_is_a = _value_is_about(_val_a, name_a)
        _b_is_b = _value_is_about(_val_b, name_b)
        if _a_is_b and _b_is_a and not _a_is_a and not _b_is_b:
            logger.info(
                "[ask_stream] comparison-table reformat swapped %s/%s — Definition row's "
                "values[0] described %r, values[1] described %r; reversing every row's values",
                name_a, name_b, name_b, name_a,
            )
            for r in rows:
                r["values"] = [r["values"][1], r["values"][0]]

    if len(rows) < 2:
        logger.debug(
            "[ask_stream] comparison-table reformat produced %d usable row(s), keeping prose", len(rows)
        )
        return None

    # Confirmed live, two different shapes of the same underlying failure:
    # (1) the reformat call collapses an ENTIRE column — every non-Example
    # row says "Not specified" on the SAME side; (2) subtler, seen after
    # the retrieval-balance fix in [[project_named_pair_retrieval_filter_gap]]
    # gave the model richer material about BOTH items — one-sidedness that
    # ALTERNATES per row ("Starting Line": {name_a} filled/{name_b} blank,
    # "Safety Net": {name_b} filled/{name_a} blank), which looks
    # superficially balanced in aggregate (each item gets a row) but still
    # never lets a reader compare both items on the SAME attribute in a
    # single row — the exact defect the round-2 row-per-item fix targeted,
    # just with metaphor labels instead of the item's own name, so
    # _is_item_name_label_row never catches it. Individual rows pass every
    # per-row check above since each one is internally well-formed; only
    # visible in aggregate. Confirmed this is a failure mode and not
    # genuine asymmetry by observing the SAME model correctly balance both
    # columns for the exact same two items in other calls — so treat 100%
    # of non-Example rows being one-sided (regardless of WHICH side, or
    # whether it's the same side every time) as an unreliable reformat and
    # fall back to prose, same as the too-few-rows case above. A MINORITY
    # of one-sided rows mixed with genuinely balanced ones is left alone —
    # that's a normal, honest reflection of an attribute only one side has
    # a stated fact for, not a failure.
    _non_example_rows = [r for r in rows if r["label"].strip().lower() != "example"]
    _one_sided_rows = sum(
        1 for r in _non_example_rows
        if r["values"][0] == "Not specified" or r["values"][1] == "Not specified"
    )
    if _non_example_rows and _one_sided_rows == len(_non_example_rows):
        logger.debug(
            "[ask_stream] comparison-table reformat produced %d/%d one-sided non-Example "
            "row(s) (every row missing one side), keeping prose",
            _one_sided_rows, len(_non_example_rows),
        )
        return None

    intro = f"Here's how {name_a} and {name_b} compare:"
    table = {"columns": [name_a, name_b], "rows": rows}
    return intro, table


# Confirmed live: the model sometimes hedges rather than actually
# explaining a shortchanged item ("Form A is the other standard form but
# isn't detailed here.") — a sentence that's just as LONG as a real
# explanation, so length alone doesn't separate them. Anything matching
# this is never counted as real coverage, regardless of length.
_HEDGE_RE = re.compile(
    r"\b(?:isn'?t|is\s+not|not)\s+(?:detailed|covered|explained|discussed|specified)\s+here\b|"
    r"\bno\s+(?:further|more)\s+details?\b",
    re.IGNORECASE,
)


def _strip_generic_joint_mention(text: str, name_a: str, name_b: str) -> str:
    """Drops any sentence of the shape "X and Y are types/kinds/forms of
    ..." — the generic scene-setter every one of these answers opens
    with, restating the question rather than saying anything specific
    about either name. Left in, it makes both names look like they have
    "real" non-trailing coverage even when one is never elaborated on
    anywhere else, defeating _is_comparison_trailing_only's whole point.
    Detection-only — never touches the actual returned answer text."""
    a, b = re.escape(name_a), re.escape(name_b)
    generic_re = re.compile(rf"(?:{a}\s+and\s+{b}|{b}\s+and\s+{a})\s+are\b[^.!?]*[.!?]", re.IGNORECASE)
    return generic_re.sub(" ", text)


def _is_comparison_trailing_only(text: str, name: str) -> bool:
    """True if EVERY occurrence of `name` in `text` sits inside a
    "compared to X / than X / unlike X / versus X" trailing clause —
    i.e. `name` is only ever the OBJECT of a comparison, never its own
    subject with real elaboration. Confirmed live: a single sentence can
    fold both named items together ("Form B, also known as the
    Comprehensive Policy, offers more coverage compared to Form A, which
    is typically a basic policy.") — Form B gets a real appositive
    description, Form A gets a throwaway relative clause tacked onto the
    comparison. Neither name gets an EXCLUSIVE sentence here (both
    _sentence_chars_mentioning counts come back 0, since the one sentence
    mentions both), which would otherwise look like "can't tell, skip" —
    this catches that specific shape instead of missing it."""
    name_l = name.lower()
    text_l = text.lower()
    positions = [mm.start() for mm in re.finditer(re.escape(name_l), text_l)]
    if not positions:
        return False
    trailing_re = re.compile(r"(?:compared\s+to|than|unlike|versus|vs\.?)\s+" + re.escape(name_l))
    trailing_positions = {mm.start() + mm.group().lower().rindex(name_l) for mm in trailing_re.finditer(text_l)}
    return all(p in trailing_positions for p in positions)


def _sentence_chars_mentioning(text: str, name: str, other_name: str) -> int:
    """Total character count of every sentence in `text` where `name`
    appears near the START (subject position) AND `other_name` does NOT
    appear anywhere in it — a proxy for "this sentence is exclusively
    ABOUT `name`", not a shared intro sentence naming both (which would
    otherwise inflate both sides' counts equally and mask a real
    imbalance) or a passing mention in a sentence really about the other
    item ("Form B ... compared to Form A" is about Form B; a naive
    "mentions anywhere" check would wrongly credit Form A with that whole
    sentence too). Hedge sentences (see _HEDGE_RE) never count, however
    long they are."""
    sentences = re.split(r"(?<=[.!?])(?<!\d\.)\s+", text)
    name_l, other_l = name.lower(), other_name.lower()
    total = 0
    for s in sentences:
        s_l = s.lower()
        idx = s_l.find(name_l)
        if 0 <= idx <= 25 and other_l not in s_l and not _HEDGE_RE.search(s):
            total += len(s)
    return total


async def _enforce_named_pair_depth(query: str, context_text: str, answer_text: str) -> Optional[str]:
    """
    When the query (or, failing that, the answer itself — see
    _NAMED_PAIR_ANSWER_PATTERN) names two specific things — any casing,
    "Form A and Form B" or "health insurance and term insurance" alike —
    and the answer's coverage of one is starved relative to the other,
    makes ONE LLM call to APPEND a real explanation of the shortchanged
    item — grounded ONLY in `context_text` (the same
    retrieved KNOWLEDGE BASE the main answer was generated from), additive
    -only (never edits or removes the existing answer, same safety
    discipline as _correct_rider_misattribution — appending can't produce
    the "So, but don't worry..." orphaned-fragment failure mode a
    delete/splice approach already caused once in this codebase).

    Returns None (no correction) when: neither the query nor the answer
    names a pair, the answer is a refusal message, too short to judge,
    both named items already got comparable coverage, or the LLM call
    fails, times out, or the KNOWLEDGE BASE genuinely has nothing more to
    say about the shortchanged item (explicitly allowed to say so — this
    never invents content, see the prompt's own grounding rule below).
    """
    pair = (
        _extract_named_pair(query, _NAMED_PAIR_QUERY_PATTERNS)
        or _extract_named_pair(answer_text, [_NAMED_PAIR_ANSWER_PATTERN])
    )
    if not pair:
        return None
    name_a, name_b = pair
    if answer_text.strip().lower().startswith("hmm, i don't have"):
        return None
    if len(answer_text) < 80:
        return None

    chars_a = _sentence_chars_mentioning(answer_text, name_a, name_b)
    chars_b = _sentence_chars_mentioning(answer_text, name_b, name_a)
    starved_name: Optional[str] = None
    if chars_a == 0 and chars_b == 0:
        # Neither name has its OWN exclusive sentence — could genuinely be
        # unrelated to this failure mode, or could be exactly the shape
        # where both names got folded into one shared sentence with one
        # getting real elaboration and the other reduced to a "compared
        # to X" trailing clause. Only the latter is actionable here.
        _stripped = _strip_generic_joint_mention(answer_text, name_a, name_b)
        a_trailing = _is_comparison_trailing_only(_stripped, name_a)
        b_trailing = _is_comparison_trailing_only(_stripped, name_b)
        if a_trailing and not b_trailing:
            starved_name = name_a
        elif b_trailing and not a_trailing:
            starved_name = name_b
        else:
            return None  # both or neither trailing-only — can't tell, skip
    else:
        lo, hi = sorted((chars_a, chars_b))
        if hi > 0 and lo / hi >= 0.5:
            return None  # already comparably balanced
        starved_name = name_a if chars_a < chars_b else name_b
    logger.debug(
        "[ask_stream] named-pair depth: a=%r(%d) b=%r(%d) starved=%r",
        name_a, chars_a, name_b, chars_b, starved_name,
    )

    prompt = f"""The KNOWLEDGE BASE below is what an answer about "{name_a}" and "{name_b}"
was generated from. The EXISTING ANSWER explains "{starved_name}" far less than the other
one. Write 1-2 sentences that explain what "{starved_name}" actually is/covers/means,
using ONLY facts stated in the KNOWLEDGE BASE below — never external knowledge, never a
guess. If the KNOWLEDGE BASE genuinely says nothing more about "{starved_name}" beyond
what the EXISTING ANSWER already says, reply with exactly the single word "NONE".

KNOWLEDGE BASE:
{context_text[:6000]}

EXISTING ANSWER:
{answer_text}

Reply with ONLY the 1-2 new sentences (or "NONE") — no lead-in, no commentary."""

    try:
        raw = await _backend_completion(prompt, max_tokens=200, timeout=35, temperature=0)
    except Exception as exc:
        logger.debug("[ask_stream] named-pair depth call failed: %s", exc)
        return None
    if not raw:
        return None
    addition = raw.strip()
    if not addition or addition.upper() == "NONE" or len(addition) > 600:
        return None
    if addition[-1] not in ".!?":
        addition += "."

    sign_off_re = re.compile(
        r"(Let me know if you want more details! 😊|Hope that clears it up! Let me know if you want me to dig into any part of this\. 😊)\s*$"
    )
    sm = sign_off_re.search(answer_text)
    if sm:
        return answer_text[:sm.start()].rstrip() + " " + addition + " " + answer_text[sm.start():]
    return answer_text.rstrip() + " " + addition


_REQUIREMENT_QUESTION_RE = re.compile(
    r"\b(should i|do i need|is it required|do i have to|must i|"
    r"need to (?:buy|get|have|carry)|is .{0,40} required)\b",
    re.IGNORECASE,
)


async def _enforce_requirement_type_named(
    query: str, context_text: str, answer_text: str
) -> Optional[str]:
    """
    Some KNOWLEDGE BASE chunks tie an insurance requirement to a SPECIFIC
    named process or document (a visa, permit, license, certificate,
    declaration, ...) required by a named place or authority — not just a
    generic "minimum coverage" statement. Confirmed live and reproducible
    on one real case (a travel-insurance chunk ties its coverage minimum
    to a Schengen-area VISA application) that fresh, uncached brief-mode
    answers named the specific requirement type ("visa") only about half
    the time — the rest settled for a generic "meets a minimum
    requirement for the Schengen Area" that drops which specific process
    the requirement is actually for, even though the full chunk text
    (confirmed short enough to skip context-compression's sentence
    trimming entirely, so nothing was lost in retrieval) reaches the
    model intact every time. This is ordinary LLM summarization variance
    — when compressing several source facts into a short answer, a
    secondary qualifying noun sometimes loses out to the primary place
    name — not something specific to Schengen's wording, so this check
    is driven entirely by whatever CONTEXT/ANSWER text is actually in
    front of it each call, with no hardcoded place or requirement-type
    vocabulary anywhere in the prompt below. It applies unchanged to any
    future KNOWLEDGE BASE document naming a different place and a
    different specific requirement type.

    Only runs for "should I"/"do I need"-shaped questions — the same
    question shape the prompt's own STOP-checkpoint rule about this
    targets — so this stays a bounded, occasional extra call, not one
    added to every reply.

    Returns None (no correction) when the query isn't this shape, the
    answer is a refusal or too short, the LLM finds no such specific
    named requirement in the CONTEXT, the answer already names it, the
    returned phrase doesn't share any real word with the CONTEXT (a
    lightweight grounding sanity check — this never invents a new fact,
    only surfaces one already present in the CONTEXT), or the call
    fails/times out.

    Extended (same shape, two questions in one call rather than a
    second function) to also catch a related but distinct gap: even
    once the requirement TYPE is named, a place-specific question
    deserves the CONTEXT's actual SCOPE specifics (how long it stays
    valid, where it applies, what it must cover, when it's checked),
    not a bare "meets the requirement" sentence — confirmed live this
    is a real, separate reliability gap even after the requirement-type
    fix above: fresh, uncached runs of the same Schengen case sometimes
    named "visa" correctly but still gave zero scope detail (validity/
    duration/repatriation all present in the CONTEXT, none surfaced).
    Runs as two separate, single-purpose LLM calls in parallel (not one
    combined call asking both questions) — confirmed live a combined
    call reliably under-delivered on one line or the other, a known LLM
    tendency to under-effort on a multi-part ask; splitting doubles the
    call count but keeps latency roughly the same since both run
    concurrently via asyncio.gather.
    """
    if not _REQUIREMENT_QUESTION_RE.search(query or ""):
        return None
    if not answer_text or answer_text.strip().lower().startswith("hmm, i don't have"):
        return None
    if len(answer_text) < 40:
        return None

    _type_prompt = f"""The KNOWLEDGE BASE below may tie an insurance requirement to a
SPECIFIC named process or document (a visa, permit, license, certificate,
authorization, declaration, or similar) required by a named place or
authority — not just a generic minimum-coverage statement.

Read the KNOWLEDGE BASE and the EXISTING ANSWER below. If the KNOWLEDGE BASE
names such a specific process/document, but the EXISTING ANSWER only
describes it generically (e.g. "meets a minimum requirement", "required
coverage") without ever naming what specific process/document it actually
is, reply with ONLY that missing name, exactly as the KNOWLEDGE BASE states
it, in 2-6 words. Right shape (never reuse this wording — it is a
deliberately unrelated, non-insurance example only to show the SHAPE of a
correct reply, two or three words naming a specific document tied to a
place or authority): "a fishing license". Take the actual name only from
the KNOWLEDGE BASE text below, never from this example — if the KNOWLEDGE
BASE names something else entirely (a permit, a certificate, anything),
reply with THAT, in its own words, not this placeholder.

If the EXISTING ANSWER already names the specific process/document, or the
KNOWLEDGE BASE does not tie the requirement to any such specific named
process/document, reply with exactly the single word "NONE".

KNOWLEDGE BASE:
{context_text[:4000]}

EXISTING ANSWER:
{answer_text}

Reply with ONLY the missing name (or "NONE") — no lead-in, no commentary."""

    _scope_prompt = f"""The KNOWLEDGE BASE below may state specific SCOPE details about an
insurance requirement — how long it must stay valid, where it must apply,
what it must cover, or when it gets checked — beyond just a generic
minimum-coverage statement.

Read the KNOWLEDGE BASE and the EXISTING ANSWER below. If the KNOWLEDGE BASE
states a scope specific that the EXISTING ANSWER leaves out entirely, reply
with ONLY the single most important missing detail, in one short clause
under 15 words, using the KNOWLEDGE BASE's own wording. Right shape (never
reuse this wording or these facts — it is a deliberately unrelated, non-
insurance example only to show the SHAPE of a correct reply): "valid for
the full calendar year regardless of when the fee was paid". Take the
actual detail only from the KNOWLEDGE BASE text below, never from this
example.

If the EXISTING ANSWER already covers the KNOWLEDGE BASE's scope specifics,
or the KNOWLEDGE BASE states none, reply with exactly the single word "NONE".

KNOWLEDGE BASE:
{context_text[:4000]}

EXISTING ANSWER:
{answer_text}

Reply with ONLY the missing detail (or "NONE") — no lead-in, no commentary."""

    # Two SEPARATE, single-purpose calls run in parallel, not one combined
    # call asking both questions — confirmed live this matters: the earlier
    # combined-question version reliably under-delivered on one line or the
    # other (missed the requirement type roughly as often as it missed
    # scope, in different runs), a known LLM tendency to under-effort on a
    # multi-part ask. Splitting doubles the call count but keeps latency
    # roughly the same as one call, since both run concurrently. Each gets
    # its own retry-on-empty, matching the same reasoning: this function
    # only ever ADDS grounded content, never edits or removes anything, so
    # a wasted retry costs one extra call, not correctness — confirmed
    # live, an isolated re-run of a case that flaked to NONE on live's
    # first attempt came back with a real, correctly-grounded addition.
    async def _single_check(prompt_text: str) -> Optional[str]:
        raw = None
        for _attempt in range(2):
            try:
                _candidate = await _backend_completion(prompt_text, max_tokens=40, timeout=12, temperature=0)
            except Exception as exc:
                logger.debug("[ask_stream] requirement-completeness check call failed (attempt %d): %s", _attempt + 1, exc)
                continue
            if not _candidate:
                continue
            raw = _candidate
            if _candidate.strip().upper() != "NONE":
                break
        return raw

    _type_raw, _scope_raw = await asyncio.gather(
        _single_check(_type_prompt), _single_check(_scope_prompt),
    )
    if not _type_raw and not _scope_raw:
        return None

    _kb_lower = context_text.lower()
    _answer_lower = answer_text.lower()
    _kb_joined = " ".join(re.findall(r"[a-z']{3,}", _kb_lower))

    def _grounded(phrase: str) -> bool:
        """True only if *phrase* shares a genuine multi-word span with the
        real KNOWLEDGE BASE text, not just scattered individual words.

        Confirmed live 2026-09-08: the old any()-over-individual-words
        version passed the scope check's raw reply straight through for a
        plain "should I buy travel insurance for Europe?" question with no
        real gap — the reply was "Valid for the full calendar year
        regardless of when the fee was paid", which is actually THIS SAME
        PROMPT'S OWN illustrative "right shape" example (explicitly banned
        above: "never reuse this wording"), not anything genuinely in the
        KB. Words like "valid"/"full"/"paid"/"when" trivially appear
        somewhere in almost any real insurance KB chunk by chance, so
        single-word overlap — even a majority of them — proves nothing
        about whether the phrase was actually DERIVED from this source.
        The prompt explicitly asks the model to answer "using the
        KNOWLEDGE BASE's own wording", so a genuine, correctly-grounded
        reply should share a real contiguous phrase with the source, not
        just its vocabulary. This is a general check, not a hardcoded
        blocklist of specific example strings — it catches any fabricated
        or leaked content the same way, including any future prompt's own
        example elsewhere in this file, without needing to know its exact
        wording in advance.
        """
        _words = re.findall(r"[a-z']{3,}", phrase.lower())
        if len(_words) < 3:
            return True
        for _n in (5, 4, 3):
            for _i in range(len(_words) - _n + 1):
                _gram = " ".join(_words[_i:_i + _n])
                if _gram in _kb_joined:
                    return True
        return False

    # Confirmed live: the LLM's own "does the EXISTING ANSWER already cover
    # this" judgment (asked directly in the prompt above) isn't reliable
    # enough on its own — it sometimes proposes a "missing" scope detail
    # that's already explicitly stated in the answer, just reworded
    # slightly ("covering the full length of your stay" already present,
    # then re-added as "covering the full length of the intended stay"),
    # producing an awkward, genuinely redundant duplicate sentence. A
    # cheap, deterministic word-overlap check against the answer's OWN
    # text (not the KNOWLEDGE BASE) catches this: if most of the
    # candidate addition's real words already appear literally in the
    # answer, treat it as already-covered and skip it, regardless of what
    # the LLM itself judged.
    def _already_in_answer(phrase: str) -> bool:
        _words = re.findall(r"[a-z]{4,}", phrase.lower())
        if not _words:
            return False
        _present = sum(1 for w in _words if w in _answer_lower)
        return (_present / len(_words)) >= 0.6

    missing_type = _type_raw.strip().strip('"').strip("'").rstrip(".") if _type_raw else ""
    missing_scope = _scope_raw.strip().strip('"').strip("'").rstrip(".") if _scope_raw else ""

    additions = []
    if (
        missing_type and missing_type.upper() != "NONE" and len(missing_type) <= 60
        and _grounded(missing_type) and not _already_in_answer(missing_type)
    ):
        additions.append(f"You'll need this specifically for {missing_type}.")
    elif missing_type and missing_type.upper() != "NONE":
        logger.debug(
            "[ask_stream] requirement-type-named check discarded type %r (ungrounded, oversized, or already present)",
            missing_type,
        )
    if (
        missing_scope and missing_scope.upper() != "NONE" and len(missing_scope) <= 150
        and _grounded(missing_scope) and not _already_in_answer(missing_scope)
    ):
        _clause = missing_scope[0].upper() + missing_scope[1:] if missing_scope else missing_scope
        additions.append(f"{_clause}.")
    elif missing_scope and missing_scope.upper() != "NONE":
        logger.debug(
            "[ask_stream] requirement-type-named check discarded scope detail %r (ungrounded, oversized, or already present)",
            missing_scope,
        )

    if not additions:
        return None

    addition = " ".join(additions)
    sign_off_re = re.compile(
        r"(Let me know if you want more details! 😊|Hope that clears it up! Let me know if you want me to dig into any part of this\. 😊)\s*$"
    )
    sm = sign_off_re.search(answer_text)
    if sm:
        return answer_text[:sm.start()].rstrip() + " " + addition + " " + answer_text[sm.start():]
    return answer_text.rstrip() + " " + addition


# ── Short follow-up detection & reformulation ──────────────────────────────
# When a user sends a very short message (e.g. "yes", "ok", "what about that")
# the raw text has no standalone semantic content for vector retrieval, causing
# near-zero similarity scores and a false human-handoff trigger.  If history is
# available we reformulate the query by merging with the last assistant turn.
_SHORT_FOLLOWUP_PHRASES = frozenset({
    "yes", "ok", "okay", "sure", "yeah", "yep", "yup",
    "tell me more", "go on", "continue", "and", "and?",
    "what about that", "what about it", "how about that", "how about it",
    "explain", "elaborate", "more", "really", "interesting",
    "i see", "got it", "understood", "right", "correct",
    "no", "nope", "nah", "not really",
    "why", "why not", "how", "how so",
    "can you elaborate", "can you explain",
})

# Referential/ordinal patterns that indicate a follow-up question even when
# the message is longer than 4 words (e.g. "explain about the second one more").
# These carry no standalone retrieval meaning — they refer back to items the
# assistant just listed — so they must trigger history-based reformulation.
_REFERENTIAL_PATTERN = re.compile(
    r"(?:"
    r"\b(first|second|third|fourth|fifth|last|other)\s+(one|option|type|item)\b|"
    r"\b(that|this)\s+one\b|"
    r"\bthe\s+other\s+one\b|"
    r"\bmore\s+about\s+(it|that|this)\b|"
    r"\bexplain\s+(more\s+)?(about\s+)?the\s+(first|second|third|fourth|fifth|last|other)\b|"
    r"\btell\s+me\s+more\s+about\s+the\s+(first|second|third|fourth|fifth|last|other)\b|"
    r"\belaborate\s+on\s+that\b|"
    r"\bexplain\s+more\b"
    r")"
)


def _is_short_followup(question: str) -> bool:
    """Detect if *question* is a short, low-content follow-up message.

    Returns ``True`` when the message is under ~4 words and either matches a
    known continuation phrase or is so short it cannot carry standalone
    retrieval meaning.  Also returns ``True`` for longer messages that match
    referential/ordinal patterns (e.g. "explain about the second one more")
    because those refer back to items the assistant just listed and have no
    standalone retrieval value.
    """
    q = question.strip().lower().strip("!.,?;:")
    words = q.split()

    # Referential/ordinal patterns — independent of word count.
    # These questions refer back to items the assistant just listed and have
    # no standalone retrieval meaning (e.g. "explain about the second one").
    if _REFERENTIAL_PATTERN.search(q):
        return True

    if len(words) > 4:
        return False
    # Exact match against known continuation phrases
    if q in _SHORT_FOLLOWUP_PHRASES:
        return True
    # Any 1-2 word message that isn't a normal-length question qualifies
    if len(words) <= 2:
        return True
    return False


# A flat history string is "User: ...\nAssistant: ...\nUser: ...\nAssistant: ..."
# — but a single turn's own content can contain internal newlines (e.g. a
# numbered-list answer, one "\n" per point). A naive history.split("\n") to
# grab "the last N lines" fragments that ONE long turn into many pieces, so
# the window can end up holding only the tail of a numbered list (points
# 6-8) while dropping the earlier points (1-5) entirely — and a follow-up
# asking about "point 2" then has no way to know what point 2 actually was,
# since it was never in the history it saw at all (this exact regression
# previously shipped and was fixed once already — see git history on this
# function — before being silently reintroduced by an unrelated merge).
# Splitting only at newlines immediately followed by "User:"/"Assistant:"
# keeps each turn whole no matter how many lines its own content spans.
_HISTORY_TURN_BOUNDARY_RE = re.compile(r'\n(?=(?:User|Assistant):\s)')


def _split_history_turns(history: str) -> list[str]:
    """Split a flat ``"User: ...\\nAssistant: ..."`` history string into whole
    turns (see module note above), not naive newline-delimited lines — so
    callers can slice the last N turns without cutting a multi-line response
    in half.
    """
    return [t.strip() for t in _HISTORY_TURN_BOUNDARY_RE.split(history.strip()) if t.strip()]


def _last_user_question(history: str) -> str:
    """Text of the most recent USER turn in *history*, "User: " prefix stripped."""
    for turn in reversed(_split_history_turns(history)):
        if turn.startswith("User:"):
            return turn[len("User:"):].strip()
    return ""


def _history_last_assistant_turn(history: str) -> str:
    """Text of the most recent ASSISTANT turn in *history*, prefix stripped.

    Named distinctly from the unrelated local variable `_last_assistant_turn`
    already used inside ask_stream() — Python's local-scope rules mean a
    same-named local variable anywhere in that function shadows a module-
    level function of the same name for the function's entire body, which
    broke this call with `TypeError: 'str' object is not callable` when
    first written as `_last_assistant_turn`.
    """
    for turn in reversed(_split_history_turns(history)):
        if turn.startswith("Assistant:"):
            return turn[len("Assistant:"):].strip()
    return ""


def _split_history_turn_pairs(history: str) -> list:
    """Pairs up _split_history_turns()'s flat turn list into chronological
    (user_text, assistant_text) tuples, "User:"/"Assistant:" prefixes
    stripped. Conversation history is always saved as strict [user,
    assistant] alternating pairs (see api.py's _save_conversation_history),
    so this just walks the flat list two at a time — skipping (not mis-
    pairing) a turn that doesn't match the expected User-then-Assistant
    alternation, as cheap insurance against malformed history rather than
    a load-bearing check.
    """
    turns = _split_history_turns(history)
    pairs = []
    i = 0
    while i < len(turns) - 1:
        if turns[i].startswith("User:") and turns[i + 1].startswith("Assistant:"):
            pairs.append((turns[i][len("User:"):].strip(), turns[i + 1][len("Assistant:"):].strip()))
            i += 2
        else:
            i += 1
    return pairs


# Similarity-comparison target text per history turn — capped short
# deliberately, same reasoning as _REFORMULATE_TOPIC_SNIPPET_CHARS below:
# a full, detailed answer routinely mentions multiple insurance types in
# passing (e.g. explaining term insurance while contrasting it against
# whole life), and embedding the WHOLE answer lets an incidental mention
# dominate the vector — the same "long, multi-topic content drowns out the
# real subject" failure already confirmed live twice in this file (see
# _reformulate_query's own 3-turn-window regression comment below, and
# _reformulate_with_history's policy-document-contents comment). Sized a
# little more generously than that constant since a similarity comparison
# tolerates extra context better than a literal retrieval string does.
_TURN_SIM_SNIPPET_CHARS = 200

# Detection-gate floor: "is this question plausibly continuing history AT
# ALL" — checked against the BEST-scoring turn including the most recent
# one. Deliberately looser than the override thresholds below: a false
# positive here just costs one extra, cheap LLM call (_reformulate_query's
# own prompt already handles an already-self-contained question by echoing
# it back unchanged) — the same asymmetric-cost tradeoff _is_likely_
# followup's existing 12-word gate already makes elsewhere in this file.
_FOLLOWUP_SIM_GATE = 0.42

# Override floor + margin: "is an EARLIER turn clearly, not just
# marginally, the better match than the most recent one." Both required
# together specifically to fail the documented takaful-vs-term-insurance
# regression (see _reformulate_query's comment) — a more "distinctive"-
# sounding earlier topic scoring only slightly higher than the true
# current topic must not win. An override is not cheap like a detection
# false-positive: it substitutes the wrong turn's content into the
# reformulation input, so this pair is intentionally stricter.
_TURN_OVERRIDE_MIN_SIM = 0.50
_TURN_OVERRIDE_MARGIN = 0.08


def _turn_similarity_text(user_text: str, assistant_text: str) -> str:
    return f"{user_text} {assistant_text[:_TURN_SIM_SNIPPET_CHARS]}".strip()


def _rank_history_turns_by_similarity(question: str, history: str) -> Optional[dict]:
    """Code-based (embedding, not LLM) ranking of which retained history
    turn *question* most resembles — same pattern PGF/SRG already use
    elsewhere in this file (_get_shared_embed_model + cosine similarity via
    np.dot) for "which of several candidates does X relate to" problems,
    applied here to conversation turns instead of retrieved chunks.

    Returns None when there is no history at all, or on any embedding
    failure, so callers degrade to today's exact behavior with zero
    special-casing needed.

    Computes a real score even with only 1 retained turn-pair (2026-09-09,
    fixed from an earlier "< 2 pairs -> None" gate). That gate was correct
    for _select_followup_anchor_turn's own job — disambiguating WHICH of
    several past turns to anchor on has nothing to disambiguate with only
    one candidate — but this same ranking also feeds
    _followup_similarity_gate, whose job is different: "is this even a
    follow-up at all." For THAT job, a 1-turn history is the single most
    common real case (a session's very first follow-up message), and
    returning None there means the gate could never fire for it —
    confirmed live: "Does treatment received while abroad get paid for
    too?" right after a health-coverage turn had no pronoun and no listed
    _GENERIC_PROCESS_RE word, ranked=None (only 1 pair existed), the gate
    never got a real score to check, and the question was answered with
    wrong-domain travel-insurance content. Safe to loosen: with exactly 1
    pair, best_idx and most_recent_idx are both necessarily 0, so
    _select_followup_anchor_turn's own `best_idx == most_recent_idx`
    check already no-ops correctly on its own — this change only ever
    gives _followup_similarity_gate a real score to work with, it cannot
    change anchor-turn overriding behavior at all.
    """
    pairs = _split_history_turn_pairs(history)
    if not pairs:
        return None
    try:
        candidates = [_turn_similarity_text(u, a) for u, a in pairs]
        embed_model = _get_shared_embed_model(EMBED_MODEL_NAME)
        vecs = embed_model.encode(candidates + [question], normalize_embeddings=True)
        turn_vecs, q_vec = vecs[:-1], vecs[-1]
        scores = [float(np.dot(q_vec, tv)) for tv in turn_vecs]
        best_idx = max(range(len(scores)), key=lambda i: scores[i])
        return {
            "pairs": pairs, "scores": scores, "question": question,
            "best_idx": best_idx, "most_recent_idx": len(pairs) - 1,
        }
    except Exception as exc:
        logger.debug("[TURN-SELECT] similarity ranking failed, skipping: %s", exc)
        return None


def _followup_similarity_gate(ranked: Optional[dict]) -> bool:
    """True if *question* (already ranked into *ranked*) is similar enough
    to ANY retained turn to count as plausibly continuing the conversation
    — the detection-side signal, independent of _is_likely_followup's own
    keyword/pattern gate. Exists specifically for indirect/scenario-phrased
    follow-ups about the MOST RECENT turn that carry no pronoun or generic
    follow-up keyword at all (e.g. "what if it happened while commuting to
    work instead?") — _select_followup_anchor_turn below correctly declines
    to override for exactly this case (best_idx == most_recent_idx), so
    detecting it at all has to happen here, not there.
    """
    return ranked is not None and max(ranked["scores"]) >= _FOLLOWUP_SIM_GATE


def _select_followup_anchor_turn(ranked: Optional[dict]) -> Optional[tuple]:
    """Decision function over an already-computed _rank_history_turns_by_
    similarity() result — never recomputes. Returns the (user, assistant)
    turn to anchor reformulation on INSTEAD of the most recent turn, only
    when ALL of: the CURRENT question carries real topic content of its
    own, the best-scoring turn isn't the most recent one, its score clears
    an absolute floor on its own merits, AND it beats the most-recent
    turn's own score by a real margin. Returns None (keep today's default,
    most-recent-turn behavior) otherwise — including the common case where
    the most recent turn is itself the best match.

    Confirmed live 2026-09-07: a content-free follow-up ("How to claim
    it?" after a motor-insurance claims turn, then again after an
    unrelated marine-insurance turn) scored 0.701 against the OLDER motor
    turn vs only 0.540 against the actual most-recent marine turn — a
    0.161 margin, comfortably clearing the threshold below — and
    incorrectly overrode recency. Not because the phrasing coincidentally
    repeated (it's a routine, generic follow-up shape a user can ask
    about any topic), but because the similarity comparison is between
    the CURRENT QUESTION and each turn's (question + answer-snippet)
    text: "claim" is a real, repeated signal throughout the motor turn's
    own claims-process answer, and genuinely absent from the marine
    turn's purely definitional answer — so a bare "claim" mention alone
    was treated as strong topical evidence, when the word carries no
    entity/topic information at all ("claim" is already in
    _QUERY_STOP_WORDS for exactly this domain-generic reason). A follow-
    up whose own text has no real content word to begin with has no
    legitimate basis to point anywhere other than the most recent turn —
    "it" resolves by recency, not by which past turn happens to share
    incidental vocabulary with the CURRENT phrasing. A genuinely
    content-bearing topic-jump ("what about takaful instead?") still
    reaches this check fine, since "takaful" survives the same filter.
    """
    if ranked is None:
        return None
    if not _extract_topic_terms(ranked.get("question", "")):
        return None
    best_idx, most_recent_idx = ranked["best_idx"], ranked["most_recent_idx"]
    if best_idx == most_recent_idx:
        return None
    scores = ranked["scores"]
    if scores[best_idx] < _TURN_OVERRIDE_MIN_SIM:
        return None
    if scores[best_idx] - scores[most_recent_idx] < _TURN_OVERRIDE_MARGIN:
        return None
    logger.info(
        "[TURN-SELECT] override: anchoring on turn %d (score=%.3f) over most-recent turn %d "
        "(score=%.3f, margin=%.3f) — %r",
        best_idx, scores[best_idx], most_recent_idx, scores[most_recent_idx],
        scores[best_idx] - scores[most_recent_idx], ranked["pairs"][best_idx][0][:80],
    )
    return ranked["pairs"][best_idx]


# A generic "elaborate on whatever we were just discussing" follow-up, as
# opposed to a follow-up that names its own specific new content ("how do I
# claim it?", "is it tax deductible?"). Only THIS class of follow-up is
# ambiguous about *which part* of a compound prior question the user wants
# more on — a substantive follow-up already says what it's asking about.
_ELABORATION_FOLLOWUP_RE = re.compile(
    r"\b(explain.{0,15}in detail|more detail|tell me more|elaborate|"
    r"go (?:into|in)\s+detail|detailed explanation|explain (?:it|that|this)\b)",
    re.IGNORECASE,
)

# Matches messages that START WITH one of these phrases — not a full-string
# match — because the "Both" clarify chip's own label ("Both — give me the
# full picture", set below in _CLARIFY_OPTIONS suffix) is sent verbatim as
# the user's message when clicked. An exact full-phrase match (the original
# design) missed that: "Both — give me the full picture" starts with "both"
# but has trailing text a `$`-anchored pattern rejects. Still narrow enough
# not to false-positive on a genuine question — real questions don't
# normally open with "both"/"everything" as their first word.
_BOTH_REPLY_RE = re.compile(
    r"^\s*(both\b|all of them\b|everything\b|"
    r"(?:give|answer|tell)\s+me\s+both\b|i\s+want\s+both\b)",
    re.IGNORECASE,
)

# QA-confirmed 2026-09-07: a bare "yes" typed right after the model's OWN
# generic sign-off ("Let me know if you want more details! 😊") got caught
# by ask_stream's earlier "pure conversational reply, zero retrieval
# value" fast-path (_PURE_CONV) and answered with a canned "Great! Let me
# know if you have any other questions." instead of actually elaborating —
# that fast-path already special-cases an affirmative reply to a HANDOFF
# offer (_wants_handoff below) but had no equivalent for a "want more
# details" offer. Used together with the existing _HANDOFF_AFFIRM set
# (same short-affirmative vocabulary, already defined at that call site)
# to detect this case and route it into elaboration instead of a dead-end
# canned reply — only fires when the LAST ASSISTANT TURN actually ended
# with an offer, same sign-off phrase vocabulary _SIGNOFF_START_RE already
# uses elsewhere in this file, so a bare "yes" with no such offer ahead of
# it (e.g. answering an actual yes/no question) is untouched.
_SIGNOFF_OFFER_TAIL_RE = re.compile(
    r"(hope that|let me know|feel free|hang tight|glad to|dig into any part)",
    re.IGNORECASE,
)

# Distinctive enough to reliably identify our own clarification message in
# history (used to recover the two sub-questions for a "both" reply) without
# false-matching on an ordinary answer that happens to contain "both".
_CLARIFY_TEMPLATE = (
    'Happy to go deeper. Did you want more on "{q1}" or "{q2}"? '
    'Click one below, or just say "both" for the full picture on each.'
)
_CLARIFY_PARSE_RE = re.compile(r'more on "(.+?)" or "(.+?)"\?', re.IGNORECASE)

# Structural signal for "this question asks two separate things": a
# wh-word/auxiliary-verb question trigger, then "and", then ANOTHER such
# trigger within a short span — "What is X and what does X cover" has two
# (what...and what), "What is home and fire insurance" has only one (the
# "and" just joins two nouns). Deliberately NOT delegated to an LLM
# yes/no judgment call: tested live, the model classified "What is fire
# insurance and what does it covers?" as NO despite it being nearly
# identical to a worked YES example in the prompt — the same
# unreliable-at-binary-classification pattern seen elsewhere this session
# (e.g. the grounding-check prompt). A structural check is deterministic
# and, unlike the model, actually gets this right.
#
# Also includes a set of imperative "ask the assistant to do something"
# verbs (get/give/tell/show/explain/connect/help/provide/send/quote) so
# imperative-shaped compounds match too, not just question-shaped ones —
# confirmed live, "get me a quote for travel insurance and also tell me
# what documents I need for a visa" has zero wh-words/aux-verbs (neither
# clause is phrased as a question), so the original pattern missed it
# entirely: the whole query silently routed as one big travel-quote
# request and the visa-docs half was never answered at all. Same
# "and"-conjunction safeguard as above keeps single-topic imperatives
# ("give me the difference between home and fire insurance" — one
# trigger, "and" just joins two nouns) from false-triggering.
_COMPOUND_STRUCTURE_RE = re.compile(
    r"\b(what|how|when|where|why|does|do|did|is|are|was|were|can|could|will|would|should"
    r"|get|give|tell|show|explain|connect|help|provide|send|quote)\b"
    r".{2,60}?\band\b.{0,20}?"
    r"\b(what|how|when|where|why|does|do|did|is|are|was|were|can|could|will|would|should"
    r"|get|give|tell|show|explain|connect|help|provide|send|quote)\b",
    re.IGNORECASE,
)


async def _split_compound_question(question: str) -> Optional[tuple[str, str]]:
    """If *question* asks two genuinely separate, independently-answerable
    things (not just two nouns/topics mentioned together — "home and fire
    insurance" is one ask about two topics, not two asks), return the two
    as complete standalone questions. Otherwise return None.

    The IS-it-compound decision is the deterministic regex above, not the
    LLM — only the SPLIT (rephrasing into two clean standalone questions,
    resolving any pronoun) is delegated to the model, which this session
    has repeatedly shown to be reliable at rephrasing but not at binary
    classification.
    """
    if not _COMPOUND_STRUCTURE_RE.search(question):
        return None
    # Ends with a plain instruction, not a "continue after this label" cue —
    # tested live: a trailing "\nLine 1:" completion-style prompt confused
    # this chat model into echoing "Line 1:"/"Line 2:" back garbled into the
    # answer text itself ('What is fire insurance? Line 1: \n\nWhat does it
    # cover? Line 2:'). The plain-instruction style already proven reliable
    # for other multi-line LLM outputs in this file works cleanly here too.
    prompt = (
        f"Question: {question}\n\n"
        "Split this into its two separate questions. Resolve any pronoun so "
        "each question stands alone with no other context needed.\n"
        "Output only the two questions, one per line, no numbering, no labels, no explanation:"
    )
    raw = await _backend_completion(prompt, max_tokens=60, timeout=15.0)
    if not raw:
        return None
    lines = [ln.strip().strip('"') for ln in raw.strip().split("\n") if ln.strip()]
    lines = [re.sub(r"^(line\s*\d\s*:\s*|\d+[.)]\s*)", "", ln, flags=re.IGNORECASE) for ln in lines]
    if len(lines) == 1:
        # Confirmed live: the model sometimes ignores "one per line" and
        # produces a genuinely correct split anyway, just both questions
        # on the SAME line ("What is travel insurance? How can I file a
        # quotation to travel to India?") — this was silently discarded as
        # "not compound" and fell through to the old whole-query problem
        # this splitter exists to avoid in the first place. Recover by
        # splitting on a question-mark-then-space boundary; only accept it
        # if that yields exactly two non-empty pieces — three or more (a
        # genuinely garbled or triple-barreled output) still correctly
        # falls through to the len(lines) != 2 check below and returns
        # None, same conservative default as before.
        parts = [p.strip() for p in re.split(r"(?<=\?)\s+", lines[0]) if p.strip()]
        if len(parts) == 2:
            lines = parts
    if len(lines) != 2:
        return None
    # Confirmed live: for an imperative-shaped input ("get me a quote and
    # explain trip cancellation coverage"), the model correctly splits into
    # two clean, complete standalone asks but keeps them as directives
    # ("Get me a travel insurance quote.", "Explain trip cancellation
    # coverage.") rather than rephrasing into questions — there's nothing
    # to turn into a "?" when the original wasn't a question either. A
    # trailing "." is just as strong a completeness signal as "?" here; a
    # genuinely garbled/truncated line (missing terminal punctuation
    # entirely) still correctly falls through to the return None below.
    if lines[0][-1:] not in "?." or lines[1][-1:] not in "?.":
        return None
    return (lines[0], lines[1])


_REFORMULATE_TOPIC_SNIPPET_CHARS = 120


def _reformulate_with_history(question: str, history: str, selected_assistant: Optional[str] = None) -> str:
    """Merge a short follow-up with the last assistant turn from *history*.

    The returned string is used **only** for the retrieval query — the original
    *question* is still passed to the LLM prompt so the model answers what the
    user actually asked.

    Only the opening _REFORMULATE_TOPIC_SNIPPET_CHARS of the last assistant
    turn is used, not the full answer. This is the non-LLM fallback path —
    used when the primary _reformulate_query() call times out — so a long,
    detailed previous answer floods the retrieval query with unrelated detail
    and buries the follow-up's own content words. Confirmed live: after a
    multi-clause answer listing everything a policy document contains ("...the
    name and address of the insured, sum insured, period of insurance, risk
    covered, rate of premium, prescription of the subject matter..."), the
    follow-up "How can relatives be informed about the policy?" merged into a
    60+ word query where "relatives" was one word out of many — retrieval
    confidently matched the policy-document-CONTENTS topic (0.78 score)
    instead of anything about relatives. A short topic snippet still resolves
    pronouns against the established subject (the scenario this function
    exists for — see the call site's docstring) without drowning out a
    substantive follow-up's own words.

    selected_assistant (2026-09-07): an optional override from _select_
    followup_anchor_turn's embedding-similarity decision (see
    _reformulate_query's own matching parameter) — when the caller already
    decided the follow-up anchors on an EARLIER turn than the most recent
    one, this fallback must honor that same decision rather than silently
    reverting to the literal last assistant turn. None (the default) keeps
    today's exact lookup below unchanged.
    """
    last_assistant = selected_assistant
    if last_assistant is None:
        lines = history.strip().split("\n")
        for line in reversed(lines):
            if line.startswith("Assistant:"):
                last_assistant = line[len("Assistant:"):].strip()
                break
    if last_assistant:
        topic_snippet = last_assistant[:_REFORMULATE_TOPIC_SNIPPET_CHARS]
        # Confirmed live 2026-09-07: the hard character cut above lands
        # mid-word whenever the true boundary doesn't happen to fall on a
        # space ("...while you're traveling, as wel" for "...as well") —
        # trim back to the last complete word instead. The bare
        # `f"{topic_snippet} {question}"` join below it was ALSO gluing
        # the (already truncated) snippet directly onto the next question
        # with nothing but a space between them ("...as wel What are the
        # exclusions..."), which the downstream scenario-reformulation
        # step then read as one continuous, garbled framing instead of
        # two separate things — a real period as the join, not a space,
        # keeps them two distinct sentences the way they actually are.
        if len(last_assistant) > _REFORMULATE_TOPIC_SNIPPET_CHARS:
            topic_snippet = topic_snippet.rsplit(" ", 1)[0]
        topic_snippet = topic_snippet.rstrip(" ,;:")
        # A whole-word trim can still dangle on a connective with nothing
        # after it ("...traveling, as." for "...as well as...") — drop
        # trailing prepositions/conjunctions/articles the same truncation
        # can land on, same closed-class spirit as this file's other
        # dangling-word checks (e.g. _SUSPECT_LIST_MARKER_CORRUPTION_RE's
        # own word set), repeating since removing one can expose another
        # ("...covers medical and" -> drop "and" -> "...covers medical").
        _dangling_tail_words = frozenset({
            "a", "an", "the", "as", "and", "or", "but", "if", "of", "to",
            "in", "on", "at", "for", "with", "by", "from", "that", "which",
        })
        while True:
            _tail_match = re.search(r"\b(\w+)$", topic_snippet)
            if not _tail_match or _tail_match.group(1).lower() not in _dangling_tail_words:
                break
            topic_snippet = topic_snippet[:_tail_match.start()].rstrip(" ,;:")
        return f"{topic_snippet}. {question}" if topic_snippet else question
    return question


def _is_insurance_related(question: str) -> bool:
    """Return True if *question* is plausibly about insurance or a related domain.

    Uses simple keyword/pattern matching — no LLM call.  Returns False for
    clearly off-topic queries (history, geography, tech comparisons, etc.).
    """
    q = question.lower().strip()

    # If the question is VERY short (1-2 words), assume it could be
    # insurance-related (e.g. "tell me more", "what about that") — avoids
    # false-off-topic for short follow-ups.  3-word queries like "chatgpt
    # vs claude" are long enough to carry clear topic content, so they
    # proceed to pattern matching below.
    if len(q.split()) <= 2:
        return True

    # ── Insurance / finance domain indicators ──────────────────────────────
    # Check these BEFORE off-topic patterns: if the query contains any actual
    # insurance vocabulary, it IS insurance-related regardless of phrasing.
    # This prevents phrases like "difference between term and whole life"
    # or "what is the history of insurance" from being falsely flagged as
    # off-topic just because they contain a generic pattern like "difference
    # between" or "history of".
    _INSURANCE_INDICATORS = re.compile(
        r"\b("
        r"insurance|policy|premium|deductible|coverage|claim|claims|"
        r"insure|insured|insurer|underwriting|underwrite|"
        r"cover|covered|covers|covers? (?:for|against|up to|of|on)|"
        r"premiums|co-pay|copay|deductibles|"
        r"health|medical|hospital|surgery|prescription|medication|"
        r"vehicle|car|motor|auto|bike|two-wheeler|four-wheeler|"
        r"travel|trip|flight|baggage|luggage|cancellation|"
        r"life|term life|whole life|endowment|ulip|"
        r"home|house|property|rental|landlord|tenant|"
        r"accident|disability|critical illness|cancer|"
        r"liability|third.party|comprehensive|"
        r"limit|limits|sum insured|sum.assured|"
        r"maternity|dental|vision|"
        r"agent|broker|renewal|grace period|waiting period|"
        r"no.claim|ncb|bonus|"
        r"nominee|beneficiary|"
        r"claim (?:form|process|settlement|rejection|approval)|"
        r"cashless|reimbursement|"
        r"roadside assistance|towing|"
        r"personal accident|"
        r"retirement|pension|annuity|"
        r"finance|financial|investment|savings|"
        r"hdfc ergo|icici|bajaj|tata aig|reliance|"
        r"new india|oriental|national|united india|"
        r"irda|regulator|"
        r"cover note|certi.* of insurance|"
        r"aog|marine|cargo|"
        r"group insurance|corporate|"
        r"rider|add.on"
        r")\b"
    )
    if _INSURANCE_INDICATORS.search(q):
        return True

    # ── Off-topic indicators ──────────────────────────────────────────────
    # These patterns only apply if the query has NO insurance vocabulary at
    # all.  Each sub-pattern uses \b word boundaries and \s+ for whitespace
    # between words (avoids trailing-space issues).
    _OFF_TOPIC_PATTERNS = re.compile(
        r"(?:"
        r"\b(?:who\s+is|who\s+was|who\s+are|when\s+was|when\s+did|when\s+is|where\s+is|where\s+was)\b|"
        r"\b(?:history\s+of|definition\s+of)\b|"
        r"\b(?:mother\s+of|father\s+of)\b|"
        r"\b(?:born\s+in|died\s+in|capital\s+of|population\s+of)\b|"
        r"\bchatgpt\b|\bclaude\b|\bgpt-4\b|"
        r"\brecipe\b|\bhow\s+to\s+cook\b|\bingredients\b|"
        r"\bhow\s+to\s+play\b|\brules\s+of\b|\bsoccer\b|\bfootball\b|\bcricket\b|\bbasketball\b|"
        r"\bmovie\b|\bactor\b|\bactress\b|\bsinger\b|\bsong\b|\balbum\b|"
        r"\bpython\b|\bjavascript\b|\bjava\b|\bc\+\+\b|\bprogramming\b|\bcode\b|\balgorithm\b|"
        r"\bweather\b|\btemperature\b|\bforecast\b|"
        r"\btranslate\b"
        r")"
    )
    if _OFF_TOPIC_PATTERNS.search(q):
        return False

    # For queries that don't match insurance indicators and don't match
    # off-topic patterns, fall back to generic question patterns combined
    # with insurance-adjacent words.

    # ── Generic question patterns (insurance-adjacent) ─────────────────────
    _GENERIC_INSURANCE_PATTERNS = re.compile(
        r"\b("
        r"what (?:are|is|does|about)|"
        r"how (?:much|many|does|can|to|do)|"
        r"can (?:i|we|you)|"
        r"do (?:i|we|you)|"
        r"tell me about|explain|"
        r"benefits|features|details|"
        r"am i|is it|will it|"
        r"recommend|suggest|"
        r"best (?:for|option|plan|policy|)"
        r")\b"
    )
    # Only count generic patterns if they contain at least one insurance-adjacent word
    _INSURANCE_ADJACENT = re.compile(
        r"\b(cover|protect|risk|plan|option|policy|benefit|pay|cost|fee|charge|"
        r"amount|document|upload|file|paper|letter|receipt)"
        r"\b"
    )
    if _GENERIC_INSURANCE_PATTERNS.search(q) and _INSURANCE_ADJACENT.search(q):
        return True

    # Default: when in doubt, assume it IS insurance-related (better to let the
    # retrieval similarity decide than to falsely mark as off-topic).
    return True


